INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH0' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI11')), 'B0', 'Chương mở đầu', 1, 1, $JSON$
{
  "content": [
    "VŨ VĂN HÙNG (Tổng Chủ biên)",
    "NGUYỄN VĂN BIÊN (Chủ biên)",
    "NGUYỄN CHÍNH CƯƠNG – PHẠM KIM CHUNG – TÔ GIANG",
    "ĐẶNG THANH HẢI – VŨ THÚY HẰNG – BÙI GIA THỊNH",
    "",
    "KẾT NỐI TRI THỨC VỚI CUỘC SỐNG",
    "",
    "**VẬT LÍ 11**",
    "",
    "[Hình nền: Đồ thị sóng dao động với nhiều màu sắc rực rỡ]",
    "",
    "NHÀ XUẤT BẢN GIÁO DỤC VIỆT NAM",
    "(Logo GD, Logo Nhà xuất bản Giáo dục Việt Nam Bản Mẫu)",
    "**Hội đồng Quốc gia thẩm định sách giáo khoa môn Vật lí lớp 11**",
    "ĐỖ HƯƠNG TRÀ (Chủ tịch) – NGUYỄN ANH THUẤN (Phó Chủ tịch)",
    "NGUYỄN VĂN NGHIỆP (Thư kí) – PHÙNG VIỆT HẢI",
    "NGUYỄN QUANG LINH – PHẠM ĐÌNH MẪN – MAI HOÀNG PHƯƠNG",
    "NGÔ THỊ QUYÊN – NGUYỄN VŨ ÁNH TUYẾT",
    "",
    "[Logo KẾT NỐI TRI THỨC VỚI CUỘC SỐNG]",
    "VŨ VĂN HÙNG (Tổng Chủ biên)",
    "NGUYỄN VĂN BIÊN (Chủ biên)",
    "NGUYỄN CHÍNH CƯƠNG – PHẠM KIM CHUNG – TÔ GIANG",
    "ĐẶNG THANH HẢI – VŨ THÚY HẰNG – BÙI GIA THỊNH",
    "",
    "**VẬT LÍ 11**",
    "",
    "[Logo KẾT NỐI TRI THỨC VỚI CUỘC SỐNG]",
    "",
    "(Logo Nhà xuất bản Giáo dục Việt Nam Bản Mẫu)",
    "",
    "NHÀ XUẤT BẢN GIÁO DỤC VIỆT NAM",
    "**HƯỚNG DẪN SỬ DỤNG SÁCH**",
    "",
    "Sách giáo khoa Vật lí 11 gồm 4 chương. Mỗi chương gồm một số bài học. Mỗi bài học là một chuỗi các nội dung kiến thức và nhiệm vụ học tập, cụ thể như sau:",
    "",
    "**Khởi động**",
    "Tiếp cận bài mới bằng sự tò mò, hứng thú học tập.",
    "",
    "**Đọc hiểu**",
    "Cung cấp hiện tượng, dữ liệu ban đầu, thuật ngữ cần thiết để tiến hành hoạt động tìm tòi, khám phá kiến thức tiếp theo.",
    "",
    "**? Câu hỏi**",
    "Câu hỏi sẽ giúp học sinh:",
    "– Tìm tòi, khám phá kiến thức.",
    "– Vận dụng kiến thức để giải bài tập.",
    "",
    "**Hoạt động**",
    "Tiến hành các hoạt động giúp học sinh giải quyết các vấn đề học tập và đồng thời phát triển các năng lực cần thiết.",
    "",
    "**! Những điều cần lưu ý.**",
    "",
    "**EM ĐÃ HỌC**",
    "Tổng kết kiến thức và kĩ năng cơ bản của bài.",
    "",
    "**EM CÓ THỂ**",
    "Yêu cầu về năng lực vận dụng kiến thức vào học tập và thực tiễn cuộc sống.",
    "",
    "**EM CÓ BIẾT**",
    "Mở rộng kiến thức của bài.",
    "",
    "Hoạt động trải nghiệm yêu cầu học sinh vận dụng kiến thức, kĩ năng đã học vào một số tình huống của thực tế cuộc sống.",
    "",
    "---",
    "*Hãy bảo quản, giữ gìn sách giáo khoa*",
    "*để dành tặng các em học sinh lớp sau!*",
    "---",
    "",
    "2",
    "**LỜI NÓI ĐẦU**",
    "",
    "Sách giáo khoa *Vật lí 11* với thông điệp *kết nối tri thức với cuộc sống* được biên soạn theo định hướng đổi mới giáo dục phổ thông nhằm phát triển phẩm chất, năng lực của người học. Tư tưởng chủ đạo trong việc biên soạn sách giáo khoa này là tổ chức các hoạt động học tập nhằm coi trọng việc phát triển phẩm chất, năng lực học sinh nhưng không coi nhẹ vai trò của kiến thức. Kiến thức trong sách giáo khoa *Vật lí 11* được coi là chất liệu làm cơ sở giúp học sinh hình thành và phát triển các phẩm chất và năng lực cần có trong cuộc sống hiện tại và tương lai.",
    "",
    "Sách giáo khoa *Vật lí 11* không phải là cuốn sách trình bày sẵn các nội dung kiến thức cần học mà là cuốn sách hướng dẫn học sinh hoạt động để tìm tòi, khám phá ra kiến thức mới, vận dụng chúng vào việc giải quyết các vấn đề trong học tập và cuộc sống. Thông qua các hoạt động học tập này, các em không những hình thành và phát triển các năng lực khoa học nói chung và vật lí nói riêng mà còn đồng thời hình thành và phát triển được các năng lực chung như năng lực tự chủ và tự học, giao tiếp và hợp tác, giải quyết vấn đề và sáng tạo,...",
    "",
    "Sách giáo khoa *Vật lí 11* coi trọng phương pháp thực nghiệm, phần lớn kiến thức cơ bản của cuốn sách được tổ chức và trình bày theo phương pháp thực nghiệm. Việc coi trọng phương pháp thực nghiệm còn được thể hiện ở hệ thống các bài thí nghiệm thực hành từ đơn giản đến phức tạp, từ cổ điển đến hiện đại, tạo điều kiện cho các em tìm hiểu các thuộc tính của các đối tượng vật lí dưới nhiều góc nhìn khác nhau. Sách giáo khoa *Vật lí 11* trình bày các bài tập đan xen vào các hoạt động tương ứng trong bài.",
    "",
    "Các tác giả mong muốn sách giáo khoa *Vật lí 11* sẽ mang đến cho các em niềm vui và sự đam mê trong học tập môn Vật lí để có kết quả học tập tốt môn học này, không những giúp các em hiểu rõ hơn về thế giới tự nhiên mà còn góp phần giúp các em thấy được năng lực và sở trường của bản thân để bắt đầu định hướng nghề nghiệp, có kế hoạch học tập nhằm đáp ứng các yêu cầu hướng nghiệp của mình.",
    "",
    "CÁC TÁC GIẢ",
    "",
    "3",
    "**MỤC LỤC**",
    "",
    "| | Trang |",
    "|---|---|",
    "| **Chương 1. DAO ĐỘNG** | **5** |",
    "| Bài 1. Dao động điều hoà | 6 |",
    "| Bài 2. Mô tả dao động điều hoà | 10 |",
    "| Bài 3. Vận tốc, gia tốc trong dao động điều hoà | 14 |",
    "| Bài 4. Bài tập về dao động điều hoà | 17 |",
    "| Bài 5. Động năng. Thế năng. Sự chuyển hoá giữa động năng và thế năng trong dao động điều hoà | 20 |",
    "| Bài 6. Dao động tắt dần. Dao động cưỡng bức. Hiện tượng cộng hưởng | 24 |",
    "| Bài 7. Bài tập về sự chuyển năng lượng trong dao động điều hoà | 28 |",
    "| **Chương 2. SÓNG** | **31** |",
    "| Bài 8. Mô tả sóng | 32 |",
    "| Bài 9. Sóng ngang, sóng dọc, sự truyền năng lượng của sóng cơ | 37 |",
    "| Bài 10. Thực hành: Đo tần số của sóng âm | 41 |",
    "| Bài 11. Sóng điện từ | 44 |",
    "| Bài 12. Giao thoa sóng | 48 |",
    "| Bài 13. Sóng dừng | 52 |",
    "| Bài 14. Bài tập về sóng | 55 |",
    "| Bài 15. Thực hành: Đo tốc độ truyền âm | 58 |",
    "| **Chương 3. ĐIỆN TRƯỜNG** | **60** |",
    "| Bài 16. Lực tương tác giữa hai điện tích | 61 |",
    "| Bài 17. Khái niệm điện trường | 65 |",
    "| Bài 18. Điện trường đều | 71 |",
    "| Bài 19. Thế năng điện | 76 |",
    "| Bài 20. Điện thế | 79 |",
    "| Bài 21. Tụ điện | 83 |",
    "| **Chương 4. DÒNG ĐIỆN. MẠCH ĐIỆN** | **90** |",
    "| Bài 22. Cường độ dòng điện | 91 |",
    "| Bài 23. Điện trở. Định luật Ohm | 95 |",
    "| Bài 24. Nguồn điện | 102 |",
    "| Bài 25. Năng lượng điện và công suất điện | 106 |",
