INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH1' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI11')), 'B1', 'Dao động điều hoà', 7, 1, $JSON$
{
  "content": [
    "# CHƯƠNG I DAO ĐỘNG",
    "",
    "Những người tham gia chơi đu có thể có khối lượng khác nhau. Thời gian thực hiện một chuyển động qua lại có khác nhau hay không?",
    "[Hình ảnh các bạn học sinh đang chơi xích đu bằng tre ở bãi cỏ]",
    "",
    "**Nội dung**",
    "- Dao động điều hoà.",
    "- Mô tả dao động điều hoà.",
    "- Vận tốc, gia tốc trong dao động điều hoà.",
    "- Động năng. Thế năng. Sự chuyển hoá giữa động năng và thế năng trong dao động điều hoà.",
    "- Dao động tắt dần. Dao động cưỡng bức. Hiện tượng cộng hưởng.",
    "",
    "5",
    "# Bài 1 DAO ĐỘNG ĐIỀU HOÀ",
    "",
    "**Khởi động:**",
    "*Trong cuộc sống hằng ngày và trong kĩ thuật ta thường gặp những vật dao động, ví dụ như dây đàn ghi ta rung động, chiếc đu đung đưa, pít-tông chuyển động lên xuống trong xi lanh của động cơ,... Chuyển động của những vật này được gọi là dao động cơ. Vậy dao động cơ có những đặc điểm gì chung?*",
    "[Hình ảnh người chơi ghi ta, bé gái chơi xích đu hình chữ A, cấu tạo bên trong của pít-tông động cơ]",
    "",
    "## I. NHỮNG ĐẶC ĐIỂM CỦA DAO ĐỘNG CƠ",
    "**1. Thí nghiệm**",
    "**Hoạt động:**",
    "*Chuẩn bị:*",
    "Sử dụng con lắc lò xo hoặc con lắc đơn (Hình 1.1).",
    "*Tiến hành:*",
    "Treo một vật nhỏ, nặng vào đầu tự do của một lò xo nhẹ (Hình 1.1a) hoặc một dây nhẹ không dãn ta có con lắc lò xo hoặc con lắc đơn (Hình 1.1b).",
    "1. Xác định vị trí cân bằng của vật.",
    "2. Kéo vật lệch khỏi vị trí cân bằng rồi thả ra cho chuyển động. Quan sát chuyển động của mỗi vật và cho nhận xét về đặc điểm chung của chúng.",
    "[Hình 1.1. Con lắc lò xo và con lắc đơn. a) Lò xo treo quả cầu. b) Dây treo quả cầu]",
    "",
    "**? Câu hỏi:**",
    "Nêu những ví dụ về dao động cơ mà em biết.",
    "",
    "**2. Dao động cơ**",
    "Vật chuyển động qua lại quanh vị trí cân bằng. Chuyển động như vậy gọi là *dao động cơ*.",
    "Dao động cơ của một vật có thể là *tuần hoàn* hoặc không tuần hoàn. Nếu sau những khoảng thời gian bằng nhau, vật trở lại vị trí cũ theo hướng cũ thì dao động của vật đó là tuần hoàn. Ví dụ: Dao động của con lắc đồng hồ là tuần hoàn, dao động của cành cây đu đưa khi gió thổi là không tuần hoàn.",
    "Dao động tuần hoàn có thể có mức độ phức tạp khác nhau. Dao động tuần hoàn đơn giản nhất là *dao động điều hoà*.",
    "",
    "6",
    "CHƯƠNG I – DAO ĐỘNG ĐIỀU HOÀ",
    "",
    "## II. DAO ĐỘNG ĐIỀU HOÀ",
    "**1. Đồ thị của dao động điều hoà**",
    "Ta hãy quan sát dao động của một con lắc lò xo dọc theo trục x thẳng đứng tại các thời điểm khác nhau như Hình 1.2. Gọi t = 0 là thời điểm bắt đầu quan sát, x = 0 là vị trí cân bằng của quả cầu.",
    "[Hình 1.2. Đồ thị dao động của con lắc lò xo. Trục tung x(cm), trục hoành t(s). Các vị trí của quả nặng được nối lại tạo thành đường hình sin]",
    "Đường cong trên Hình 1.2 là đồ thị dao động của con lắc. Nó cho biết vị trí của quả cầu trên trục x tại những thời điểm khác nhau. Đường cong này có dạng *hình sin*.",
    "",
    "**2. Phương trình của dao động điều hoà**",
    "Tương ứng với đồ thị hình sin trên là hàm sin hoặc cosin.",
    "Ta chọn:",
    "$x = A\\cos(\\omega t + \\varphi)$ (1.1)",
    "là hàm tương ứng với đồ thị Hình 1.2, còn được gọi là phương trình của dao động điều hoà.",
    "Trong phương trình này A, $\\omega$ và $\\varphi$ là các hằng số.",
    "- $x$ *là li độ dao động.*",
    "- $A$ *là biên độ dao động.*",
    "- $(\\omega t + \\varphi)$ *là pha của dao động ở thời điểm t.*",
    "- $\\varphi$ *là pha ban đầu.*",
    "Dao động được mô tả bằng phương trình $x = A\\cos(\\omega t + \\varphi)$ gọi là *dao động điều hoà*. Vật nặng của con lắc đang dao động điều hoà gọi là vật dao động điều hoà.",
    "",
    "**? Câu hỏi:**",
    "Một vật dao động điều hoà có phương trình",
    "$x = 2\\cos(4\\pi t + \\frac{\\pi}{2}) \\text{ (cm)}$",
    "Hãy xác định:",
    "a) Biên độ và pha ban đầu của dao động.",
    "b) Pha và li độ của dao động khi t = 2 s.",
    "",
    "7",
    "CHƯƠNG I – DAO ĐỘNG ĐIỀU HOÀ",
    "",
    "**Hoạt động:**",
    "Đồ thị li độ - thời gian của một con lắc đơn dao động điều hoà được mô tả trên Hình 1.3.",
    "1. Hãy mô tả dao động điều hoà của con lắc đơn.",
    "2. Xác định biên độ và li độ của con lắc ở các thời điểm t = 0, t = 0,5 s, t = 2,0 s.",
    "[Hình 1.3. Đồ thị li độ - thời gian của con lắc đơn. Trục tung x(cm) từ -40 đến 40. Trục hoành t(s) từ 0 đến 3,0. Tại t=0, x=40; t=1,0, x=-40; t=2,0, x=40]",
    "",
    "**? Câu hỏi:**",
    "Pít-tông của một động cơ đốt trong dao động trên một đoạn thẳng dài 16 cm và làm cho trục khuỷu của động cơ quay đều (Hình 1.5). Xác định biên độ dao động của một điểm trên mặt pít-tông.",
    "[Hình 1.5. Pít-tông và trục khuỷu của động cơ]",
    "",
    "**EM CÓ BIẾT?**",
    "Người ta tạo ra dao động điều hoà của một con lắc đơn với biên độ dao động nhỏ (góc lệch cực đại $\\alpha_0 \\le 10^\\circ$) bằng cách kết nối cảm biến khoảng cách với máy tính để xác định vị trí của vật dao động (Hình 1.4). Trên màn hình máy tính cho đồ thị của dao động là dạng hình sin.",
    "[Hình 1.4. Thiết bị thí nghiệm. Con lắc đơn dao động trước cảm biến khoảng cách kết nối dao động kí]",
    "",
    "**EM CÓ BIẾT?**",
    "Mối liên hệ giữa dao động điều hoà và chuyển động tròn đều.",
    "Điểm M chuyển động tròn đều với tốc độ góc $\\omega$. Gọi Q là hình chiếu của M trên trục Ox (Hình 1.6). Điểm Q dao động điều hoà với phương trình:",
    "$x = OM \\cos(\\omega t + \\varphi)$",
    "Ta có thể làm thí nghiệm để xác nhận mối liên hệ này:",
    "[Hình 1.6. Mối liên hệ chuyển động tròn đều và dao động điều hoà]",
    "Ban đầu cho con lắc lò xo dao động theo phương thẳng đứng. Tiếp sau, điều chỉnh mô tơ sao cho khi mô tơ bắt đầu quay thì bóng của vật hình trụ trùng với bóng của con lắc trên màn và khi mô tơ quay được một vòng thì quả cầu cũng thực hiện được một dao động (Hình 1.7).",
    "",
    "8",
    "CHƯƠNG I – DAO ĐỘNG ĐIỀU HOÀ",
    "",
    "Quan sát thí nghiệm cho thấy khi vật hình trụ gắn ở đầu một thanh quay tròn đều dưới ánh sáng của chiếc đèn chiếu thì bóng của đầu vật hình trụ và của quả cầu của con lắc trên màn luôn trùng nhau và dao động quanh vị trí cân bằng O.",
    "",
    "[Hình 1.7. Thí nghiệm minh hoạ mối liên hệ giữa dao động của con lắc lò xo và chuyển động tròn đều. Ánh sáng chiếu vào vật hình trụ trên thanh quay và con lắc lò xo tạo bóng trên màn. Bóng của chúng trùng nhau]",
    "",
    "**EM ĐÃ HỌC**",
    "- Dao động điều hoà là dao động trong đó li độ của vật là một hàm cosin (hay sin) của thời gian.",
    "- Phương trình của dao động điều hoà là $x = A \\cos(\\omega t + \\varphi)$, trong đó: x là li độ; A là biên độ; $\\varphi$ là pha ban đầu.",
    "",
    "**EM CÓ THỂ**",
    "- Xác định được biên độ của pít-tông chuyển động trong xi lanh của động cơ đốt trong.",
    "- Mô tả được dao động điều hoà của con lắc đồng hồ.",
    "",
    "9"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH1' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI11')), 'B2', 'Mô tả dao động điều hoà', 12, 2, $JSON$
{
  "content": [
    "# Bài 2 MÔ TẢ DAO ĐỘNG ĐIỀU HOÀ",
    "",
    "**Khởi động:**",
    "*Để vẽ đồ thị hoặc viết phương trình của một dao động điều hoà cần biết những đại lượng vật lí nào?*",
    "",
    "## I. CÁC ĐẠI LƯỢNG ĐẶC TRƯNG CỦA DAO ĐỘNG ĐIỀU HOÀ",
    "Từ đồ thị và phương trình của dao động điều hoà ở Bài 1 ta có thể xác định được các đại lượng dùng để mô tả dao động điều hoà.",
    "- Li độ: x là độ dịch chuyển từ vị trí cân bằng đến vị trí của vật tại thời điểm t.",
    "- Biên độ: A là độ dịch chuyển cực đại của vật tính từ vị trí cân bằng.",
    "- Chu kì: là khoảng thời gian để vật thực hiện được một dao động, kí hiệu là T.",
    "Đơn vị của chu kì dao động là giây (s).",
    "- Tần số: là số dao động mà vật thực hiện được trong một giây, kí hiệu là f.",
    "Ta có:",
    "$f = \\frac{1}{T}$ (2.1)",
    "Đơn vị của tần số là $\\frac{1}{s}$, gọi là héc (kí hiệu là Hz).",
    "- Tần số góc",
    "Theo đồ thị Hình 2.1 cứ sau mỗi chu kì thì dao động của vật lại lặp lại như cũ. Như vậy, theo phương trình dao động ta phải có:",
    "$x = A \\cos[\\omega(t + T)] = A \\cos\\omega t$",
    "Theo tính chất của hàm cosin ta suy ra:",
    "$\\omega T = 2\\pi$ hay $\\omega = \\frac{2\\pi}{T}$ (rad/s) (2.2)",
    "Đại lượng $\\omega$ được gọi là *tần số góc*.",
    "Trong dao động điều hoà của mỗi vật thì bốn đại lượng biên độ, chu kì, tần số và tần số góc là những đại lượng không đổi, không phụ thuộc vào thời điểm quan sát. *Với các vật khác nhau thì các đại lượng này khác nhau. Vì thế chúng là những đại lượng đặc trưng cho dao động điều hoà.*",
    "",
    "**? Câu hỏi:**",
    "Hình 2.1 là đồ thị dao động điều hoà của một vật.",
    "[Hình 2.1. Đồ thị x-t]",
    "Hãy xác định:",
    "- Biên độ, chu kì, tần số của dao động.",
    "- Nêu thời điểm mà vật có li độ x = 0; x = 0,1 m.",
    "",
    "**? Câu hỏi:**",
    "Từ Hình 2.1 hãy xác định tần số góc của dao động của vật.",
    "",
    "10",
    "CHƯƠNG I – DAO ĐỘNG ĐIỀU HOÀ",
    "",
    "## II. PHA BAN ĐẦU. ĐỘ LỆCH PHA",
    "**1. Pha ban đầu**",
    "Hình 2.2 là đồ thị của hai vật dao động điều hoà cùng chu kì, cùng biên độ nhưng dao động 1 luôn đạt tới giá trị cực đại sớm hơn dao động 2 một thời gian là $\\frac{T}{4}$.",
    "Từ đồ thị ta thấy, tại thời điểm ban đầu (t = 0) vật dao động điều hoà 1 đang ở vị trí biên x = A và sẽ dịch chuyển về vị trí cân bằng, còn vật dao động điều hoà 2 đang ở vị trí cân bằng và sẽ dịch chuyển về phía x > 0.",
    "Các phương trình dao động tương ứng với đồ thị Hình 2.2 có pha ban đầu $\\varphi$ lần lượt là:",
    "$x_1 = A \\cos(\\omega t)$ với $\\varphi_1 = 0$",
    "$x_2 = A \\cos(\\omega t - \\frac{\\pi}{2})$ với $\\varphi_2 = -\\frac{\\pi}{2}$",
    "Như vậy, pha ban đầu $\\varphi$ cho biết tại thời điểm bắt đầu quan sát vật dao động điều hoà ở đâu và sẽ đi về phía nào. Nó có giá trị nằm trong khoảng từ $-\\pi$ đến $\\pi$ (rad).",
    "",
    "[Hình 2.2. Đồ thị dao động của hai vật. Vật 1 đường màu đỏ, vật 2 đường màu xanh]",
    "",
    "**? Câu hỏi:**",
    "Hình 2.3 là đồ thị dao động điều hoà của một con lắc.",
    "[Hình 2.3. Đồ thị dao động của một con lắc]",
    "Hãy cho biết:",
    "- Vị trí và hướng dịch chuyển của con lắc tại thời điểm ban đầu.",
    "- Pha ban đầu của dao động.",
    "",
    "**2. Độ lệch pha giữa hai dao động cùng chu kì**",
    "Đồ thị Hình 2.2 còn cho thấy tại bất kì thời điểm nào thì độ lệch pha giữa hai dao động trên cũng bằng $\\frac{\\pi}{2}$.",
    "Trong khoa học và trong kĩ thuật, *độ lệch pha quan trọng hơn pha*, vì nó là đại lượng không đổi, không phụ thuộc vào thời điểm quan sát.",
    "Nếu $\\varphi_1 > \\varphi_2$ thì dao động 1 sớm pha hơn dao động 2.",
    "Nếu $\\varphi_1 < \\varphi_2$ thì dao động 1 trễ pha hơn dao động 2.",
    "Nếu $\\varphi_1 = \\varphi_2$ thì dao động 1 cùng (đồng) pha với dao động 2.",
    "Nếu $\\varphi_1 = \\varphi_2 \\pm \\pi$ thì dao động 1 ngược pha với dao động 2.",
    "",
    "**? Câu hỏi:**",
    "Hãy chứng minh rằng độ lệch pha giữa hai dao động cùng chu kì bằng độ lệch pha ban đầu.",
    "",
    "[Hình 2.4.",
    "a) Hai dao động đồng pha.",
    "b) Hai dao động ngược pha]",
    "",
    "11",
    "CHƯƠNG I – DAO ĐỘNG ĐIỀU HOÀ",
    "",
    "**? Câu hỏi:**",
    "Hai con lắc 1 và 2 dao động điều hoà tại cùng thời điểm quan sát vị trí của chúng được biểu diễn trên Hình 2.5 a, b. Hỏi dao động của con lắc nào sớm pha hơn và sớm hơn bao nhiêu?",
    "[Hình 2.5. Hai con lắc lò xo. a) Con lắc 1 ở vị trí biên dương. b) Con lắc 2 ở vị trí cân bằng và đang đi theo chiều dương]",
    "",
    "## III. BÀI TẬP VÍ DỤ VỀ CÁC ĐẠI LƯỢNG ĐẶC TRƯNG CỦA DAO ĐỘNG ĐIỀU HOÀ",
    "*Ví dụ 1:* Đồ thị li độ - thời gian của một vật dao động điều hoà được mô tả trên Hình 2.6.",
    "a) Xác định biên độ, chu kì, tần số, tần số góc, pha ban đầu và viết phương trình của dao động.",
    "b) Xác định pha của dao động tại thời điểm t = 2,5 s.",
    "[Hình 2.6. Đồ thị dao động. Trục tung x(cm) từ -20 đến 20, trục hoành t(s)]",
    "*Giải:*",
    "a) Từ đồ thị ta xác định được:",
    "Biên độ: A = 20 cm; chu kì T = 2,5 - 0,5 = 2,0 s.",
    "Áp dụng công thức: $\\omega = \\frac{2\\pi}{T} = 2\\pi f \\Rightarrow \\omega = \\pi$ (rad/s); f = 0,5 Hz.",
    "Khi t = 0, $x = A \\cos\\varphi \\Rightarrow \\cos\\varphi = 1 \\Rightarrow \\varphi = 0$ (rad).",
    "Do đó phương trình dao động của vật được viết: $x = 20 \\cos(\\pi t)$ (cm).",
    "b) Từ phương trình dao động ta có: $\\varphi = \\pi t + \\frac{\\pi}{2}$, thay t = 2,5 s vào suy ra $\\varphi = 3\\pi$ (rad)",
    "*(Chú ý: Trong sách giải bước b bị lỗi in, ghi phương trình là $\\varphi = \\pi t + \\frac{\\pi}{2}$ nhưng thực chất pha dao động là $\\Phi = \\omega t + \\varphi = \\pi t + 0 = \\pi t$. Thay t = 2,5s thì pha là $2,5\\pi$. Trong sách ghi kết quả $3\\pi$ là sai số hoặc sai phương trình. Trích xuất theo nguyên bản: $\\varphi = \\pi t + \\frac{\\pi}{2}$, thay t = 2,5 s vào suy ra $\\varphi = 3\\pi$ (rad))*",
    "",
    "*Ví dụ 2:* Hai vật dao động điều hoà A và B có cùng tần số nhưng lệch pha nhau được mô tả trên Hình 2.7.",
    "a) Xác định li độ của B khi A có li độ cực đại.",
    "b) Xác định li độ của A khi B có li độ cực đại.",
    "c) Hãy cho biết A hay B đạt tới li độ cực đại trước (không kể thời điểm t = 0).",
    "d) Xác định độ lệch pha của dao động A so với dao động B.",
    "[Hình 2.7. Đồ thị của hai dao động A và B]",
    "*Giải:*",
    "Từ đồ thị, cho thấy:",
    "a) Khi A có li độ cực đại thì B có li độ x = 0.",
    "b) Khi B có li độ cực đại thì A có li độ x = 0.",
    "c) A có li độ cực đại trước B.",
    "d) Dao động A sớm pha $\\frac{\\pi}{2}$ so với dao động B.",
    "",
    "12",
    "CHƯƠNG I – DAO ĐỘNG ĐIỀU HOÀ",
    "",
    "**Hoạt động:**",
    "1. Xét một vật dao động điều hoà có biên độ 10 cm, tần số 5 Hz. Tại thời điểm ban đầu (t = 0) vật có li độ cực đại theo chiều dương.",
    "- Xác định chu kì, tần số góc, pha ban đầu của dao động.",
    "- Viết phương trình và vẽ đồ thị (x - t) của dao động.",
    "2. Cho hai con lắc đơn dao động điều hoà. Biết phương trình dao động của con lắc thứ nhất là",
    "$x = 20\\cos(20\\pi t + \\frac{\\pi}{2})$ (cm). Con lắc thứ hai có cùng biên độ và tần số nhưng lệch về thời gian so với con lắc thứ nhất một phần tư chu kì. Viết phương trình dao động của con lắc thứ hai.",
    "",
    "**? Câu hỏi:**",
    "1. Đại lượng nào dưới đây đặc trưng cho độ lệch về thời gian giữa hai dao động điều hoà cùng chu kì?",
    "A. Li độ.",
    "B. Pha.",
    "C. Pha ban đầu.",
    "D. Độ lệch pha.",
    "2. Hãy chứng minh rằng độ lệch pha giữa hai dao động điều hoà cùng tần số là đại lượng không đổi và bằng độ lệch pha ban đầu.",
    "",
    "**EM ĐÃ HỌC**",
    "- Chu kì T là khoảng thời gian để vật thực hiện một dao động.",
    "Đơn vị của chu kì là giây (s).",
    "- Tần số f là số dao động mà vật thực hiện được trong một giây.",
    "Đơn vị của tần số là một trên giây (1/s), gọi là héc (kí hiệu là Hz).",
    "- Trong dao động điều hoà, giữa tần số góc $\\omega$, chu kì T và tần số f có mối liên hệ:",
    "$\\omega = \\frac{2\\pi}{T} = 2\\pi f$.",
    "Đơn vị của tần số góc là radian trên giây (rad/s).",
    "- Độ lệch pha giữa hai dao động điều hoà cùng chu kì luôn bằng độ lệch pha ban đầu.",
    "",
    "**EM CÓ THỂ**",
    "- Dùng đồ thị li độ - thời gian có dạng hình sin hoặc phương trình của dao động điều hoà để xác định các đại lượng như biên độ chu kì, tần số, tần số góc và pha ban đầu của dao động đó.",
    "- Biết cách xác định độ lệch pha giữa hai dao động điều hoà cùng chu kì.",
    "",
    "13"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH1' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI11')), 'B3', 'Vận tốc, gia tốc trong dao động điều hoà', 16, 3, $JSON$
{
  "content": [
    "# Bài 3 VẬN TỐC, GIA TỐC TRONG DAO ĐỘNG ĐIỀU HOÀ",
    "",
    "**Khởi động:**",
    "*Ta có thể dựa vào đồ thị (x - t) của dao động điều hoà để xác định vận tốc và gia tốc của vật được không?*",
    "",
    "## I. VẬN TỐC CỦA VẬT DAO ĐỘNG ĐIỀU HOÀ",
    "Như đã biết, vận tốc tức thời của một vật được xác định bằng công thức:",
    "$v = \\frac{\\Delta x}{\\Delta t}$ (với $\\Delta t$ rất nhỏ), tức là bằng độ dốc của đồ thị (x - t) tại điểm đang xét.",
    "Để đơn giản, ta hãy xét một vật dao động điều hoà có đồ thị (x - t) được chỉ trên Hình 3.1. Ta nhận thấy độ dốc của đồ thị, tức vận tốc của vật, có giá trị cực đại khi ở vị trí cân bằng rồi giảm dần đến 0 khi vật ra đến vị trí biên. Sau đó độ dốc của đồ thị lại tăng dần đến giá trị cực đại khi vật về đến vị trí cân bằng.",
    "[Hình 3.1. Đồ thị (x - t) của một vật dao động điều hoà ($\\varphi = 0$)]",
    "",
    "**1. Phương trình của vận tốc**",
    "Khi học phép tính đạo hàm chúng ta sẽ biết",
    "$v = \\frac{\\Delta x}{\\Delta t}$ (với $\\Delta t$ rất nhỏ) chính là đạo hàm của li độ x theo thời gian, kí hiệu là x'.",
    "$x = A \\cos(\\omega t + \\varphi)$",
    "$v = x' = -\\omega A \\sin(\\omega t + \\varphi)$ (3.1)",
    "Công thức (3.1) là phương trình của vận tốc, có thể biến đổi như sau:",
    "$v = \\omega A \\sqrt{1 - \\cos^2(\\omega t + \\varphi)}$",
    "Thay $x = A \\cos(\\omega t + \\varphi)$ vào ta được:",
    "$v = \\pm \\omega \\sqrt{A^2 - x^2}$ (3.2)",
    "- Khi vật ở vị trí cân bằng thì $v = \\pm \\omega A$.",
    "- Khi vật ở vị trí biên thì $v = 0$.",
    "",
    "**2. Đồ thị của vận tốc**",
    "Hình 3.2 là đồ thị của vận tốc của một dao động điều hoà với $\\varphi = 0$. Nó cũng là một đường hình sin.",
    "[Hình 3.2. Đồ thị (v - t) của một vật dao động điều hoà ($\\varphi = 0$)]",
    "",
    "**Hoạt động:**",
    "Đặt một thước kẻ (loại 20 cm) cho mép của thước tiếp xúc với đồ thị li độ - thời gian (Hình 3.1) ở một số điểm C, D, E, G, H. Từ độ dốc của thước hãy so sánh độ lớn vận tốc của vật tại các điểm C, E, H.",
    "",
    "14",
    "CHƯƠNG I – DAO ĐỘNG ĐIỀU HOÀ",
    "",
    "**? Câu hỏi:**",
    "1. So sánh đồ thị của vận tốc (Hình 3.2) với đồ thị của li độ (Hình 3.1), hãy cho biết vận tốc sớm pha hay trễ pha bao nhiêu so với li độ.",
    "2. Trong các khoảng thời gian từ 0 đến $\\frac{T}{4}$, từ $\\frac{T}{4}$ đến $\\frac{T}{2}$, từ $\\frac{T}{2}$ đến $\\frac{3T}{4}$, từ $\\frac{3T}{4}$ đến T, vận tốc của dao động điều hoà thay đổi như thế nào?",
    "",
    "## II. GIA TỐC CỦA VẬT DAO ĐỘNG ĐIỀU HOÀ",
    "Tương tự như vận tốc, gia tốc tức thời của một vật được xác định bằng công thức:",
    "$a = \\frac{\\Delta v}{\\Delta t}$ (với $\\Delta t$ rất nhỏ), tức là bằng độ dốc của đồ thị vận tốc tại điểm đang xét. Ta nhận thấy độ dốc của đồ thị Hình 3.2, hay gia tốc của vật, có giá trị bằng 0 khi vật ở vị trí cân bằng, rồi tăng đến giá trị cực đại khi vật ở vị trí biên.",
    "",
    "**1. Phương trình của gia tốc**",
    "Như vậy, gia tốc tức thời của một vật là đạo hàm của vận tốc theo thời gian, kí hiệu là v'.",
    "$a = v' = -\\omega^2 A \\cos(\\omega t + \\varphi)$ (3.3)",
    "Công thức 3.3 là phương trình của gia tốc.",
    "Thay $x = A \\cos(\\omega t + \\varphi)$ vào (3.3) ta được:",
    "$a = -\\omega^2 x$ (3.4)",
    "Từ công thức (3.4) ta thấy:",
    "- Khi vật ở vị trí cân bằng a = 0.",
    "- Khi vật ở vị trí biên gia tốc có giá trị $a = \\pm \\omega^2 A$.",
    "",
    "**2. Đồ thị của gia tốc**",
    "Hình 3.3 là đồ thị của gia tốc (với $\\varphi = 0$), nó cũng là một đường hình sin như li độ và vận tốc.",
    "[Hình 3.3. Đồ thị (a - t) của một vật dao động điều hoà ($\\varphi = 0$)]",
    "",
    "**Hoạt động:**",
    "1. Dùng thước kẻ (loại 20 cm) để xác định xem trên đồ thị (v - t) Hình 3.2, tại thời điểm nào độ dốc của đồ thị bằng 0 và tại thời điểm nào độ dốc của đồ thị cực đại. Từ đó, so sánh độ lớn của gia tốc trên đồ thị (a - t) Hình 3.3 ở các thời điểm tương ứng.",
    "2. Phương trình dao động của một vật là $x = 5 \\cos 4\\pi t \\text{ (cm)}$. Hãy viết phương trình vận tốc, gia tốc và vẽ đồ thị li độ, vận tốc, gia tốc theo thời gian của vật.",
    "",
    "**? Câu hỏi:**",
    "1. So sánh đồ thị Hình 3.3 và Hình 3.1 ta có nhận xét gì về pha của li độ và gia tốc của một dao động.",
    "2. Trong các khoảng thời gian từ 0 đến $\\frac{T}{4}$, từ $\\frac{T}{4}$ đến $\\frac{T}{2}$, từ $\\frac{T}{2}$ đến $\\frac{3T}{4}$, từ $\\frac{3T}{4}$ đến T, gia tốc của dao động thay đổi như thế nào?",
    "",
    "15",
    "CHƯƠNG I – DAO ĐỘNG ĐIỀU HOÀ",
    "",
    "**? Câu hỏi:**",
    "1. Một vật dao động điều hoà trên trục Ox. Khi vật qua vị trí cân bằng thì tốc độ của nó là 20 cm/s. Khi vật có tốc độ là 10 cm/s thì gia tốc của nó có độ lớn là $40\\sqrt{3}$ cm/s$^2$. Tính biên độ dao động của vật.",
    "2. Hình 3.4 là đồ thị li độ – thời gian của một vật dao động điều hoà. Sử dụng đồ thị để tính các đại lượng sau:",
    "a) Tốc độ của vật ở thời điểm t = 0 s.",
    "b) Tốc độ cực đại của vật.",
    "c) Gia tốc của vật tại thời điểm t = 1,0 s.",
    "[Hình 3.4. Đồ thị x-t. Tại t=0, x=40; t=1,0, x=0; t=2,0, x=-40]",
    "",
    "**EM ĐÃ HỌC**",
    "- Phương trình của vận tốc và gia tốc của một vật dao động điều hoà có li độ là $x = A \\cos(\\omega t + \\varphi)$:",
    "$v = -\\omega A \\sin(\\omega t + \\varphi)$",
    "$a = -\\omega^2 A \\cos(\\omega t + \\varphi)$",
    "- Đồ thị của vận tốc, gia tốc theo thời gian là đường hình sin. Vận tốc của vật dao động sớm pha $\\frac{\\pi}{2}$ so với li độ, còn gia tốc của vật dao động ngược pha so với li độ.",
    "- Vectơ gia tốc luôn hướng về vị trí cân bằng và có độ lớn tỉ lệ với độ lớn của li độ.",
    "- Tại vị trí biên, vận tốc của vật bằng 0, còn gia tốc của vật có độ lớn cực đại. Tại vị trí cân bằng, gia tốc của vật bằng 0 còn vận tốc của vật có độ lớn cực đại.",
    "",
    "**EM CÓ THỂ**",
    "- Sử dụng được đồ thị mô tả dao động điều hoà thu được trên dao động kí có thể suy ra các đại lượng vận tốc, gia tốc của vật trong dao động điều hoà.",
    "",
    "16"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH1' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI11')), 'B4', 'Bài tập về dao động điều hoà', 19, 4, $JSON$
{
  "content": [
    "# Bài 4 BÀI TẬP VỀ DAO ĐỘNG ĐIỀU HOÀ",
    "",
    "**Khởi động:**",
    "*Khi biết phương trình hoặc đồ thị của vật dao động điều hoà, làm thế nào để xác định được vận tốc và gia tốc của vật?*",
    "",
    "## I. BÀI TẬP VÍ DỤ",
    "*Ví dụ 1:* Cho phương trình của một vật dao động điều hoà:",
    "$x = 5 \\cos(10\\pi t + \\frac{\\pi}{6}) \\text{ (cm)}$",
    "Xác định biên độ A, tần số f, pha ban đầu $\\varphi$, và li độ $x_1$ tại thời điểm $t_1 = 0,05 \\text{ s}$.",
    "*Giải:*",
    "So sánh phương trình dao động của vật với phương trình dạng cơ bản $x = A \\cos(\\omega t + \\varphi)$:",
    "Ta có:",
    "- Biên độ A = 5 cm",
    "- Tần số $f = \\frac{\\omega}{2\\pi} = \\frac{10\\pi}{2\\pi} = 5 \\text{ Hz}$",
    "- Pha ban đầu $\\varphi = \\frac{\\pi}{6} \\text{ (rad)}$",
    "- Li độ lúc $t_1$:",
    "$x_1 = 5 \\cos(10\\pi \\cdot 0,05 + \\frac{\\pi}{6}) = 5 \\cos(\\frac{4\\pi}{6}) = -2,5 \\text{ cm}$.",
    "",
    "**? Câu hỏi:**",
    "1. Nếu đề bài cho phương trình dao động không đúng dạng cơ bản $x = A \\cos(\\omega t + \\varphi)$ thì ta xác định pha ban đầu như thế nào?",
    "2. Có thể sử dụng mối liên hệ giữa dao động điều hoà và chuyển động tròn đều để xác định pha ban đầu, thời gian để vật đi từ điểm này đến điểm khác trong dao động điều hoà được không?",
    "",
    "*Ví dụ 2:* Một vật dao động điều hoà với tần số 2 Hz. Tại thời điểm ban đầu vật có li độ x = 5 cm và vận tốc v = -30 cm/s. Xác định:",
    "a) Biên độ và pha ban đầu của dao động.",
    "b) Giá trị cực đại của vận tốc và gia tốc của vật khi dao động.",
    "*Giải:*",
    "a) Tần số góc của dao động: $\\omega = 2\\pi f = 4\\pi \\text{ (rad/s)}$.",
    "Khi t = 0: $\\begin{cases} x_0 = A \\cos\\varphi = 5 \\text{ cm} \\\\ v_0 = -\\omega A \\sin\\varphi = -30 \\text{ cm/s} \\end{cases}$",
    "",
    "17",
    "CHƯƠNG I – DAO ĐỘNG ĐIỀU HOÀ",
    "",
    "Biên độ và pha ban đầu của dao động:",
    "$A = \\sqrt{x_0^2 + \\frac{v_0^2}{\\omega^2}} = \\sqrt{5^2 + \\frac{(-30)^2}{(4\\pi)^2}} \\approx 5,54 \\text{ cm}$",
    "$\\tan\\varphi = \\frac{-\\omega x_0}{v_0} = \\frac{-4\\pi \\cdot 5}{-30} = \\frac{2\\pi}{3} \\Rightarrow \\varphi \\approx 1,12 \\text{ rad}$",
    "*(Ghi chú: Trong sách in $\\frac{\\omega x_0}{v_0} = \\frac{30}{4\\pi\\cdot 5} = \\frac{3}{2\\pi} \\Rightarrow \\varphi \\approx 0,44 \\text{ rad}$ là sai công thức $\\tan\\varphi = \\frac{-v_0}{\\omega x_0}$)*",
    "*(Trích xuất theo đúng bản in trong sách:)*",
    "$A = \\sqrt{x^2 + \\frac{v^2}{\\omega^2}} = \\sqrt{5^2 + \\frac{(-30)^2}{(4\\pi)^2}} \\approx 5,54 \\text{ cm}$",
    "$\\tan\\varphi = \\frac{\\omega x_0}{v_0} = \\frac{30}{4\\pi \\cdot 5} = \\frac{3}{2\\pi} \\Rightarrow \\varphi \\approx 0,44 \\text{ rad}$",
    "",
    "b) Vận tốc cực đại của vật: $v_{max} = \\omega A = 4\\pi \\cdot 5,54 \\approx 70 \\text{ cm/s}$.",
    "Gia tốc cực đại của vật: $a_{max} = \\omega^2 A = (4\\pi)^2 \\cdot 5,54 \\cdot 10^{-2} \\approx 8,8 \\text{ m/s}^2$.",
    "",
    "*Ví dụ 3:* Một vật dao động điều hoà với tần số góc $\\omega = 1 \\text{ rad/s}$, có đồ thị của li độ x, vận tốc v và gia tốc a theo thời gian t được mô tả trên Hình 4.1.",
    "[Hình 4.1. Đồ thị dao động điều hoà]",
    "Hãy chỉ đúng đồ thị của li độ (x - t), vận tốc (v - t), gia tốc (a - t) theo thời gian t trên Hình 4.1.",
    "*Giải:*",
    "Ta đã biết:",
    "- Vận tốc v sớm pha $\\frac{\\pi}{2}$ so với li độ và trễ pha $\\frac{\\pi}{2}$ so với gia tốc.",
    "- Gia tốc a ngược pha so với li độ và sớm pha $\\frac{\\pi}{2}$ so với vận tốc.",
    "Do đó, trên Hình 4.1 đường 2 là đồ thị li độ x(t), đường 1 là đồ thị vận tốc v(t), đường 3 là đồ thị gia tốc a(t).",
    "",
    "## II. BÀI TẬP LUYỆN TẬP",
    "1. Một vật dao động điều hoà có phương trình là $x = 2 \\cos(4\\pi t - \\frac{\\pi}{6}) \\text{ (cm)}$. Hãy cho biết biên độ, tần số góc, chu kì, tần số, pha ban đầu và pha của dao động ở thời điểm t = 1 s.",
    "2. Một vật dao động điều hoà dọc theo trục Ox, quanh điểm gốc O, với biên độ A = 10 cm và chu kì T = 2 s. Tại thời điểm t = 0, vật có li độ x = A.",
    "a) Viết phương trình dao động của vật.",
    "b) Xác định thời điểm đầu tiên vật qua vị trí có li độ x = 5 cm.",
    "",
    "18",
    "CHƯƠNG I – DAO ĐỘNG ĐIỀU HOÀ",
    "",
    "3. Hình 4.2 là sơ đồ của một bàn xoay hình tròn, có gắn một thanh nhỏ cách tâm bàn 15 cm. Bàn xoay được chiếu sáng bằng nguồn sáng rộng, song song, hướng chiếu sáng từ phía trước màn để bóng đổ lên màn hình. Một con lắc đơn dao động điều hoà phía sau bàn xoay với biên độ bằng khoảng cách từ thanh nhỏ đến tâm bàn xoay. Tốc độ quay của bàn quay được điều chỉnh là $3\\pi \\text{ rad/s}$. Vị trí bóng của thanh nhỏ con lắc luôn trùng nhau.",
    "a) Tại sao nói dao động của bóng của thanh nhỏ và quả nặng là đồng pha?",
    "b) Viết phương trình dao động của con lắc. Chọn gốc thời gian là lúc con lắc ở vị trí hiển thị trong Hình 4.2.",
    "c) Bàn xoay đi một góc 60° từ vị trí ban đầu, tính li độ của con lắc và tốc độ của nó tại thời điểm này.",
    "[Hình 4.2. Con lắc đơn dao động điều hoà]",
    "",
    "4. Hình 4.3 là đồ thị li độ – thời gian của một vật dao động điều hoà.",
    "a) Xác định biên độ, chu kì, tần số, tần số góc và pha ban đầu của vật dao động.",
    "b) Viết phương trình của dao động của vật.",
    "[Hình 4.3. Đồ thị dao động điều hoà. x(cm) từ -10 đến 10, t(ms) từ 0 đến 160]",
    "",
    "5. Đồ thị li độ – thời gian của hai vật dao động điều hoà A và B có cùng tần số nhưng lệch pha nhau Hình 4.4.",
    "a) Xác định li độ dao động của vật B khi vật A có li độ cực đại và ngược lại.",
    "b) Hãy cho biết vật A hay vật B đạt tới li độ cực đại trước.",
    "c) Xác định độ lệch pha giữa dao động của vật A so với dao động của vật B.",
    "[Hình 4.4. Đồ thị dao động của hai vật A và B]",
    "",
    "**EM ĐÃ HỌC**",
    "- Cách xác định các đại lượng biên độ, chu kì, tần số, tần số góc pha,... khi biết phương trình hoặc đồ thị của vật dao động điều hoà và ngược lại.",
    "",
    "**EM CÓ THỂ**",
    "- Xác định được chu kì, tần số, tần số góc và viết phương trình của vật dao động điều hoà (Ví dụ Đồng hồ quả lắc).",
    "",
    "19"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH1' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI11')), 'B5', 'Động năng. Thế năng. Sự chuyển hoá năng lượng trong dao động điều hoà', 22, 5, $JSON$
{
  "content": [
    "# Bài 5 ĐỘNG NĂNG. THẾ NĂNG. SỰ CHUYỂN HOÁ NĂNG LƯỢNG TRONG DAO ĐỘNG ĐIỀU HOÀ",
    "",
    "**Khởi động:**",
    "*Ở lớp 10, khi học về chuyển động của vật, ta đã biết có sự chuyển hoá giữa động năng và thế năng của vật. Vậy trong dao động điều hoà có sự chuyển hoá tương tự không?*",
    "",
    "## I. ĐỘNG NĂNG",
    "- Động năng của vật dao động điều hoà được xác định bởi biểu thức:",
    "$W_đ = \\frac{1}{2} m v^2$. Thay $v = -\\omega A \\sin(\\omega t + \\varphi)$ vào, ta được:",
    "$W_đ = \\frac{1}{2} m \\omega^2 A^2 \\sin^2(\\omega t + \\varphi)$",
    "$W_đ = \\frac{1}{2} m \\omega^2 A^2 [1 - \\cos^2(\\omega t + \\varphi)]$",
    "Thay $x = A \\cos(\\omega t + \\varphi)$ vào ta được:",
    "$W_đ = \\frac{1}{2} m \\omega^2 (A^2 - x^2)$ (5.1)",
    "- Công thức (5.1) cho biết sự biến thiên của động năng theo li độ x.",
    "[Hình 5.1. Sự biến thiên của động năng $W_đ$ theo li độ x. Đồ thị parabol bề lõm hướng xuống]",
    "Hình 5.1 là đồ thị chỉ sự biến thiên của động năng theo li độ x. Đó là một đường parabol có bề lõm hướng xuống và có giá trị cực đại: $W_{đmax} = \\frac{1}{2} m \\omega^2 A^2$.",
    "Đồ thị cho thấy, khi vật đi từ vị trí cân bằng tới vị trí biên thì động năng của vật đang từ cực đại giảm đến 0. Khi vật đi từ vị trí biên về vị trí cân bằng thì động năng của vật tăng từ 0 đến giá trị cực đại.",
    "",
    "## II. THẾ NĂNG",
    "- Theo định luật bảo toàn năng lượng, nếu bỏ qua ma sát thì động năng của vật không mất đi mà chuyển dần thành thế năng của vật và ngược lại. Vì thế ta có thể viết:",
    "$W_t = \\frac{1}{2} W_{đmax} - W_{đ(x)}$ *(Chú ý: Trong sách in $W_t = W_{đmax} - W_{đ(x)}$, có thể do lỗi đánh máy thêm $\\frac{1}{2}$ phía trước $W_{đmax}$. Ta ghi đúng theo nguyên bản)*",
    "$W_t = \\frac{1}{2} W_{đmax} - W_{đ(x)}$",
    "$= \\frac{1}{2} m \\omega^2 A^2 - [\\frac{1}{2} m \\omega^2 A^2 - \\frac{1}{2} m \\omega^2 x^2]$",
    "$W_t = \\frac{1}{2} m \\omega^2 x^2$ (5.2)",
    "[Hình 5.2. Sự biến thiên của thế năng $W_t$ theo li độ x. Đồ thị parabol bề lõm hướng lên]",
    "Công thức (5.2) cho biết sự biến thiên của thế năng theo li độ.",
    "- Đồ thị biến thiên của thế năng theo li độ x cũng là một đường parabol nhưng bề lõm hướng lên như Hình 5.2 và có giá trị cực đại: $W_{tmax} = W_{đmax} = \\frac{1}{2} m \\omega^2 A^2$.",
    "",
    "20",
    "CHƯƠNG I – DAO ĐỘNG ĐIỀU HOÀ",
    "",
    "## III. CƠ NĂNG",
    "Trong dao động điều hoà, có sự chuyển hoá qua lại giữa động năng và thế năng của vật, còn cơ năng, tức tổng động năng và thế năng thì được bảo toàn.",
    "$W = W_đ + W_t = \\frac{1}{2} m \\omega^2 A^2$ (5.3)",
    "",
    "**Hoạt động:**",
    "1. Hình 5.3 là đồ thị động năng và thế năng của một vật dao động điều hoà theo li độ. Hãy phân tích sự chuyển hoá giữa động năng và thế năng bằng đồ thị.",
    "2. Hình 5.4 là đồ thị động năng và thế năng của một vật dao động điều hoà theo thời gian.",
    "a) Động năng và thế năng của vật thay đổi như thế nào trong các khoảng thời gian: từ 0 đến $\\frac{T}{4}$, từ $\\frac{T}{4}$ đến $\\frac{T}{2}$, từ $\\frac{T}{2}$ đến $\\frac{3T}{4}$, từ $\\frac{3T}{4}$ đến T.",
    "b) Tại các thời điểm: $t = 0; t = \\frac{T}{8}; t = \\frac{T}{4}; t = \\frac{3T}{8}$, động năng và thế năng của vật có giá trị như thế nào (tính theo W). Nghiệm lại để thấy ở mỗi thời điểm đó $W_đ + W_t = W$.",
    "[Hình 5.3. Đồ thị động năng và thế năng theo li độ]",
    "[Hình 5.4. Đồ thị động năng và thế năng theo thời gian]",
    "",
    "## IV. CƠ NĂNG CỦA CON LẮC ĐƠN VÀ CON LẮC LÒ XO",
    "**1. Con lắc lò xo**",
    "Ta biết nếu bỏ qua ma sát thì dao động của con lắc lò xo là dao động điều hoà. Thế năng của con lắc lò xo là thế năng đàn hồi của lò xo khi bị biến dạng.",
    "Người ta đã chứng minh được rằng, nếu chọn mốc thế năng ở vị trí cân bằng thì thế năng của con lắc lò xo khi vật ở li độ x là:",
    "$W_t = \\frac{1}{2} k x^2$ (5.4)",
    "với k là độ cứng của lò xo.",
    "So sánh (5.4) với (5.2) ta suy ra $\\omega = \\sqrt{\\frac{k}{m}}$ và chu kì của con lắc lò xo là: $T = 2\\pi\\sqrt{\\frac{m}{k}}$ (5.5)",
    "[Hình 5.5. Con lắc lò xo]",
    "",
    "**! Chú ý:**",
    "Làm thí nghiệm để xác nhận rằng khi góc lệch $\\alpha_0 \\le 10^\\circ$ thì chu kì của con lắc đơn gần như không phụ thuộc vào biên độ dao động.",
    "",
    "21",
    "CHƯƠNG I – DAO ĐỘNG ĐIỀU HOÀ",
    "",
    "Cơ năng của con lắc lò xo là:",
    "$W = W_đ + W_t = \\frac{1}{2} m v^2 + \\frac{1}{2} k x^2$",
    "$W = \\frac{1}{2} m \\omega^2 A^2 \\sin^2(\\omega t + \\varphi) + \\frac{1}{2} m \\omega^2 A^2 \\cos^2(\\omega t + \\varphi)$",
    "$= \\frac{1}{2} m \\omega^2 A^2 [\\sin^2(\\omega t + \\varphi) + \\cos^2(\\omega t + \\varphi)]$",
    "$= \\frac{1}{2} m \\omega^2 A^2 = \\text{hằng số}.$ (5.6)",
    "",
    "**2. Con lắc đơn**",
    "- Vị trí của con lắc đơn được xác định bằng li độ dài s hay li độ góc $\\alpha$ (Hình 5.6).",
    "- Thế năng của con lắc đơn là thế năng trọng trường.",
    "Chọn mốc thế năng ở vị trí cân bằng thì thế năng của con lắc ở li độ góc $\\alpha$ là:",
    "$W_t = mgl(1 - \\cos\\alpha)$ (5.7)",
    "Ta có: $(1 - \\cos\\alpha) = 2\\sin^2\\frac{\\alpha}{2}$, với $\\alpha$ nhỏ $\\sin\\frac{\\alpha}{2} \\approx \\frac{\\alpha}{2}$ ($\\alpha$ tính theo rad)",
    "Khi đó $W_t = mgl\\frac{\\alpha^2}{2}$, với $\\alpha = \\frac{s}{l}$",
    "Suy ra: $W_t = mgl\\frac{s^2}{2l^2} = \\frac{1}{2}m\\frac{g}{l}s^2$ (5.8)",
    "[Hình 5.6. Con lắc đơn. Dây treo dài l, li độ góc $\\alpha$, li độ dài s]",
    "",
    "Tại vị trí biên, li độ dài s của con lắc cực đại bằng A. Khi đó, động năng của con lắc bằng 0, do đó thế năng của con lắc bằng cơ năng.",
    "So sánh biểu thức (5.8) và (5.3), ta suy ra $\\omega = \\sqrt{\\frac{g}{l}}$.",
    "Biểu thức (5.8) được viết: $W_t = \\frac{1}{2} m \\omega^2 A^2 \\cos^2(\\omega t + \\varphi)$",
    "Động năng của con lắc ở li độ góc $\\alpha$ là động năng của vật m:",
    "$W_đ = \\frac{1}{2} m v^2 = \\frac{1}{2} m \\omega^2 A^2 \\sin^2(\\omega t + \\varphi)$ (5.9)",
    "Tương tự với con lắc lò xo ta có: $W = \\frac{1}{2} m \\omega^2 A^2 = \\text{hằng số}.$",
    "",
    "**Hoạt động:**",
    "Một con lắc lò xo có độ cứng k và vật nặng có khối lượng m.",
    "1. Tính chu kì T.",
    "2. Đo chu kì T bằng đồng hồ. So sánh hai kết quả thu được với kết quả tính ở Câu 1.",
    "",
    "22",
    "CHƯƠNG I – DAO ĐỘNG ĐIỀU HOÀ",
    "",
    "**? Câu hỏi:**",
    "1. Một con lắc lò xo có vật nặng khối lượng 0,4 kg, dao động điều hoà. Đồ thị vận tốc v theo thời gian t như Hình 5.7. Tính:",
    "a) Vận tốc cực đại của vật;",
    "b) Động năng cực đại của vật;",
    "c) Thế năng cực đại của con lắc;",
    "d) Độ cứng k của lò xo.",
    "2. Một con lắc lò xo gồm lò xo có độ cứng k = 100 N/m, vật nặng có khối lượng m = 200 g, dao động điều hoà với biên độ A = 5 cm.",
    "a) Xác định li độ của vật tại thời điểm động năng của vật bằng 3 lần thế năng của con lắc.",
    "b) Xác định tốc độ của vật khi vật qua vị trí cân bằng.",
    "c) Xác định thế năng của con lắc khi vật có li độ x = -2,5 cm.",
    "[Hình 5.7. Đồ thị v-t]",
    "",
    "**EM ĐÃ HỌC**",
    "- Một vật có khối lượng m dao động điều hoà với tần số góc $\\omega$ và biên độ A. Tại li độ x:",
    "– Động năng của vật là:",
    "$W_đ = \\frac{1}{2} m v^2$",
    "– Thế năng của con lắc là:",
    "$W_t = \\frac{1}{2} m \\omega^2 x^2$",
    "- Cơ năng của con lắc là:",
    "$W = \\frac{1}{2} m v^2 + \\frac{1}{2} m \\omega^2 x^2 = \\frac{1}{2} m \\omega^2 A^2 = \\text{hằng số}$",
    "",
    "**EM CÓ THỂ**",
    "- Phân tích sự chuyển hoá giữa động năng và thế năng trong dao động điều hoà ở một số ví dụ trong đời sống.",
    "",
    "23"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH1' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI11')), 'B6', 'Dao động tắt dần. Dao động cưỡng bức. Hiện tượng cộng hưởng', 26, 6, $JSON$
{
  "content": [
    "# Bài 6 DAO ĐỘNG TẮT DẦN. DAO ĐỘNG CƯỠNG BỨC. HIỆN TƯỢNG CỘNG HƯỞNG",
    "",
    "**Khởi động:**",
    "*Một em bé đang chơi xích đu trong sân. Tại sao để xích đu tiếp tục dao động, người mẹ thỉnh thoảng lại đẩy nhẹ vào em bé?*",
    "[Hình ảnh người mẹ đẩy xích đu cho em bé]",
    "",
    "## I. DAO ĐỘNG TẮT DẦN",
    "**1. Thí nghiệm dao động tắt dần**",
    "Trong các bài trước, ta đã giả thiết không có ma sát tác dụng vào con lắc. Con lắc dao động với biên độ và tần số riêng (kí hiệu là $f_0$) không đổi.",
    "Trong thực tế, khi kéo con lắc ra khỏi vị trí cân bằng rồi thả cho nó dao động thì biên độ của nó giảm dần (Hình 6.1). Dao động như vậy gọi là *dao động tắt dần*.",
    "",
    "**? Câu hỏi:**",
    "Hãy giải thích tại sao dao động của em bé chơi xích đu trong ví dụ ở đầu bài lại tắt dần nếu không có người mẹ thỉnh thoảng đẩy nhẹ vào em bé.",
    "",
    "**Thí nghiệm**",
    "*Chuẩn bị:*",
    "Con lắc có quả nặng gắn bút dạ; tấm nhựa để ghi đồ thị của dao động; bộ phận tạo chuyển động đều cho tấm nhựa.",
    "*Tiến hành:*",
    "- Bố trí thí nghiệm như Hình 6.1b.",
    "- Cho con lắc dao động ổn định và tấm nhựa chuyển động đều, bút dạ gắn ở vật nặng luôn tiếp xúc với tấm ghi đồ thị. Khi con lắc dao động, bút dạ gắn trên quả nặng sẽ ghi lại biên độ dao động của con lắc đơn theo thời gian như Hình 6.1a.",
    "Hãy nhận xét về biên độ và chu kì (hay tần số) dao động của con lắc trong thí nghiệm.",
    "[Hình 6.1. a) Hình ảnh kết quả thí nghiệm của dao động tắt dần. b) Bộ thí nghiệm khảo sát dao động tắt dần của con lắc đơn]",
    "",
    "24",
    "CHƯƠNG I – DAO ĐỘNG ĐIỀU HOÀ",
    "",
    "*Kết quả thí nghiệm:*",
    "Trong phần 1, khi con lắc dao động, nó chịu lực ma sát ở chỗ treo và ở chỗ tiếp xúc giữa bút dạ với tấm nhựa. Ngoài ra, nó còn chịu lực cản của không khí. Lực ma sát và lực cản của không khí đều làm tiêu hao cơ năng của con lắc, chuyển hoá dần cơ năng thành nhiệt năng. Vì thế, biên độ dao động của con lắc giảm dần và cuối cùng con lắc dừng lại.",
    "*Nguyên nhân làm dao động của vật tắt dần là do lực ma sát và lực cản của môi trường.*",
    "[Hình 6.2. Bộ phận giảm xóc của xe máy]",
    "",
    "**2. Ứng dụng**",
    "Bộ phận giảm xóc của xe máy Hình 6.2 là ứng dụng của dao động tắt dần.",
    "Khi xe máy đi qua chỗ mấp mô, xe bị nảy lên và dao động. Nếu dao động kéo dài làm người ngồi trên xe khó chịu. Vì thế, người ta lắp thêm một bộ phận giảm xóc để làm tắt dao động của khung xe.",
    "",
    "**? Câu hỏi:**",
    "Hãy tìm trong thực tế ví dụ về dao động tắt dần và cho biết trong mỗi trường hợp thì dao động tắt dần là có lợi hay có hại.",
    "",
    "## II. DAO ĐỘNG CƯỠNG BỨC",
    "**1. Khái niệm dao động cưỡng bức**",
    "Dao động cưỡng bức là dao động xảy ra dưới tác dụng của ngoại lực tuần hoàn có tần số f bất kì. Khi dao động ổn định tần số dao động cưỡng bức bằng tần số của ngoại lực.",
    "Ví dụ:",
    "Khi đến bến xe buýt, xe chỉ tạm dừng nên không tắt máy, thân xe vẫn dao động. Dao động đó là dao động cưỡng bức dưới tác dụng của lực cưỡng bức tuần hoàn gây ra bởi chuyển động của pít-tông trong xi lanh của máy nổ.",
    "",
    "**2. Đặc điểm**",
    "Dao động cưỡng bức khi ổn định có những đặc điểm sau đây:",
    "- Dao động cưỡng bức có biên độ không đổi và có tần số bằng tần số của lực cưỡng bức.",
    "- Biên độ của dao động cưỡng bức không chỉ phụ thuộc vào biên độ của lực cưỡng bức mà còn phụ thuộc cả vào độ chênh lệch giữa tần số của lực cưỡng bức và tần số riêng của hệ dao động. Khi tần số của lực cưỡng bức càng gần tần số riêng thì biên độ dao động của hệ càng lớn.",
    "",
    "**? Câu hỏi:**",
    "Tìm thêm ví dụ về dao động cưỡng bức.",
    "",
    "25",
    "CHƯƠNG I – DAO ĐỘNG ĐIỀU HOÀ",
    "",
    "**Thí nghiệm**",
    "*Chuẩn bị:*",
    "- Một thanh cứng hình trụ hai đầu thanh được gắn vào hai ổ trục để thanh có thể xoay dễ dàng quanh trục của nó.",
    "- Một con lắc điều khiển Đ, ba con lắc thử 1, 2 và 3 được treo vào thanh cứng hình trụ.",
    "- Bố trí thí nghiệm như Hình 6.3.",
    "*Tiến hành:*",
    "- Hãy dự đoán xem, trong thí nghiệm Hình 6.3, nếu con lắc điều khiển Đ được kéo sang một bên theo phương vuông góc với thanh rồi thả ra cho dao động thì các con lắc khác có dao động không? Con lắc nào dao động mạnh nhất? Tại sao?",
    "- Làm thí nghiệm để kiểm tra.",
    "*Nhận xét:*",
    "So sánh kết quả quan sát được với dự đoán.",
    "[Hình 6.3. Thí nghiệm về dao động cưỡng bức. Thanh cứng treo 4 con lắc Đ, 1, 2, 3]",
    "",
    "## III. HIỆN TƯỢNG CỘNG HƯỞNG",
    "**1. Định nghĩa**",
    "Từ kết quả thí nghiệm trên, ta có thể rút ra điều kiện để xảy ra hiện tượng cộng hưởng.",
    "*Hiện tượng biên độ dao động cưỡng bức tăng đến giá trị cực đại khi tần số f của lực cưỡng bức tiến đến bằng tần số riêng $f_0$ của hệ dao động gọi là hiện tượng cộng hưởng.*",
    "Đường cong trên đồ thị Hình 6.4 gọi là đồ thị cộng hưởng. Độ thị càng nhọn khi lực cản của môi trường càng nhỏ (điểm A).",
    "Điều kiện $f = f_0$ gọi là *điều kiện cộng hưởng*.",
    "[Hình 6.4. Đồ thị cộng hưởng. Trục tung là Biên độ dao động, trục hoành là Tần số của lực cưỡng bức. Đường A cao nhọn (Lực cản nhỏ), đường B thấp tãi (Lực cản lớn). Điểm cực đại ứng với $f_0$]",
    "",
    "**2. Giải thích**",
    "Khi tần số của lực cưỡng bức bằng tần số riêng của hệ dao động thì hệ được cung cấp năng lượng một cách nhịp nhàng, đúng lúc, do đó biên độ dao động của hệ tăng dần lên. Biên độ dao động đạt tới giá trị cực đại khi tốc độ tiêu hao năng lượng do ma sát bằng tốc độ cung cấp năng lượng cho hệ.",
    "Trong trò chơi đu, người đu phải tác dụng lực vào đu bằng cách nhún người khi đu bắt đầu đổi chiều ở vị trí cao nhất. Trong trò chơi này, người chơi và đu đóng vai trò là một con lắc, lực nhún của của người chơi đóng vai trò là ngoại lực. Vì ngoại lực luôn tác dụng vào con lắc tại những thời điểm nhất định (có cùng tần số với tần số dao động của đu) nên mặc dù người chơi chỉ cần nhún nhẹ nhàng cũng có thể đưa được đu lên rất cao.",
    "",
    "26",
    "CHƯƠNG I – DAO ĐỘNG ĐIỀU HOÀ",
    "",
    "**3. Hiện tượng cộng hưởng trong đời sống**",
    "Cộng hưởng là một hiện tượng vật lí quan trọng có thể xuất hiện trong nhiều tình huống khác nhau. Trong một số trường hợp, hiện tượng cộng hưởng có lợi, như:",
    "- Hộp đàn của các đàn ghi ta, violon,... là những hộp cộng hưởng được cấu tạo sao cho không khí trong hộp có thể dao động cộng hưởng với nhiều tần số dao động khác nhau của dây đàn.",
    "- Nguyên tắc hoạt động của lò vi sóng dựa trên cộng hưởng. Ở các lò vi sóng này, sóng được sử dụng có tần số phù hợp với tần số dao động riêng của các phân tử nước trong thực phẩm. Các phân tử nước đóng vai trò là hệ cộng hưởng cũng dao động cưỡng bức, nên hấp thụ năng lượng của sóng được sử dụng và nóng lên.",
    "",
    "Tuy nhiên, trong một số trường hợp khác hiện tượng cộng hưởng lại có hại.",
    "Nhiều hệ dao động như toà nhà, cầu, bệ máy, khung xe,... đều có một hay nhiều tần số riêng. Do vậy khi thiết kế cần tránh không để cho các hệ ấy chịu tác dụng của những lực cưỡng bức mạnh có tần số bằng tần số riêng ấy. Nếu không chúng sẽ làm cho các hệ dao động mạnh dẫn đến đổ hoặc gãy. Câu chuyện về một cái cầu bắc ngang qua sông Fontanka (Phô-tan-ca) ở Saint Petersburg (Xanh Pê-téc-bua) ở nước Nga được thiết kế đủ vững chắc cho 300 người đi qua. Nhưng nó đã bị sập khi một trung đội bộ binh gồm 36 người đi đều qua vào năm 1960. Hay câu chuyện về một cây cầu khác được xây dựng năm 1940 qua eo biển Tacoma (Ta-cô-ma) ở nước Mỹ có thể chịu nhiều ô tô có tải trọng lớn đi qua nhưng cũng đã bị đổ sập dưới tác dụng của gió.",
    "(Nguồn: http://www.history.com)",
    "",
    "**? Câu hỏi:**",
    "Đánh giá được sự có lợi hay có hại của cộng hưởng trong các ví dụ nêu trên.",
    "",
    "**EM ĐÃ HỌC**",
    "- Dao động có biên độ giảm dần theo thời gian gọi là dao động tắt dần.",
    "- Nguyên nhân làm dao động tắt dần là do lực ma sát và lực cản của môi trường.",
    "- Dao động chịu tác dụng của một ngoại lực cưỡng bức tuần hoàn gọi là dao động cưỡng bức. Dao động cưỡng bức có biên độ không đổi và có tần số bằng tần số của lực cưỡng bức.",
    "- Hiện tượng biên độ dao động cưỡng bức tăng đến giá trị cực đại khi tần số f của lực cưỡng bức tiến đến bằng tần số riêng $f_0$ của hệ dao động gọi là hiện tượng cộng hưởng.",
    "- Tuỳ từng trường hợp mà hiện tượng cộng hưởng có thể có lợi hoặc có thể có hại.",
    "",
    "**EM CÓ THỂ**",
    "- Lấy được ví dụ thực tế về dao động tắt dần, dao động cưỡng bức và hiện tượng cộng hưởng.",
    "- Nhận biết được sự có lợi hay có hại của cộng hưởng và vận dụng nó vào cuộc sống.",
    "",
    "27"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH1' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI11')), 'B7', 'Bài tập về sự chuyển hoá năng lượng trong dao động điều hoà', 30, 7, $JSON$
{
  "content": [
    "# Bài 7 BÀI TẬP VỀ SỰ CHUYỂN HOÁ NĂNG LƯỢNG TRONG DAO ĐỘNG ĐIỀU HOÀ",
    "",
    "**Khởi động:**",
    "*Ta có thể sử dụng định luật bảo toàn cơ năng để tìm li độ và vận tốc của vật dao động điều hoà được không?*",
    "",
    "## I. CÁC VÍ DỤ",
    "*Ví dụ 1:* Một con lắc đơn gồm vật nặng có kích thước nhỏ, có khối lượng m, treo ở đầu một sợi dây mềm không giãn có độ dài l và có khối lượng không đáng kể (Hình 7.1). Đưa vật nặng ra khỏi vị trí cân bằng O sao cho dây treo hợp với QO một góc $\\alpha_0 (\\alpha_0 \\le 10^\\circ)$ rồi thả nhẹ cho con lắc dao động điều hoà trên cung tròn AOB.",
    "a) Tính thế năng của con lắc, động năng của vật ở các vị trí A, O, B và vị trí bất kì (li độ góc $\\alpha$).",
    "b) Ở vị trí nào động năng bằng thế năng?",
    "[Hình 7.1. Con lắc đơn dao động điều hoà trên cung tròn AOB]",
    "*Giải:*",
    "a) Chọn mốc để tính thế năng của vật là vị trí cân bằng O thì:",
    "- Thế năng và động năng của vật tại các vị trí A và B là:",
    "$W_t = W_{tmax} = mgl(1 - \\cos\\alpha_0) = mgl(2\\sin^2\\frac{\\alpha_0}{2}) \\approx mgl\\frac{\\alpha_0^2}{2}$ (với $\\alpha_0$ tính theo rad)",
    "$W_đ = 0.$",
    "- Thế năng và động năng của vật tại vị trí O là:",
    "$W_t = 0.$",
    "$W_đ = W_{tmax} = mgl(1 - \\cos\\alpha_0) \\approx mgl\\frac{\\alpha_0^2}{2}$",
    "- Thế năng và động năng của vật tại vị trí bất kì (li độ góc $\\alpha$) là:",
    "$W_t = mgl(1 - \\cos\\alpha) \\approx mgl\\frac{\\alpha^2}{2}$ (với $\\alpha$ tính theo rad)",
    "$W_đ = W_{tmax} - W_t \\approx mgl\\left(\\frac{\\alpha_0^2}{2} - \\frac{\\alpha^2}{2}\\right)$",
    "b) Khi $W_đ = W_t$, áp dụng định luật bảo toàn cơ năng:",
    "$W = W_{tmax} = W_đ + W_t = 2W_t \\Leftrightarrow mgl\\frac{\\alpha_0^2}{2} = 2mgl\\frac{\\alpha^2}{2} \\Rightarrow \\alpha = \\pm \\frac{\\alpha_0}{\\sqrt{2}}.$",
    "Vậy ở các vị trí có li độ góc $\\alpha = \\pm \\frac{\\alpha_0}{\\sqrt{2}}$ thì động năng bằng thế năng.",
    "",
    "*Ví dụ 2:* Một vật có khối lượng m = 200 g dao động điều hoà với tần số góc $\\omega = 2\\pi \\text{ rad/s}$, biên độ A = 10 cm. Xác định thế năng của con lắc tại thời điểm vật có tốc độ v = 10 cm/s.",
    "",
    "28"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH2' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI11')), 'B8', 'Mô tả sóng', 32, 1, $JSON$
{
  "content": [
    "# Bài 8 MÔ TẢ SÓNG",
    "",
    "**Khởi động:**",
    "*Trong cuộc sống hằng ngày, chúng ta thường gặp hay nghe đến nhiều loại sóng như: sóng nước, sóng âm, sóng vô tuyến, sóng biển, sóng địa chấn,... Vậy sóng được hình thành như thế nào và có những đặc điểm gì?*",
    "[Hình ảnh những đợt sóng biển xô vào bờ]",
    "",
    "## I. THÍ NGHIỆM TẠO SÓNG MẶT NƯỚC",
    "**Thí nghiệm**",
    "*Chuẩn bị:*",
    "Thiết bị tạo sóng mặt nước bằng kênh tạo sóng (Hình 8.1). Đề xuất cách đo các đại lượng đặc trưng như: biên độ sóng, bước sóng, chu kì của sóng và tốc độ truyền sóng trên mặt nước.",
    "*Tiến hành:*",
    "Đặt một miếng xốp nhỏ C trên mặt nước. Khi quay đĩa D làm cho vật tạo sóng O dao động lên xuống, thì dao động đó được truyền cho các phần tử nước từ gần ra xa.",
    "[Hình 8.1. Thiết bị tạo sóng mặt nước bằng kênh tạo sóng. Đĩa D gắn cơ cấu chuyển động nối với vật tạo sóng O. Tấm chống phản xạ ở cuối kênh]",
    "*Kết quả:*",
    "- Quan sát qua thành kênh thẳng đứng, ta thấy mặt cắt của nước có dạng hình sin.",
    "- Miếng xốp C dao động lên xuống tại chỗ, còn những biến dạng của mặt nước lan truyền đi từ nguồn sóng O ra xa cho ta hình ảnh về sóng có trên mặt nước. O là nguồn sóng, nước là môi trường truyền sóng, đường thẳng OC là phương truyền sóng.",
    "- Đồ thị sóng được mô tả như trên Hình 8.2.",
    "",
    "32",
    "CHƯƠNG II – SÓNG",
    "",
    "Hình 8.2 là đồ thị một sóng hình sin lan truyền trên mặt nước theo phương Ox.",
    "[Hình 8.2. Đồ thị (u - x) của một sóng hình sin. Trục tung là li độ u, trục hoành là phương truyền sóng x. Có chú thích Ngọn sóng, Bước sóng $\\lambda$, Biên độ sóng, Lõm sóng]",
    "",
    "## II. GIẢI THÍCH SỰ TẠO THÀNH SÓNG",
    "Trong thí nghiệm Hình 8.1 các phần tử nước sát nguồn O dao động theo phương thẳng đứng. Nhờ có lực liên kết giữa các phần tử nước mà các phần tử nước ở điểm M lân cận điểm O dao động theo. Đến lượt các phần tử nước ở điểm N lân cận điểm M dao động. Ta nói có sự truyền dao động từ điểm này sang điểm khác tạo nên sóng mặt nước.",
    "Như vậy, có hai nguyên nhân tạo nên sóng truyền trong một môi trường. Đó là nguồn dao động từ bên ngoài tác dụng lên môi trường tại điểm O và có lực liên kết giữa các phần tử của môi trường.",
    "",
    "**Hoạt động:**",
    "Hãy quan sát chuyển động của miếng xốp trong thí nghiệm Hình 8.1 và cho biết miếng xốp có chuyển động ra xa nguồn cùng với sóng không?",
    "",
    "Các phần tử môi trường chỉ dao động trong một phạm vi không gian rất hẹp, trong khi sóng truyền đi rất xa.",
    "[Hình 8.3. Mô tả sự truyền sóng trên dây. Hình a, b, c, d tương ứng với các thời điểm dao động truyền đến các điểm M, N, P dọc theo trục x]",
    "",
    "33",
    "CHƯƠNG II – SÓNG",
    "",
    "Sự truyền sóng là sự truyền dao động. Dao động từ nguồn lan truyền trong môi trường thì gọi là *sóng cơ* (thường gọi tắt là sóng).",
    "",
    "## III. CÁC ĐẠI LƯỢNG ĐẶC TRƯNG CỦA SÓNG",
    "Theo Hình 8.3 tốc độ truyền sóng trên dây là không đổi, các điểm trên dây đều dao động với cùng chu kì (hay cùng tần số) của nguồn dao động.",
    "Ta có các định nghĩa:",
    "- *Biên độ sóng* là độ lệch lớn nhất của phần tử môi trường khỏi vị trí cân bằng khi sóng truyền qua.",
    "- *Bước sóng* là quãng đường sóng truyền được trong một chu kì, kí hiệu là $\\lambda$ (Hình 8.2). Đơn vị của bước sóng là mét (m).",
    "- *Chu kì sóng* là chu kì dao động của các phần tử môi trường, có đơn vị là giây (s).",
    "- *Tần số sóng* là đại lượng nghịch đảo của chu kì sóng: $f = \\frac{1}{T}$, có đơn vị là héc (Hz).",
    "- *Tốc độ truyền sóng* là tốc độ lan truyền dao động trong không gian. Nó được tính bằng thương số giữa quãng đường sóng truyền đi và thời gian truyền tương ứng: $v = \\frac{s}{t}$",
    "Tốc độ truyền sóng chỉ phụ thuộc vào tính chất của môi trường mà không phụ thuộc vào tần số sóng.",
    "",
    "**Mối liên hệ giữa chu kì, bước sóng, tốc độ truyền sóng**",
    "Trong một chu kì dao động T, sóng lan truyền đi được một quãng đường bằng một bước sóng $\\lambda$. Như vậy, tốc độ truyền sóng được tính bằng:",
    "$v = \\frac{\\lambda}{T}$ hay $\\lambda = vT = \\frac{v}{f}$ (8.1)",
    "(v là tốc độ truyền sóng; $f$ là tần số sóng)",
    "",
    "- *Cường độ sóng* I là năng lượng sóng được truyền qua một đơn vị diện tích vuông góc với phương truyền sóng trong một đơn vị thời gian.",
    "$I = \\frac{E}{S\\Delta t}$ (8.2)",
    "trong đó:",
    "E là năng lượng sóng truyền qua diện tích S trong thời gian $\\Delta t$.",
    "Trong hệ SI, năng lượng đo bằng jun (J), thời gian đo bằng giây (s), diện tích đo bằng mét vuông ($m^2$) thì đơn vị cường độ sóng là oát trên mét vuông (kí hiệu là $W/m^2$).",
    "",
    "34",
    "CHƯƠNG II – SÓNG",
    "",
    "**? Câu hỏi:**",
    "1. Hãy quan sát đồ thị (Hình 8.4). Xác định:",
    "a) Biên độ của sóng.",
    "b) Bước sóng.",
    "[Hình 8.4. Đồ thị x-y. Trục y (cm), trục x (cm). Tương tự Hình 8.2. Tại x=0, y=0. x=20, y max, x=40, y=0. Bước sóng = 80 cm, Biên độ = 0,2 cm]",
    "2. Trong thí nghiệm ở Hình 8.1, nếu ta thay đổi tần số dao động của nguồn sóng thì đại lượng nào sau đây không thay đổi?",
    "A. Chu kì sóng.",
    "B. Bước sóng.",
    "C. Tần số sóng.",
    "D. Tốc độ truyền sóng.",
    "",
    "**Hoạt động:**",
    "Từ thị Hình 8.4, hãy:",
    "1. So sánh bước sóng $\\lambda$ với khoảng cách giữa hai đỉnh sóng liên tiếp.",
    "2. Nêu mối liên hệ giữa bước sóng và khoảng cách giữa hai phần tử môi trường dao động cùng pha, ngược pha.",
    "3. Cho biết một sóng có tần số 120 Hz, truyền trong một môi trường với tốc độ 60 m/s thì bước sóng của nó bằng bao nhiêu?",
    "4. Đọc kết quả đo tốc độ truyền sóng âm trong một số môi trường (Bảng 8.1) và rút ra nhận xét.",
    "Bảng 8.1. Tốc độ truyền sóng âm trong một số môi trường (ở nhiệt độ phòng)",
    "| Chất | v (m/s) |",
    "|---|---|",
    "| Khí <br> Không khí | 343 |",
    "| Lỏng <br> Nước | 1500 |",
    "| Rắn <br> Sắt | 5130 |",
    "",
    "**EM ĐÃ HỌC**",
    "- Sóng cơ là những dao động cơ lan truyền trong một môi trường. Sóng chỉ truyền dao động, không truyền các phần tử của môi trường.",
    "- Bước sóng là quãng đường sóng truyền đi được trong một chu kì dao động.",
    "- Giữa tốc độ truyền sóng, bước sóng, chu kì dao động, hoặc tần số của sóng có hệ thức:",
    "$v = \\frac{\\lambda}{T}$ hay $\\lambda = vT = \\frac{v}{f}$",
    "",
    "**EM CÓ THỂ**",
    "- Nhận biết được một sóng, xác định được các đại lượng đặc trưng của nó.",
    "- Tạo ra và khảo sát được một sóng nước.",
    "",
    "35",
    "**EM ĐÃ HỌC**",
    "- Sóng cơ là những biến dạng cơ lan truyền trong một môi trường đàn hồi.",
    "- Biên độ sóng A là độ cao hay độ sâu của một ngọn sóng so với mức cân bằng. Biên độ sóng bằng biên độ dao động của nguồn sóng.",
    "- Chu kì T của sóng là khoảng thời gian để hai ngọn sóng liên tiếp chạy qua một điểm đang xét. Chu kì của sóng bằng chu kì dao động của nguồn sóng.",
    "- Tần số f của sóng là số các ngọn sóng đi qua một điểm đang xét trong một đơn vị thời gian. Tần số sóng bằng tần số dao động của nguồn sóng.",
    "- Tốc độ truyền sóng v là tốc độ lan truyền biến dạng.",
    "- Bước sóng $\\lambda$ là khoảng cách giữa hai ngọn sóng liên tiếp. Bước sóng bằng quãng đường mà sóng truyền được trong một chu kì.",
    "- Các đại lượng $\\lambda$, T (hay f) và v có mối liên hệ sau đây: $\\lambda = vT = \\frac{v}{f}$.",
    "- Sự lệch pha giữa các phần tử dao động trên phương truyền sóng tạo nên hình ảnh của sóng.",
    "",
    "**EM CÓ THỂ**",
    "- Dùng đồ thị (u – x) của một sóng hình sin để nêu được các đại lượng đặc trưng của sóng.",
    "",
    "36"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH2' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI11')), 'B9', 'Sóng ngang. Sóng dọc. Sự truyền năng lượng của sóng cơ', 37, 2, $JSON$
{
  "content": [
    "# Bài 9 SÓNG NGANG. SÓNG DỌC. SỰ TRUYỀN NĂNG LƯỢNG CỦA SÓNG CƠ",
    "",
    "**Khởi động:**",
    "*Sóng mặt nước và sóng âm truyền trong không khí có đặc điểm gì chung và riêng?*",
    "",
    "## I. SÓNG NGANG",
    "Trong thí nghiệm ở Hình 8.1 các phần tử nước tại O, rồi tại M dao động lên, xuống theo phương thẳng đứng, trong khi sóng truyền từ O đến M theo phương ngang.",
    "*Sóng trong đó các phần tử của môi trường dao động theo phương vuông góc với phương truyền sóng gọi là sóng ngang.*",
    "",
    "**? Câu hỏi:**",
    "Hình 9.1 mô tả một sóng ngang truyền trên dây đàn hồi. Hãy quan sát các mũi tên, từ đó chỉ ra phương dao động của các phần tử của dây và phương truyền sóng.",
    "[Hình 9.1. Một sóng ngang truyền trên dây. Dao động phương thẳng đứng, truyền sóng phương ngang]",
    "",
    "## II. SÓNG DỌC",
    "Đặt một lò xo ống dài và mềm trên mặt bàn nhẵn. Dùng tay cầm một đầu lò xo và cho bàn tay dao động dọc theo trục của lò xo. Các vòng của lò xo ở sát bàn tay lần lượt bị nén rồi bị dãn. Nhờ có lực đàn hồi giữa các vòng lò xo mà các biến dạng nén – dãn lan truyền đi xa dọc theo trục của lò xo (Hình 9.2).",
    "*Sóng trong đó các phần tử của môi trường dao động theo phương trùng với phương truyền sóng gọi là sóng dọc.*",
    "[Hình 9.2. Một sóng dọc truyền trên lò xo. Bàn tay dao động và sóng truyền cùng phương ngang. Gồm các đoạn dãn và nén]",
    "",
    "37",
    "CHƯƠNG II – SÓNG",
    "",
    "**Hoạt động:**",
    "Dựa vào Hình 9.1 và Hình 9.2, hãy chỉ ra điểm giống và khác nhau giữa sóng dọc và sóng ngang.",
    "",
    "## III. QUÁ TRÌNH TRUYỀN NĂNG LƯỢNG BỞI SÓNG",
    "Trong thí nghiệm Hình 8.1, khi sóng lan truyền đến đâu thì các phân tử nước ở đó bắt đầu dao động. Năng lượng dao động mà các phân tử nước này có được là do *sóng mang năng lượng* của nguồn đến cho chúng.",
    "Các phần tử nước chỉ dao động tại chỗ, quanh vị trí cân bằng của nó chứ không chuyển động theo sóng. Điều đó chứng tỏ sóng mang năng lượng mà không mang các phân tử nước đi theo.",
    "Đối với sóng dọc trên lò xo thì năng lượng được truyền đi bằng sự nén, dãn liên tiếp của các vòng lò xo.",
    "Mọi sóng cơ khác như sóng âm đều mang năng lượng đi xa theo cách như vậy.",
    "",
    "## IV. SỬ DỤNG MÔ HÌNH SÓNG ĐỂ GIẢI THÍCH MỘT SỐ TÍNH CHẤT CỦA ÂM",
    "Sóng dọc chạy trên lò xo là mô hình giúp ta hiểu được sự lan truyền và một số tính chất của sóng âm.",
    "Nguồn âm dao động làm cho các phần tử không khí trên dao động theo phương truyền âm, các phân tử không khí dao động lệch pha nhau tạo nên các lớp không khí nén, dãn giống như ở lò xo. Các nén, dãn này truyền đi tạo thành *sóng âm* theo mọi hướng trong không khí Hình 9.3 chỉ xét sóng âm truyền theo hướng Ox. Khi sóng âm truyền đến tai người làm cho màng nhĩ dao động, do đó ta nghe được âm thanh.",
    "[Hình 9.3. Các lớp không khí nén – dãn lan truyền tạo thành sóng âm]",
    "",
    "Như vậy, dù sóng âm không nhìn thấy nhưng ta lại có thể nghe được âm. Biên độ của sóng âm càng lớn thì biên độ dao động của màng nhĩ càng lớn, âm nghe càng to. Tần số của sóng âm càng lớn thì tần số dao động của màng nhĩ càng lớn, âm nghe càng cao.",
    "",
    "38",
    "CHƯƠNG II – SÓNG",
    "",
    "**EM ĐÃ HỌC**",
    "- Có hai loại sóng là sóng ngang và sóng dọc. Sóng ngang là sóng trong đó các phần tử của môi trường dao động theo phương vuông góc với phương truyền sóng. Sóng dọc là sóng trong đó các phần tử của môi trường dao động theo phương trùng với phương truyền sóng.",
    "- Quá trình truyền sóng là quá trình truyền năng lượng.",
    "",
    "**EM CÓ THỂ**",
    "- Sử dụng mô hình sóng dọc để giải thích được sự truyền của sóng âm và một số tính chất của âm.",
    "",
    "39"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

