  "content": [
    "# Bài 10 THỰC HÀNH: ĐO TẦN SỐ CỦA SÓNG ÂM",
    "",
    "**Khởi động:**",
    "*Trong đời sống hằng ngày, chúng ta thường nghe thấy âm thanh từ các dây đàn ghi ta phát ra hay tiếng sáo, tiếng vỗ tay,... Những âm thanh này đều có cùng bản chất là sóng âm. Làm thế nào để đo được tần số của sóng âm?*",
    "",
    "## I. MỤC ĐÍCH",
    "Đo được tần số của sóng âm bằng dao động kí điện tử (gọi tắt là dao động kí) hoặc các dụng cụ đơn giản (như ứng dụng trên điện thoại thông minh).",
    "",
