    "**1. Dao động kí điện tử**",
    "Dao động kí là một thiết bị hiển thị đồ thị của tín hiệu điện theo thời gian (với trục tung là điện áp, trục hoành là thời gian).",
    "Đối với các dao động kí phổ biến hiện nay, màn hình của nó được chia thành các ô vuông. Kích thước của mỗi ô có thể thiết lập bằng các núm điều khiển trên màn hình (Hình 10.1).",
    "Dao động kí thường có hai kênh đo để quan sát được đồng thời hai tín hiệu điện.",
