    "Micro là thiết bị điện biến đổi trực tiếp dao động âm thành dao động điện. Do đó, dao động điện trên màn hình của dao động kí có cùng quy luật với dao động âm phát ra từ nguồn âm.",
    "**3. Máy phát tần số**",
    "Máy phát tần số là thiết bị có thể tạo ra tín hiệu điện có tần số, biên độ và dạng tín hiệu (sin, vuông, tam giác) có thể thay đổi được.",
    "",
    "[Hình 10.1. Màn hình của một dao động kí điện tử]",
