    "CHƯƠNG II – SÓNG",
    "",
    "**EM CÓ BIẾT**",
    "Ánh sáng là sóng, mang năng lượng và truyền được trong chân không. Ánh sáng cũng có những đại lượng đặc trưng như chu kì, tần số, bước sóng và tốc độ truyền sóng. Trong chân không, ánh sáng nhìn thấy có bước sóng nằm trong khoảng từ 0,38 µm đến 0,76 µm.",
    "Âm nghe được có tần số nằm trong khoảng từ 16 Hz đến 20 000 Hz.",
