    "",
    "43",
    "CHƯƠNG II – SÓNG",
    "",
    "- Nguồn phát tia tử ngoại: Vật có nhiệt độ trên $2000^\\circ\\text{C}$ thì phát được tia tử ngoại, nhiệt độ của vật càng cao thì bước sóng tử ngoại càng nhỏ. Hồ quang điện, đèn hơi thuỷ ngân là nguồn phát tia tử ngoại mạnh.",
    "",
    "**4. Sóng vô tuyến**",
    "Sóng vô tuyến có bước sóng nằm trong khoảng từ $1\\text{ mm}$ đến $100\\text{ km}$. Chúng được phát ra từ an ten và được sử dụng để \"mang\" các thông tin như âm thanh, hình ảnh đi rất xa. Sóng này bị phản xạ bởi tầng điện li trước khi tới máy thu (Hình 11.4). Trong đó, sóng VHF (Very High Frequency) (bước sóng rất ngắn) từ $1\\text{ m}$ đến $10\\text{ m}$ và sóng UHF (Ultra High Frequency) (bước sóng cực ngắn) từ $10\\text{ cm}$ đến $1\\text{ m}$ có thể truyền thẳng đến máy thu, không bị phản xạ bởi tầng điện li. Chúng được sử dụng cho các đài phát thanh và truyền hình địa phương. Sóng vi ba (bước sóng khoảng vài cm) được sử dụng cho viễn thông quốc tế và chuyển tiếp truyền hình qua vệ tinh thông tin và cho mạng điện thoại di động qua tháp vi ba.",
    "[Hình 11.4. Truyền sóng vô tuyến trong khí quyển. Nối 2 máy phát và máy thu bằng sóng truyền lên tầng điện li]",
    "",
    "**? Câu hỏi:**",
    "1. Giải thích tại sao mỗi khi cho phóng hồ quang người thợ hàn cần mặt nạ che mặt (Hình 11.5).",
    "2. Giải thích tại sao Mặt Trời là một nguồn năng lượng khổng lồ phát ra tia tử ngoại mà con người và các sinh vật trên Trái Đất vẫn có thể sinh sống dưới ánh nắng mặt trời được.",
