    "",
    "**5. Tia Rơn ghen (tia X)**",
    "Tia X có bước sóng nhỏ hơn tia tử ngoại (khoảng từ $30\\text{ pm}$ đến $3\\text{ nm}$).",
    "Nguồn phát tia X: Tia X được tạo ra khi các electron chuyển động với tốc độ cao tới đập vào tấm kim loại có nguyên tử lượng lớn trong ống tia X.",
    "",
    "46",
    "CHƯƠNG II – SÓNG",
    "",
    "Ngoài các công dụng về chuẩn đoán và chữa trị một số bệnh trong y học, tia X còn được sử dụng trong công nghiệp để tìm khuyết tật trong các vật đúc bằng kim loại và trong các tinh thể; sử dụng trong giao thông để kiểm tra hành lí của hành khách khi đi máy bay,...",
    "",
    "**6. Tia gamma ($\\gamma$)**",
    "Tia gamma có bước sóng nhỏ nhất trong thang sóng điện từ, khoảng từ $10^{-5}\\text{ nm}$ đến $0,1\\text{ nm}$.",
    "Trong y học, tia gamma được dùng trong phẫu thuật, điều trị các căn bệnh liên quan đến khối u, dị dạng mạch máu, các bệnh chức năng của não. Bên cạnh lĩnh vực y tế, tia gamma còn được ứng dụng trong lĩnh vực công nghiệp. Tia gamma giúp phát hiện, các khuyết tật bằng hình ảnh rõ ràng với độ chính xác cao.",
    "",
    "**Hoạt động:**",
    "Bảng 11.1 cho biết phạm vi của bước sóng trong chân không của các dải chính tạo nên thang sóng điện từ.",
    "Hãy xác định phạm vi của tần số tương ứng với các dải bước sóng đó.",
    "*Bảng 11.1. Bước sóng trong chân không của thang sóng điện từ*",
    "| Loại bức xạ | Phạm vi bước sóng | Phạm vi tần số (Hz) |",
    "|---|---|---|",
    "| Sóng vô tuyến | Từ $1\\text{ mm}$ đến $100\\text{ km}$ | ... |",
    "| Sóng vi ba | Từ $1\\text{ mm}$ đến $1\\text{ m}$ | ... |",
    "| Tia hồng ngoại | Từ $0,76\\text{ }\\mu\\text{m}$ đến $1\\text{ mm}$ | ... |",
    "| Ánh sáng nhìn thấy | Từ $0,38\\text{ }\\mu\\text{m}$ đến $0,76\\text{ }\\mu\\text{m}$ | ... |",
    "| Tia tử ngoại | Từ $10\\text{ nm}$ đến $400\\text{ nm}$ | ... |",
    "| Tia X | Từ $30\\text{ pm}$ đến $3\\text{ nm}$ | ... |",
    "",
    "**? Câu hỏi:**",
    "1. Nêu tên sóng điện từ trong chân không ứng với mỗi bước sóng.",
    "a) $1\\text{ km}$;",
    "b) $3\\text{ cm}$;",
    "c) $5\\text{ }\\mu\\text{m}$;",
    "d) $500\\text{ nm}$;",
    "e) $50\\text{ nm}$;",
    "g) $10^{-12}\\text{ m}$.",
    "2. Nêu loại sóng điện từ ứng với mỗi tần số sau:",
    "a) $200\\text{ kHz}$;",
    "b) $100\\text{ MHz}$;",
    "c) $5.10^{14}\\text{ Hz}$;",
    "d) $10^{18}\\text{ Hz}$.",
    "",
    "**EM ĐÃ HỌC**",
    "- Sóng điện từ là điện từ trường lan truyền trong không gian.",
    "- Sóng điện từ truyền trong chân không với tốc độ bằng tốc độ ánh sáng $c = 3.10^8\\text{ m/s}$.",
    "- Dải bước sóng của thang sóng điện từ.",
    "",
    "**EM CÓ THỂ**",
    "- Nhận biết được các loại bức xạ trong thang sóng điện từ dựa vào bước sóng hoặc tần số của nó.",
    "",
    "47"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH2' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI11')), 'B11', 'Giao thoa sóng', 48, 4, $JSON$
{
  "content": [
    "# Bài 12 GIAO THOA SÓNG",
    "",
    "**Khởi động:**",
    "*Cho hai loa giống nhau cùng phát âm thanh như hình bên, dịch chuyển một micro có nối với dao động kí phía trước hai loa để ghi đồ thị sóng âm thì thấy có những điểm tại đó biên độ sóng âm thu được rất lớn (L) và những điểm biên độ rất bé (B) nằm xen kẽ. Hiện tượng thú vị này giải thích như thế nào?*",
    "[Hình ảnh 2 loa phát âm thanh và micro di chuyển ghi lại các điểm L (âm thanh lớn) và B (âm thanh nhỏ)]",
    "",
    "## I. HIỆN TƯỢNG GIAO THOA CỦA HAI SÓNG MẶT NƯỚC",
    "**1. Thí nghiệm**",
    "*Chuẩn bị:*",
    "- Đèn chiếu.",
    "- Cần rung có gắn một quả cầu",
    "- Cần rung có gắn hai quả cầu.",
    "- Khay nước có đáy trong suốt.",
    "- Gương phẳng đặt hợp với đáy khay nước một góc $45^\\circ$ để thu hình ảnh giao thoa chiếu trên màn thẳng đứng.",
    "*Tiến hành:*",
    "Bước 1: Cho cần rung có gắn một quả cầu dao động, quan sát hình ảnh sóng trên màn thẳng đứng.",
    "Bước 2: Cho cần rung có gắn hai quả cầu dao động, quan sát hình ảnh sóng trên màn thẳng đứng và rút ra nhận xét.",
    "Bước 3: Dùng bút nối các điểm dao động cực đại (các điểm tối) trên màn ta thu được các đường cong liền nét như trên Hình 12.2. Tương tự ta nối các điểm dao động cực tiểu trên màn ta thu được các đường cong đứt nét như trên Hình 12.2.",
    "[Hình 12.1. Thí nghiệm tạo ra sự giao thoa của hai sóng nước. Hình ảnh giao thoa từ khay nước chiếu trên gương phẳng hắt lên màn đục]",
    "",
    "*Kết quả:*",
    "Đối với cần rung có gắn một quả cầu, hình ảnh trên màn thẳng đứng cho thấy có các hình tròn sáng, tối đồng tâm xen kẽ, lan truyền từ tâm dao động ra xa.",
    "Đối với cần rung có gắn hai quả cầu, hình ảnh trên màn thẳng đứng ta thấy ảnh của các gợn sóng là các đường sáng và tối ổn định. Các đường này được biểu diễn như trong Hình 12.2.",
    "",
    "48",
    "CHƯƠNG II – SÓNG",
    "",
    "**2. Giải thích**",
    "a) Để giải thích hiện tượng trên, ta cần biết thêm một đặc điểm nữa của chuyển động sóng: Mỗi nguồn sóng phát ra một sóng có các gợn sóng là những đường tròn giống hệt như khi không có các nguồn sóng khác ở bên cạnh.",
    "Những điểm nào cách nguồn một khoảng bằng $k\\lambda$ thì dao động đồng pha với nguồn, còn những điểm nào cách nguồn một khoảng $(k + 0,5)\\lambda$ thì dao động ngược pha với nguồn.",
    "b) Trong thí nghiệm ta đã dùng hai nguồn sóng giống hệt nhau dao động theo phương vuông góc với mặt nước. Vì thế, trên mặt nước có những điểm đứng yên, do hai sóng gặp nhau ở đó dao động ngược pha, triệt tiêu nhau. Có những điểm dao động rất mạnh do hai sóng ở đó dao động đồng pha.",
    "[Hình 12.2. Sự giao thoa của hai sóng mặt nước]",
    "c) Ánh sáng truyền qua những điểm đứng yên không bị cản trở, nên cho ảnh là những hypebol rất sáng. Còn ánh sáng truyền qua những điểm dao động mạnh thì bị tán xạ nên cho ảnh là những đường hypebol nhoè và tối.",
    "",
    "*Hiện tượng hai sóng gặp nhau tạo nên các gợn sóng ổn định gọi là hiện tượng giao thoa của hai sóng. Các gợn sóng ổn định gọi là các vân giao thoa.*",
    "",
    "**3. Điều kiện để xảy ra giao thoa**",
    "Để xảy ra hiện tượng giao thoa hai nguồn sóng phải:",
    "- Dao động cùng phương, cùng tần số.",
    "- Có độ lệch pha không đổi theo thời gian.",
    "*Hai nguồn như vậy gọi là hai nguồn kết hợp. Hai sóng do hai nguồn kết hợp phát ra gọi là hai sóng kết hợp.*",
    "Hiện tượng giao thoa là một hiện tượng đặc trưng của sóng. Vì thế, mọi quá trình vật lí nào gây ra được hiện tượng giao thoa cũng tất yếu là một quá trình sóng.",
    "",
    "**? Câu hỏi:**",
    "Giải thích hiện tượng nêu ở mục khởi động của đầu bài.",
    "",
    "## II. THÍ NGHIỆM CỦA YOUNG (Y-ÂNG) VỀ GIAO THOA ÁNH SÁNG",
    "**1. Thí nghiệm**",
    "Tương tự như sóng nước, làm thí nghiệm về giao thoa của hai nguồn sóng ánh sáng kết hợp.",
    "Thí nghiệm được bố trí như Hình 12.3.",
    "Ánh sáng phát ra từ nguồn S chiếu vào hai khe hẹp $F_1$, $F_2$. Hai khe hẹp này là hai nguồn kết hợp.",
    "",
    "49",
    "CHƯƠNG II – SÓNG",
    "",
    "[Hình 12.3. Thí nghiệm giao thoa ánh sáng]",
    "[Hình 12.4. Thí nghiệm tạo ra sự giao thoa ánh sáng của hai chùm laze]",
    "",
    "Hình ảnh giao thoa ánh sáng quan sát được trên màn E như Hình 12.4.",
    "",
    "**? Câu hỏi:**",
    "Trong thí nghiệm trên, nếu thay nguồn sáng laze trong thí nghiệm trên bằng bóng đèn dây tóc phát ánh sáng trắng thì vân sáng chính giữa sẽ có màu gì.",
    "",
    "Trong vùng hai chùm sáng gặp nhau lại có những vạch tối và vạch sáng xen kẽ như trên Hình 12.4 đã khẳng định ánh sáng có tính chất sóng. *Những vạch tối là chỗ hai sóng ánh sáng triệt tiêu lẫn nhau. Những vạch sáng là chỗ hai sóng ánh sáng tăng cường lẫn nhau. Những vạch sáng và tối xen kẽ nhau chính là hệ vân giao thoa của hai sóng ánh sáng.*",
    "",
    "**2. Công thức xác định bước sóng $\\lambda$ của ánh sáng**",
    "Hình 12.5 là sơ đồ rút gọn của thí nghiệm Y-âng. Gọi:",
    "- O là vị trí tại đó xuất hiện vân sáng chính giữa.",
    "- a là khoảng cách giữa hai khe: $a = F_1F_2$.",
    "- D là khoảng cách từ hai khe đến màn quan sát: $D = IO$.",
    "- i là khoảng vân. Đó là khoảng cách giữa hai vân sáng hoặc hai vân tối liên tiếp.",
    "Nếu đo được a, D và i thì sẽ xác định được bước sóng $\\lambda$ theo công thức sau: $\\lambda = \\frac{ia}{D}$.",
    "",
    "[Hình 12.5. Sơ đồ rút gọn của thí nghiệm Y-âng]",
    "",
    "50",
    "CHƯƠNG II – SÓNG",
    "",
    "**? Câu hỏi:**",
    "1. Trong thí nghiệm ở Hình 12.1, tốc độ truyền sóng trên mặt nước là 50 cm/s, cần rung có tần số 40 Hz. Tính khoảng cách giữa hai điểm cực đại giao thoa cạnh nhau trên đoạn thẳng $S_1S_2$.",
    "2. Trong một thí nghiệm Y-âng về giao thoa ánh sáng với a = 0,2 mm, D = 1,2 m, người ta đo được i = 0,36 mm. Tính bước sóng $\\lambda$ và tần số f của bức xạ.",
    "3. Trong một thí nghiệm Y-âng, biết a = 0,15 mm, D = 1,20 m, khoảng cách giữa 12 vân sáng liên tiếp là 5,2 mm. Tính bước sóng ánh sáng.",
    "",
    "**EM ĐÃ HỌC**",
    "- Hai nguồn sóng kết hợp là hai nguồn có cùng tần số và có độ lệch pha không đổi theo thời gian. Hai sóng do hai nguồn kết hợp phát ra là hai sóng kết hợp.",
    "- Hiện tượng giao thoa là hiện tượng khi hai sóng kết hợp gặp nhau thì có những điểm ở đó hai sóng luôn đồng pha thì dao động mạnh; có những điểm ở đó hai sóng luôn ngược pha thì đứng yên.",
    "- Bước sóng $\\lambda$ của ánh sáng được xác định theo hệ thức: $\\lambda = \\frac{ia}{D}$.",
    "(trong đó: a là khoảng cách giữa hai nguồn kết hợp, D là khoảng cách từ hai nguồn kết hợp đến màn quan sát, i là khoảng vân).",
    "",
    "**EM CÓ THỂ**",
    "- Từ hiện tượng giao thoa sóng nước, giải thích hiện tượng giao thoa của các sóng khác như sóng âm, sóng ánh sáng.",
    "",
    "51"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH2' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI11')), 'B12', 'Sóng dừng', 52, 5, $JSON$
{
  "content": [
    "# Bài 13 SÓNG DỪNG",
    "",
    "**Khởi động:**",
    "*Khi vỗ tay đều trước miệng các ống của đàn K’lông pút có độ dài khác nhau như hình bên, thì thấy âm phát ra ở các miệng ống trầm bổng khác nhau. Sóng âm lan truyền trong mỗi ống không phải là sóng chạy. Vậy đó là loại sóng gì và có những đặc điểm nào?*",
    "[Hình ảnh người chơi đàn K'lông pút]",
    "",
    "## I. THÍ NGHIỆM TẠO SÓNG DỪNG",
    "**Thí nghiệm**",
    "Bố trí thí nghiệm như Hình 13.1",
    "*Chuẩn bị*",
    "- Giá thí nghiệm.",
    "- Dây đàn hồi PQ.",
    "- Bộ rung.",
    "- Máy phát âm tần.",
    "*Tiến hành*",
    "Bước 1: Giữ cho dây căng, đầu P mắc vào ròng rọc, đầu rung mắc vào dây Hình 13.1.",
    "Bước 2: Cho bộ rung hoạt động để rung đầu P. Điều chỉnh tần số của bộ rung cho đến khi trên dây xuất hiện những điểm dao động với biên độ cực đại và có những điểm đứng yên. Hiện tượng như vậy gọi là hiện tượng sóng dừng. Ghi lại tần số của bộ rung.",
    "Bước 3: Thay đổi tần số của bộ rung cho đến khi lại quan sát được những điểm dao động với biên độ cực đại và những điểm đứng yên. Ghi lại tần số mới của bộ rung.",
    "[Hình 13.1. Bộ thí nghiệm tạo sóng dừng trên sợi dây]",
    "",
    "**? Câu hỏi:**",
    "Từ kết quả thí nghiệm rút ra điều kiện để có sóng dừng.",
    "",
    "## II. GIẢI THÍCH SỰ TẠO THÀNH SÓNG DỪNG",
    "**1. Đặc điểm của sóng dừng**",
    "Sóng dừng được tạo thành mỗi khi có hai sóng cùng biên độ, cùng bước sóng lan truyền theo hai hướng ngược nhau. Hai sóng này gặp nhau, giao thoa nhau tạo nên sóng tổng hợp là sóng dừng. Những điểm tại đó hai sóng ngược pha nhau thì không dao động và được gọi là",
    "",
    "52",
    "CHƯƠNG II – SÓNG",
    "",
    "nút sóng. Những điểm tại đó hai sóng đồng pha với nhau thì dao động với biên độ cực đại và được gọi là bụng sóng (Hình 13.2).",
    "Trong thực tế ta thường gặp một trong hai sóng là sóng phản xạ của sóng kia.",
    "Sóng dừng là tổng hợp của nhiều sóng tới và sóng phản xạ.",
    "[Hình 13.2. Đồ thị Hướng truyền của sóng phản xạ, Hướng truyền của sóng tới, Sóng tổng hợp]",
    "",
    "**? Câu hỏi:**",
    "Hãy xác định số nút và số bụng của sóng dừng trên sợi dây Hình 13.3.",
    "",
    "**2. Điều kiện để có sóng dừng**",
    "*Điều kiện để có sóng dừng trên một sợi dây có hai đầu cố định là chiều dài của sợi dây phải bằng một số nguyên lần nửa bước sóng (Hình 13.3).*",
    "$L = n\\frac{\\lambda}{2}$ (13.1)",
    "với n = 1, 2, 3,...",
    "[Hình 13.3. Bụng sóng, Nút sóng]",
    "",
    "## III. SÓNG DỪNG TRONG CÁC NHẠC CỤ",
    "Việc các nhạc cụ phát ra các nốt nhạc cao, thấp khác nhau thường phụ thuộc vào các việc tạo ra các sóng dừng khác nhau.",
    "",
    "**1. Sóng dừng đối với nhạc cụ dây**",
    "Đối với các loại nhạc cụ dây như đàn ghita, violon, đàn tính, đàn cò,... thì hai đầu dây đàn được giữ cố định. Khi ta gảy đàn, trên dây xuất hiện sóng dừng. Theo công thức (13.1), nó phát ra một âm có bước sóng $\\lambda = 2L$ hay có tần số $f = \\frac{v}{2L}$. Khi ấn ngón tay vào các phím khác nhau ta đã thay đổi chiều dài của dây đàn, do đó âm phát ra có độ cao, thấp khác nhau. Để khuếch đại âm, đàn ghita còn có một thùng đàn đóng vai trò hộp cộng hưởng.",
    "",
    "**? Câu hỏi:**",
    "Hãy giải thích sự tạo thành sóng dừng trên dây PQ ở thí nghiệm Hình 13.1.",
    "[Hình 13.4. Đàn tính]",
    "",
    "53",
    "CHƯƠNG II – SÓNG",
    "",
    "**2. Sóng dừng đối với nhạc cụ khí**",
    "Đối với các loại nhạc cụ khí như sáo, kèn, khi ta thổi, cột không khí dao động tạo ra sóng dừng. Bằng cách thay đổi lỗ không bị bịt ta thay đổi chiều dài cột không khí dao động. Do đó các nốt nhạc phát ra cũng bị thay đổi (Hình 13.5).",
    "[Hình 13.5. Sáo trúc]",
    "",
    "**? Câu hỏi:**",
    "1. Một dây đàn hồi dài 0,6 m hai đầu cố định dao động với một bụng sóng.",
    "a) Tính bước sóng $\\lambda$ của sóng trên dây.",
    "b) Nếu dây dao động với 3 bụng sóng thì bước sóng là bao nhiêu?",
    "2. Trên sợi dây đàn hồi, có chiều dài L = 1,2 m người ta tạo ra sóng dừng có hình dạng được mô tả ở Hình 13.6. Biết tần số rung của sợi dây là f = 13,3 Hz. Xác định tốc độ truyền sóng trên dây.",
    "[Hình 13.6. Sóng dừng trên dây hai đầu cố định]",
    "[Hình 13.7. Sóng dừng trong ống khí một đầu kín, một đầu hở]",
    "",
    "**? Câu hỏi:**",
    "Tìm điều kiện để có sóng dừng trong cột không khí một đầu cố định, một đầu tự do (Hình 13.7).",
    "",
    "**EM ĐÃ HỌC**",
    "- Hai sóng cùng biên độ, cùng tần số lan truyền theo hai hướng ngược nhau trên một dây giao thoa với nhau tạo nên một sóng tổng hợp gọi là sóng dừng.",
    "- Trong sóng dừng có những điểm luôn đứng yên gọi là nút sóng và những điểm luôn dao động với biên độ cực đại gọi là bụng sóng. Hai nút liên tiếp cách nhau $\\frac{\\lambda}{2}$, xen giữa chúng là một bụng sóng.",
    "- Điều kiện để có sóng dừng trên một dây có hai đầu cố định là chiều dài của dây phải bằng một số nguyên lần nửa bước sóng.",
    "$L = n\\frac{\\lambda}{2}$ với n = 1, 2, 3,...",
    "- Điều kiện để có sóng dừng trên dây một đầu cố định, một đầu tự do hoặc trong ống khí một đầu kín, một đầu hở là chiều dài của dây hoặc của cột không khí phải bằng một số lẻ lần một phần tư bước sóng.",
    "$L = (2n + 1)\\frac{\\lambda}{4}$ với n = 0, 1, 2, 3,...",
    "",
    "**EM CÓ THỂ**",
    "- Giải thích được sự hình thành sóng dừng trong thực tế. Ví dụ trong ống sáo, đàn K’lông pút.",
    "",
    "54"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH2' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI11')), 'B13', 'Bài tập về sóng', 55, 6, $JSON$
{
  "content": [
    "# Bài 14 BÀI TẬP VỀ SÓNG",
    "",
    "**Khởi động:**",
    "*Có thể sử dụng mối liên hệ nào để xác định các đại lượng $\\lambda, v, f, T$?*",
    "",
    "## I. CÁC VÍ DỤ",
    "*Ví dụ 1:* Một sóng âm có tần số 192 Hz và truyền đi được quãng đường 91,4 m trong 0,27 s. Hãy tính:",
    "a) Tốc độ truyền sóng.",
    "b) Bước sóng.",
    "c) Nếu tần số sóng là 442 Hz thì bước sóng và chu kì là bao nhiêu?",
    "*Giải:*",
    "a) $v = \\frac{s}{t} = \\frac{91,4}{0,27} = 338,5\\text{ m/s}.$",
    "b) Sử dụng công thức $v = \\lambda f$",
    "$\\Rightarrow \\lambda = \\frac{v}{f} = \\frac{338,5}{192} = 1,76\\text{ m}.$",
    "c) $\\lambda' = \\frac{v}{f'} = \\frac{338,5}{442} = 0,77\\text{ m};$",
    "$T' = \\frac{1}{f} = \\frac{1}{442} = 0,002\\text{ s}.$",
    "",
    "*Ví dụ 2:* Trong thí nghiệm Hình 8.1, cần rung dao động với tần số 50 Hz. Người ta đo được bán kính của 2 gợn sóng hình tròn liên tiếp lần lượt bằng: 12,4 cm và 14,3 cm. Tính tốc độ truyền sóng.",
    "*Giải:*",
    "Bước sóng là khoảng cách giữa hai gợn sóng liên tiếp, theo đề bài ta có:",
    "$\\lambda = 14,3 - 12,4 = 1,90\\text{ cm};$",
    "Áp dụng công thức $v = \\lambda f$, tính tốc độ truyền sóng: $v = 1,9.50 = 95\\text{ cm/s}.$",
    "",
    "*Ví dụ 3:* Một sóng hình sin đang lan truyền từ trái sang phải trên một dây dài Hình 14.1 là hình ảnh của sóng ở một thời điểm xét. Cho biết tốc độ truyền sóng v = 1 m/s.",
    "[Hình 14.1. Đồ thị Li độ u (cm) theo Phương truyền sóng x (cm)]",
    "",
    "55",
    "CHƯƠNG II – SÓNG",
    "",
    "a) Tính tần số của sóng.",
    "b) Hỏi điểm Q, P và O đang chuyển động lên hay xuống?",
    "*Giải:*",
    "a) Từ đồ thị ta được $\\lambda = 10\\text{ cm} = 0,1\\text{ m}$.",
    "Sử dụng công thức: $\\lambda = \\frac{v}{f}$:",
    "Ta suy ra tần số của sóng: $f = \\frac{v}{\\lambda} = \\frac{1}{0,1} = 10\\text{ Hz}$.",
    "b) Căn cứ vào sóng lan truyền tới điểm R bắt đầu đi lên.",
    "- Điểm Q cách R đúng một bước sóng nên dao động cùng pha. Do vậy, tại điểm Q sóng phải bắt đầu chuyển động đi lên.",
    "- Điểm P cách R 1,5 lần bước sóng nên dao động ngược pha. Do vậy, tại điểm P sóng phải bắt đầu chuyển động đi xuống.",
    "- Điểm O cách R đúng hai bước sóng nên dao động cùng pha. Do vậy, tại điểm O sóng phải bắt đầu chuyển động đi lên.",
    "",
    "*Ví dụ 4:* Trong một thí nghiệm về giao thoa ánh sáng với hai khe Y-âng, khoảng cách giữa hai khe hẹp là a = 2 mm, khoảng cách giữa mặt phẳng chứa hai khe với màn quan sát là D = 1,2 m. Khe sáng hẹp phát đồng thời hai bức xạ đơn sắc màu đỏ $\\lambda_1 = 0,66\\text{ }\\mu\\text{m}$ và màu lục $\\lambda_2 = 0,55\\text{ }\\mu\\text{m}$.",
    "a) Tính khoảng vân của hai ánh sáng màu đỏ và màu lục.",
    "b) Tính khoảng cách ngắn nhất giữa hai vân sáng cùng màu với vân sáng trung tâm.",
    "*Giải:*",
    "a) Với ánh sáng đỏ $\\lambda_1 = 0,66\\text{ }\\mu\\text{m}$",
    "$i_1 = \\frac{\\lambda_1 D}{a} = \\frac{0,66.10^{-3}.1,2.10^3}{2} \\approx 0,40\\text{ mm}.$",
    "Với ánh sáng lục $\\lambda_2 = 0,55\\text{ }\\mu\\text{m}$",
    "$i_2 = \\frac{\\lambda_2 D}{a} = \\frac{0,55.10^{-3}.1,2.10^3}{2} = 0,35\\text{ mm}.$",
    "b) Vân chính giữa ứng với k = 0 là chung cho cả hai bức xạ, tức là tại đó cả hai bức xạ đều cho vân sáng và vân có màu là màu hỗn hợp của màu đỏ và màu lục, tức là màu vàng – da cam.",
    "Vân đầu tiên cùng màu với vân này ở tại điểm A và cách tâm O của vân chính giữa một khoảng x = OA sao cho: $k_1 i_1 = k_2 i_2$ với $k \\in \\mathbb{Z}$.",
    "Ta nhận thấy $6k_1 = 5k_2$.",
    "Do vậy, giá trị nhỏ nhất của $k_1$ là 5 và của $k_2$ là 6, tức là:",
    "OA = 0,33.6 = 1,98 mm",
    "",
    "56",
    "CHƯƠNG II – SÓNG",
    "",
    "## II. BÀI TẬP LUYỆN TẬP",
    "1. Một lò xo có chiều dài 1,2 m, đầu trên gắn vào một nhánh âm thoa, đầu dưới treo một quả cân. Dao động của âm thoa được duy trì bằng một nam châm điện để có tần số 50 Hz. Khi đó, trên lò xo có sóng dừng và trên lò xo chỉ có một nhóm vòng dao động với biên độ cực đại. Tính tốc độ truyền sóng trên lò xo.",
    "2. Một sóng hình sin được mô tả như Hình 14.2.",
    "a) Xác định bước sóng của sóng.",
    "b) Nếu chu kì của sóng là 1 s thì tần số và tốc độ truyền sóng bằng bao nhiêu?",
    "c) Bước sóng sẽ bằng bao nhiêu nếu tần số tăng lên 5 Hz và tốc độ truyền sóng không đổi? Vẽ đồ thị (u – x) trong trường hợp này và đánh dấu rõ bước sóng trên đồ thị.",
    "[Hình 14.2. Đồ thị Li độ u (cm) theo Phương truyền sóng x (cm)]",
    "",
    "3. Trong một thí nghiệm Y-âng về giao thoa ánh sáng, hai khe được chiếu bằng ánh sáng đơn sắc. Khoảng cách giữa hai khe là 0,6 mm. Khoảng vân trên màn quan sát đo được là 1 mm. Từ vị trí ban đầu, nếu tịnh tiến màn quan sát một đoạn 25 cm lại gần mặt phẳng chứa hai khe thì khoảng vân mới trên màn là 0,8 mm. Tính bước sóng của ánh sáng dùng trong thí nghiệm.",
    "",
    "**EM ĐÃ HỌC**",
    "- Cách xác định các đại lượng đặc trưng (chu kì, bước sóng, tốc độ truyền sóng,...) khi biết phương trình hoặc đồ thị của sóng và ngược lại.",
    "",
    "**EM CÓ THỂ**",
    "- Giải thích được cách đo bước sóng ánh sáng qua thí nghiệm giao thoa ánh sáng với khe Y-âng thông qua mối liên hệ giữa các đại lượng i, D, a, $\\lambda$.",
    "",
    "57"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH2' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI11')), 'B14', 'Thực hành: Đo tốc độ truyền âm', 58, 7, $JSON$
{
  "content": [
    "# Bài 15 THỰC HÀNH: ĐO TỐC ĐỘ TRUYỀN ÂM",
    "",
    "**Khởi động:**",
    "*Âm thanh truyền trong một môi trường có tốc độ xác định, làm thế nào đo được tốc độ truyền âm trong không khí bằng dụng cụ thí nghiệm?*",
    "",
    "## I. DỤNG CỤ THÍ NGHIỆM",
    "- Ống trụ làm bằng thuỷ tinh hữu cơ trong suốt, có đường kính trong 40 mm, dài 670 mm, có chia độ 0 $\\div$ 660 mm (1).",
    "- Pít-tông làm bằng thép bọc nhựa, có vạch dấu, nối với dây kéo và ròng rọc, có thể di chuyển dễ dàng trong ống (2).",
    "- Máy phát tần số phát ra tín hiệu có dạng sin (3).",
    "- Một loa nhỏ (4).",
    "- Giá đỡ ống trụ (5).",
    "",
    "[Hình 15.1. Bộ thí nghiệm đo tốc độ truyền âm]",
    "",
    "## II. THIẾT KẾ PHƯƠNG ÁN THÍ NGHIỆM",
    "Lắp ống trụ đã được lồng pít-tông ở trong ống lên giá đỡ, ghép loa sát đầu dưới của ống trụ (Hình 15.1).",
    "",
    "**! Chú ý:**",
    "Có thể sử dụng âm thoa La thay cho loa.",
    "",
    "**Hoạt động:**",
    "Nối máy phát tần số với loa, bật công tắc nguồn của máy phát tần số, điều chỉnh biên độ và tần số để nghe rõ âm (hoặc dùng búa cao su gõ vào một nhánh của âm thoa), đồng thời dịch chuyển dần pít-tông ra xa loa. Trả lời câu hỏi sau:",
    "a) Khi pít-tông di chuyển, độ to của âm thanh nghe được thay đổi như thế nào?",
    "b) Khoảng cách giữa hai vị trí liên tiếp của pít-tông mà âm thanh nghe được to nhất cho phép xác định đại lượng nào của sóng âm?",
    "c) Cần đo đại lượng nào để tính được tốc độ truyền âm?",
    "",
    "## III. TIẾN HÀNH THÍ NGHIỆM",
    "1. Điều chỉnh máy phát tần số đến giá trị 500 Hz.",
    "2. Dùng dây kéo pít-tông di chuyển trong ống thuỷ tinh, cho đến lúc âm thanh nghe được to nhất. Xác định vị trí âm thanh nghe được là lớn nhất lần 1. Đo chiều dài cột khí $l_1$. Ghi số liệu vào Bảng 15.1.",
    "Thực hiện thao tác thêm hai lần nữa.",
    "[Hình 15.2. Máy phát tần số]",
    "",
    "58",
    "CHƯƠNG II – SÓNG",
    "",
    "3. Tiếp tục kéo pít-tông di chuyển trong ống thuỷ tinh, cho đến lúc lại nghe được âm thanh to nhất. Xác định vị trí của pít-tông mà âm thanh nghe được là to nhất lần 2. Đo chiều dài cột khí $l_2$. Ghi số liệu vào mẫu Bảng 15.1",
    "Thực hiện thao tác thêm hai lần nữa.",
    "",
    "**EM CÓ BIẾT**",
    "Sử dụng một số phần mềm trên điện thoại hay máy tính có thể thay thế cho máy phát âm tần.",
    "",
    "## IV. KẾT QUẢ THÍ NGHIỆM",
    "*Bảng 15.1*",
    "Tần số nguồn âm $f = ...\\pm ...\\text{ Hz}$.",
    "| Chiều dài cột không khí khi âm to nhất (cm) | Lần 1 | Lần 2 | Lần 3 | Giá trị trung bình (l) | Sai số $\\Delta l$ |",
    "|---|---|---|---|---|---|",
    "| $l_1$ | ? | ? | ? | ? | ? |",
    "| $l_2$ | ? | ? | ? | ? | ? |",
    "",
    "**Hoạt động:**",
    "Xử lí kết quả thí nghiệm",
    "a) Tính chiều dài cột không khí giữa hai vị trí của pít-tông khi âm to nhất $d = l_2 - l_1 = ?$",
    "b) Tính tốc độ truyền âm $v = \\lambda.f = 2df = ?$",
    "c) Tính sai số: $\\delta v = \\delta d + \\delta f = ?$",
    "$\\Delta v = ?$",
    "d) Giải thích tại sao không xác định tốc độ truyền âm qua $l_1$, $l_2$ mà cần xác định qua $l_2 - l_1$.",
    "",
    "**EM CÓ THỂ**",
    "Chế tạo chiếc đàn K’lông Pút bằng các ống nứa hoặc ống nhựa rỗng, có độ dài khác nhau và có thể phát ra được âm có tần số bằng tần số các nốt nhạc cơ bản.",
    "",
    "**EM ĐÃ HỌC**",
    "Cách đo tốc độ truyền âm trong không khí nhờ hiện tượng sóng dừng.",
    "",
    "**EM CÓ BIẾT**",
    "Âm có thể truyền trong các môi trường chất rắn, chất lỏng và chất khí với tốc độ khác nhau. Tốc độ truyền âm trong một số môi trường như Bảng 15.2.",
    "",
    "*Bảng 15.2*",
    "| Môi trường | Tốc độ (m/s) |",
    "|---|---|",
    "| Không khí | 340 |",
    "| Gỗ | 3400 |",
    "| Nước | 1500 |",
    "| Thép | 6100 |",
    "| Thuỷ tinh | 5500 |",
    "",
    "59"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH3' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI11')), 'B15', 'Lực tương tác giữa hai điện tích', 61, 1, $JSON$
{
  "content": [
    "# Bài 16 LỰC TƯƠNG TÁC GIỮA HAI ĐIỆN TÍCH",
    "",
    "**Khởi động:**",
    "*Em đã biết các điện tích cùng dấu đẩy nhau, khác dấu hút nhau. Theo em, độ lớn của lực tương tác giữa hai điện tích phụ thuộc như thế nào vào độ lớn của các điện tích và khoảng cách giữa chúng?*",
    "",
    "## I. LỰC HÚT VÀ LỰC ĐẨY GIỮA CÁC ĐIỆN TÍCH",
    "**Hoạt động:**",
    "- Treo thanh nhựa A bằng một dây chỉ để nó có thể quay tự do rồi dùng len cọ xát một đầu của nó.",
    "- Quan sát, mô tả và giải thích hiện tượng xảy ra khi:",
    "a) Dùng len cọ xát một đầu thanh nhựa B rồi đưa lại gần đầu đã được cọ xát của thanh nhựa A (Hình 16.1a).",
    "b) Dùng lụa cọ xát một đầu thanh thuỷ tinh C rồi đưa lại gần đầu đã được cọ xát của thanh nhựa A (Hình 16.1b).",
    "[Hình 16.1. Sự hút, đẩy của các điện tích]",
    "- Dựa vào Hình 16.2a, vẽ các vector lực biểu diễn tương tác giữa các điện tích trong các hình còn lại.",
    "- Vẽ vector lực của ba điện tích đặt tại các đỉnh của một tam giác đều. Biết các điện tích trên đều cùng dấu và cùng độ lớn.",
    "[Hình 16.2. Lực tương tác giữa hai điện tích]",
    "",
    "Từ những thí nghiệm trên có thể rút ra kết luận:",
    "- Có hai loại điện tích trái dấu. Điện tích xuất hiện ở thanh thuỷ tinh khi được cọ xát vào len được quy ước gọi là điện tích dương, điện tích xuất hiện ở thanh nhựa được cọ xát vào vải được quy ước gọi là điện tích âm.",
    "- Các điện tích cùng loại đẩy nhau.",
    "- Các điện tích khác loại hút nhau.",
    "Lực hút, đẩy giữa các điện tích được gọi chung là lực tương tác giữa các điện tích (thường gọi tắt là lực điện).",
    "",
    "61",
    "CHƯƠNG III – ĐIỆN TRƯỜNG",
    "",
    "Độ lớn của lực tương tác giữa các điện tích có phụ thuộc như thế nào vào khoảng cách giữa các điện tích? Đề xuất phương án thí nghiệm để kiểm tra dự đoán.",
    "",
    "## II. ĐỊNH LUẬT COULOMB (CU-LÔNG)",
    "**1. Đơn vị điện tích, điện tích điểm**",
    "Người ta kí hiệu giá trị của điện tích bằng chữ \"q\". Trong hệ SI đơn vị đo điện tích là Coulomb (C), lấy theo tên của nhà vật lí người Pháp Charles Coulomb (Sác-lơ Cu-lông).",
    "Điện tích điểm là vật tích điện có kích thước nhỏ so với khoảng cách tới điểm mà ta xét. Trong các thí nghiệm vật lí, người ta coi các quả cầu tích điện có bán kính nhỏ so với khoảng cách giữa chúng là các điện tích điểm, khoảng cách giữa các điện tích điểm này là khoảng cách giữa tâm của các quả cầu.",
    "",
    "**2. Định luật Coulomb**",
    "Coulomb cho rằng độ lớn của lực tương tác giữa hai điện tích phụ thuộc vào giá trị của các điện tích và khoảng cách giữa chúng. Ông dùng cân xoắn (Hình 16.4) để xác định mối liên hệ giữa độ lớn lực tương tác giữa hai quả cầu tích điện với điện tích của hai quả cầu và khoảng cách giữa chúng.",
    "Các kết quả thí nghiệm được phát biểu thành định luật sau đây mang tên ông:",
    "*Lực tương tác giữa hai điện tích điểm có phương trùng với đường thẳng nối hai điện tích điểm, có độ lớn tỉ lệ thuận với tích giá trị của hai điện tích điểm và tỉ lệ nghịch với bình phương khoảng cách giữa chúng.*",
    "$F = \\frac{k|q_1q_2|}{r^2}$ (16.1)",
    "Trong đó r là khoảng cách giữa hai điện tích điểm $q_1, q_2$; k là hệ số tỉ lệ có độ lớn phụ thuộc vào môi trường trong đó đặt điện tích và đơn vị sử dụng. Khi các điện",
    "",
    "[Hình 16.3. Charles Coulomb (Sác-lơ Cu-lông, 1736-1806), nhà vật lí người Pháp có nhiều công trình nghiên cứu về điện và từ]",
    "",
    "**EM CÓ BIẾT**",
    "Thí nghiệm cân xoắn Coulomb",
    "[Hình 16.4. Cân xoắn Coulomb]",
    "A: Quả cầu kim loại được giữ cố định.",
    "B: Quả cầu kim loại giống hệt A, được gắn vào một đầu của thanh ngang làm bằng chất cách điện.",
    "C: Quả cầu đối trọng của B để giữ thanh ngang cân bằng",
    "D: Dây treo có tính đàn hồi chống lại sự xoắn.",
    "E: Chốt quay để thay đổi vị trí của thanh ngang.",
    "G: Bảng chia độ.",
    "Tích điện cho quả cầu A. Cho quả cầu A chưa tích điện tiếp xúc với quả cầu B. Khi đó quả cầu A sẽ truyền cho quả cầu B một nửa điện tích của mình và đẩy quả cầu này ra xa nhờ lực tĩnh điện. Lực đẩy tĩnh điện của hai quả cầu làm xoắn dây treo D. Góc xoắn giữa hai quả cầu được xác định nhờ bảng chia độ G trên hình trụ. Từ đó, xác định được độ lớn của lực tương tác giữa hai quả cầu và quan hệ của lực này với độ lớn của điện tích và khoảng cách giữa hai quả cầu.",
    "",
    "62",
    "CHƯƠNG III – ĐIỆN TRƯỜNG",
    "",
    "tích đặt trong chân không và hệ đơn vị sử dụng là SI thì k được xác định bởi:",
    "$k = \\frac{1}{4\\pi\\varepsilon_0}$",
    "Trong đó $\\varepsilon_0$ là một hằng số điện $\\varepsilon_0 = 8,85.10^{-12}\\text{ C}^2/\\text{Nm}^2$. Do đó, định luật Coulomb đối với các điện tích điểm đặt trong chân không có biểu thức:",
    "$F = \\frac{|q_1q_2|}{4\\pi\\varepsilon_0 r^2}$ (16.2)",
    "hoặc $F = \\frac{k|q_1q_2|}{r^2}$, với $k \\approx 9.10^9\\text{ Nm}^2/\\text{C}^2$ (16.3)",
    "[Hình 16.5. Lực tương tác giữa hai điện tích điểm]",
    "",
    "**! Chú ý:**",
    "Vì không khí khô có tính chất điện giống của chân không nên người ta thường áp dụng biểu thức (16.2), (16.3) cho cả hai môi trường chân không và không khí.",
    "",
    "**? Câu hỏi:**",
    "1. Hãy nêu tên các đại lượng và tên các đơn vị trong biểu thức (16.2) và (16.3).",
    "2. Nếu khoảng cách giữa hai điện tích điểm tăng lên 2 lần và giá trị của mỗi điện tích điểm tăng lên 3 lần thì lực điện tương tác giữa chúng tăng hay giảm bao nhiêu lần?",
    "3. Hãy vẽ các vector lực điện tương tác giữa hai điện tích điểm $q_1 = 10^{-5}\\text{ C}$ và $q_2 = 10^{-7}\\text{ C}$ đặt cách nhau 10 cm trong chân không theo tỉ lệ 1 cm ứng với khoảng cách 2 cm và lực 0,4 N. Lấy $k = 9.10^9\\text{ Nm}^2/\\text{C}^2$.",
    "",
    "## III. BÀI TẬP VỀ ĐỊNH LUẬT COULOMB",
    "**1. Bài tập ví dụ**",
    "Người ta dùng máy phát tĩnh điện để tích điện cho hai quả cầu kim loại nhỏ đặt cách nhau 10 cm trong không khí. Tính lực điện tương tác giữa hai quả cầu khi:",
    "a) Hai quả cầu được tích điện cùng dấu và cùng độ lớn $9,45.10^{-7}\\text{ C}$.",
    "b) Đưa hai quả cầu cách nhau 20 cm.",
    "c) Đưa hai quả cầu về vị trí cũ và làm giảm điện tích của một quả cầu đi một nửa.",
    "*Giải:*",
    "a) Theo định luật Coulomb:",
    "$F = \\frac{|q_1q_2|}{4\\pi\\varepsilon_0 r^2} = \\frac{(9,45.10^{-7})^2}{4.3,14.8,85.10^{-12}.10^{-2}} \\approx 0,8\\text{ N}.$",
    "b) Vì lực điện tỉ lệ nghịch với bình phương khoảng cách giữa hai điện tích nên khi khoảng cách tăng lên 2 lần thì F giảm đi 4 lần: $F \\approx 0,2\\text{ N}$.",
    "c) Vì lực điện tỉ lệ thuận với tích của $q_1$ và $q_2$ nên khi $q_1$ giảm đi một nửa thì lực cũng giảm đi một nửa: $F \\approx 0,4\\text{ N}$.",
    "",
    "**2. Bài tập luyện tập**",
    "1. Người ta có thể dùng lực tĩnh điện để tách các trang sách bị dính chặt vào nhau mà không làm chúng hỏng. Hãy mô tả cách làm này.",
    "2. Có thể dùng định luật Coulomb để xác định độ lớn của lực tương tác giữa các điện tích trong các thí nghiệm ở Hình 16.1 không? Tại sao?",
    "3. Xác định lực điện tương tác giữa electron và proton của nguyên tử hydrogen. Biết khoảng cách từ electron trong nguyên tử hydrogen đến hạt nhân của nguyên tử này là $5.10^{-11}\\text{ m}$; điện tích của electron và proton có độ lớn bằng nhau $1,6.10^{-19}\\text{ C}$.",
    "Lấy $\\varepsilon_0 = 8,85.10^{-12}\\frac{\\text{C}^2}{\\text{N.m}^2}$.",
    "",
    "63",
    "CHƯƠNG III – ĐIỆN TRƯỜNG",
    "",
    "4. Hai điện tích điểm $q_1 = 15\\text{ }\\mu\\text{C}; q_2 = -6\\text{ }\\mu\\text{C}$ đặt cách nhau 0,2 m trong không khí. Phải đặt một điện tích $q_3$ ở vị trí nào để lực điện tác dụng lên điện tích này bằng 0?",
    "",
    "**EM ĐÃ HỌC**",
    "- Có hai loại điện tích khác dấu là điện tích dương và điện tích âm.",
    "- Các điện tích cùng dấu đẩy nhau, khác dấu hút nhau.",
    "- Trong hệ SI đơn vị điện tích là Coulomb (C).",
    "- Định luật Coulomb: *Lực tương tác giữa hai điện tích điểm có phương trùng với đường thẳng nối hai điện tích điểm, có độ lớn tỉ lệ thuận với tích giá trị của hai điện tích điểm và tỉ lệ nghịch với bình phương khoảng cách giữa chúng.*",
    "- Biểu thức của định luật Coulomb đối với môi trường chân không:",
    "$F = \\frac{|q_1q_2|}{4\\pi\\varepsilon_0 r^2}; F = \\frac{k|q_1q_2|}{r^2}$",
    "với $k = 9.10^9\\text{ Nm}^2/\\text{C}^2$",
    "",
    "**EM CÓ BIẾT**",
    "Hình 16.6 mô tả một ứng dụng của lực điện vào thực tế: Sơn tĩnh điện (còn gọi là sơn khô tĩnh điện). Mũi của “súng sơn” được nối với cực dương của một máy phát tĩnh điện, vật cần sơn được nối với cực âm của máy này.",
    "Các hạt sơn cực nhỏ khi bay ra khỏi mũi của súng sơn mang điện dương nên bị vật cần sơn mang điện âm hút dính chặt vào. Cách sơn tĩnh điện tiết kiệm được sơn, ít làm ô nhiễm môi trường, có nước sơn bền lâu hơn so với cách phun sơn thông thường.",
    "[Hình 16.6. Sơn tĩnh điện. Có Mũi súng phun sơn, Vật cần sơn]",
    "",
    "**EM CÓ THỂ**",
    "Có thể trình bày được nguyên tắc hoạt động của máy lọc không khí trong gia đình dựa trên sơ đồ (Hình 16.7).",
    "[Hình 16.7. Sơ đồ máy lọc bụi không khí]",
    "Không khí bẩn đi qua:",
    "1: Lớp lọc bụi có kích thước lớn.",
    "2, 3: Lưới lọc tĩnh điện.",
    "4: Lớp lọc vi khuẩn, mùi.",
    "5: Quạt.",
    "6: Nguồn điện.",
    "Đầu ra là Không khí sạch.",
    "",
    "64"
  ]
}
