{
  "content": [
    "# Bài 17 KHÁI NIỆM ĐIỆN TRƯỜNG",
    "",
    "**Khởi động:**",
    "*Hai quả cầu tích điện cùng dấu được treo bằng hai sợi dây mảnh không dẫn điện như hình bên. Tại sao chúng không tiếp xúc nhưng vẫn tương tác được với nhau?*",
    "[Hình ảnh Hai quả cầu tích điện có tương tác với nhau]",
    "",
    "## I. KHÁI NIỆM ĐIỆN TRƯỜNG",
    "**Hoạt động:**",
    "Đặt điện tích q cách điện tích Q một khoảng r (Hình 17.1):",
    "1. Có phải không khí đã truyền tương tác điện từ điện tích Q tới điện tích q?",
    "2. Vùng không gian bao quanh một nam châm có từ trường. Tương tự như vậy, vùng không gian bao quanh một điện tích có điện trường. Ta có thể phát hiện sự tồn tại của điện trường bằng cách nào?",
    "[Hình 17.1. Tương tác giữa hai điện tích]",
    "[Hình 17.2. Tương tác giữa hai nam châm]",
    "",
    "- Xung quanh nam châm có từ trường, từ trường sẽ truyền tương tác từ nam châm này tới nam châm khác (Hình 17.2). Tương tự như nam châm, xung quanh điện tích có một điện trường, điện trường sẽ truyền tương tác giữa các điện tích, đó là một trường lực.",
    "- Điện trường được tạo ra bởi điện tích, là dạng vật chất tồn tại xung quanh điện tích và truyền tương tác giữa các điện tích.",
    "",
    "**! Chú ý:**",
    "Trong bài này ta chỉ xét điện trường của các điện tích đứng yên.",
    "",
    "65",
    "CHƯƠNG III – ĐIỆN TRƯỜNG",
    "",
    "## II. CƯỜNG ĐỘ ĐIỆN TRƯỜNG",
    "- Người ta sử dụng điện tích dương có điện tích nhỏ, được gọi là điện tích thử, để phát hiện lực điện tác dụng lên nó, qua đó nhận biết được độ mạnh yếu của điện trường tại điểm ta xét. Đại lượng đặc trưng cho độ mạnh yếu của điện trường được gọi là cường độ điện trường.",
    "- Theo công thức (16.2), độ lớn của lực điện F tỉ lệ với độ lớn của điện tích q. Tỉ số $\\frac{F}{q}$ chính bằng độ lớn của lực điện tác dụng lên điện tích 1 C, do đó tỉ số này được lấy làm số đo cường độ điện trường tại điểm đặt điện tích thử q.",
    "",
    "[Hình 17.3. Điện trường tại N mạnh hơn điện trường tại M]",
    "",
    "Cường độ điện trường tại một điểm được đo bằng tỉ số giữa lực điện tác dụng lên một điện tích dương đặt tại điểm đó và độ lớn của điện tích đó.",
    "$E = \\frac{F}{q}$ (17.1)",
    "- Trong hệ SI, đơn vị của cường độ điện trường là vôn trên mét (V/m).",
    "- Vì lực là đại lượng vector, q là đại lượng vô hướng nên cường độ điện trường E là đại lượng vector. Vector cường độ điện trường $\\vec{E}$ tại một điểm được xác định bằng tỉ số giữa vector lực điện $\\vec{F}$ tác dụng lên một điện tích q đặt tại điểm đó và trị số của điện tích đó:",
    "$\\vec{E} = \\frac{\\vec{F}}{q}$ (17.2)",
    "",
    "**Hoạt động:**",
    "Hãy chứng tỏ rằng vector cường độ điện trường $\\vec{E}$ có:",
    "+ Phương trùng với phương của lực điện tác dụng lên điện tích.",
    "+ Chiều cùng với chiều của lực điện khi q > 0, ngược chiều với chiều của lực điện khi q < 0.",
    "+ Độ lớn của vector cường độ điện trường $\\vec{E}$ bằng độ lớn của lực điện tác dụng lên điện tích 1C đặt tại điểm ta xét.",
    "",
    "- Từ công thức (16.2), ta xác định được độ lớn cường độ điện trường do một điện tích điểm Q đặt trong chân không hoặc trong không khí gây ra tại một điểm cách nó một khoảng r có giá trị bằng:",
    "$E = \\frac{|Q|}{4\\pi\\varepsilon_0 r^2}$ (17.3)",
    "",
    "**Hoạt động:**",
    "Xét điện trường của điện tích $Q = 6.10^{-14}\\text{ C}$, sử dụng đoạn thẳng dài 1cm để biểu diễn cho độ lớn vector cường độ điện trường $E = \\frac{10^{-10}}{6\\pi\\varepsilon_0}$ (V/m). Hãy tính và vẽ vector cường độ điện trường tại một điểm cách Q một khoảng 2 cm và 3 cm.",
    "",
    "66",
    "CHƯƠNG III – ĐIỆN TRƯỜNG",
    "",
    "**? Câu hỏi:**",
    "1. Hãy chứng tỏ rằng: Độ lớn cường độ điện trường tại một điểm trong công thức (17.1) bằng độ lớn của lực điện tác dụng lên một đơn vị điện tích đặt tại điểm đó.",
    "2. Một điện tích điểm $Q = 6.10^{-13}\\text{ C}$ đặt trong chân không.",
    "a) Xác định phương, chiều, độ lớn của cường độ điện trường do điện tích điểm Q gây ra tại một điểm cách nó một khoảng 1 cm, 2 cm, 3 cm.",
    "b) Nhận xét về cường độ điện trường ở những điểm gần điện tích Q và ở những điểm cách xa điện tích Q.",
    "c) Từ các nhận xét trên, em hãy mô tả cường độ điện trường do một điện tích điểm dương Q đặt trong chân không gây ra tại một điểm cách nó một khoảng r. Vẽ hình minh hoạ.",
    "",
    "**EM CÓ BIẾT**",
    "Trong cơn dông, thường xuất hiện những đám mây tích điện do các hạt nước trong đó nhiễm điện, chúng tạo ra những vùng điện trường mạnh quanh các đám mây này. Khi các đám mây tích điện trái dấu tới gần nhau có thể xảy ra hiện tượng phóng điện mà ta gọi là sét.",
    "",
    "**Hoạt động:**",
    "Nếu trong không gian có hai điện tích điểm dương $Q_1 = Q_2$ được đặt ở hai điểm B và C, một điện tích thử q được đặt tại một điểm A như Hình 17.4. Hãy mô tả bằng hình vẽ lực điện tổng hợp do $Q_1$ và $Q_2$ tác dụng lên điện tích thử q.",
    "[Hình 17.4. Lực điện tác dụng lên điện tích thử q tại điểm A]",
    "",
    "- Muốn tính vector cường độ điện trường của hệ điện tích tại điểm A bất kì ta cũng có vector cường độ điện trường $\\vec{E}_1 = \\frac{\\vec{F}_1}{q}$ do $Q_1$ gây ra tại điểm A, vector cường độ điện trường $\\vec{E}_2 = \\frac{\\vec{F}_2}{q}$ do $Q_2$ gây ra tại điểm A,... tổng các vector cường độ điện trường $\\vec{E}_1$, $\\vec{E}_2$... theo quy tắc tổng hợp vector ta sẽ có vector cường độ điện trường tổng hợp của hệ điện tích gây ra tại điểm A. Vector cường độ điện trường tổng hợp chính bằng thương số của vector lực điện tổng hợp chia cho trị số của điện tích q: $\\vec{E} = \\frac{\\vec{F}}{q}$",
    "Như vậy, cường độ điện trường của hệ điện tích điểm được tổng hợp từ cường độ điện trường theo công thức (17.2) hay (17.3) của mỗi điện tích điểm.",
    "$\\vec{E} = \\vec{E}_1 + \\vec{E}_2 + \\vec{E}_3 + ...$",
    "",
    "67",
    "CHƯƠNG III – ĐIỆN TRƯỜNG",
    "",
    "## III. ĐIỆN PHỔ",
    "- Để mô tả trực quan điện trường, người ta dùng điện phổ.",
    "*Hình ảnh các đường mạt cưa (hoặc những mẩu chỉ ngắn,...) mang các hạt mang điện tích nằm dọc theo những đường cong xác định trong điện trường là hình ảnh của các điện phổ.*",
    "Dựa vào hình ảnh điện phổ để vẽ các đường sức điện. Đường sức điện là các đường được vẽ trong điện trường sao cho hướng của vector cường độ điện trường tại mỗi điểm trên đường sức điện trùng với hướng của vector tiếp tuyến của đường sức điện tại điểm đó.",
    "Dưới đây là một số hình ảnh điện phổ và đường sức điện (Hình 17.5).",
    "",
    "**Hoạt động:**",
    "Quan sát Hình 17.5, hãy:",
    "1. Mô tả hình ảnh điện phổ của một điện tích điểm, của hai điện tích điểm, của hai bản phẳng tích điện.",
    "2. Vẽ các đường sức điện và nhận xét về các đường sức điện của một điện tích điểm, của hai điện tích điểm, của hai bản phẳng tích điện. (Dùng các đường cong nét liền, có hướng).",
    "",
    "**Đặc điểm của đường sức điện**",
    "- Tại mỗi điểm trong điện trường chỉ vẽ được một đường sức điện đi qua. Nói cách khác, các đường sức điện không cắt nhau.",
    "- Các đường sức điện là những đường cong không kín, xuất phát từ các điện tích dương và tận cùng ở các điện tích âm. Nếu chỉ có một điện tích thì đường sức điện xuất phát từ điện tích dương và kéo dài ra vô cực hoặc đường sức điện xuất phát từ vô cực và tận cùng ở điện tích âm.",
    "- Mật độ các đường sức điện (số đường sức điện qua một đơn vị diện tích vuông góc với đường sức) được vẽ theo quy ước: nơi nào có cường độ điện trường lớn hơn thì các đường sức điện được vẽ mau (dày) hơn, nơi nào cường độ điện trường nhỏ hơn thì các đường sức điện được vẽ thưa hơn.",
    "",
    "[Hình 17.5. Một số hình ảnh điện phổ và đường sức điện]",
    "a) Hình ảnh điện phổ của một điện tích dương và đường sức điện tương ứng.",
    "b) Hình ảnh điện phổ của hai điện tích dương bằng nhau và đường sức điện tương ứng.",
    "c) Hình ảnh điện phổ của hai điện tích trái dấu bằng nhau và đường sức điện tương ứng.",
    "d) Hình ảnh điện phổ của hai bản phẳng tích điện trái dấu bằng nhau đặt song song và đường sức điện tương ứng.",
    "",
    "68",
    "CHƯƠNG III – ĐIỆN TRƯỜNG",
    "",
    "**? Câu hỏi:**",
    "Vẽ các đường sức điện của một điện tích âm.",
    "",
    "**EM ĐÃ HỌC**",
    "- Điện trường là dạng vật chất tồn tại xung quanh điện tích và truyền tương tác điện.",
    "- Cường độ điện trường tại một điểm là đại lượng đặc trưng cho độ mạnh yếu của điện trường tại điểm đó và được xác định bằng tỉ số giữa độ lớn của lực điện tác dụng lên một điện tích điểm đặt tại điểm đó và độ lớn của điện tích đó:",
    "$E = \\frac{F}{q}$",
    "- Cường độ điện trường do điện tích Q gây ra tại một điểm cách nó một khoảng r có độ lớn:",
    "$E = \\frac{|Q|}{4\\pi\\varepsilon_0 r^2}$",
    "- Vector cường độ điện trường $\\vec{E}$ có: phương trùng với phương của lực điện tác dụng lên điện tích; chiều cùng với chiều của lực điện khi q > 0, ngược chiều với chiều của lực điện khi q < 0.",
    "- Đường sức điện là đường mô tả trực quan điện trường. Các đường sức điện có đặc điểm:",
    "+ Tại mỗi điểm trong điện trường chỉ vẽ được một đường sức điện đi qua. Nói cách khác, các đường sức điện không cắt nhau.",
    "+ Các đường sức điện là những đường cong không kín.",
    "+ Mật độ đường sức điện được vẽ mau (dày) hơn ở nơi có điện trường lớn hơn và thưa hơn ở nơi có điện trường nhỏ hơn.",
    "",
    "**EM CÓ THỂ**",
    "- Xác định được cường độ điện trường do điện tích Q gây ra tại một điểm bất kì và lực điện do Q tác dụng lên điện tích q đặt tại điểm đó.",
    "- Nêu được nguyên tắc hoạt động của máy phun sơn tĩnh điện.",
    "",
    "69",
    "CHƯƠNG III – ĐIỆN TRƯỜNG",
    "",
    "**? Câu hỏi:**",
    "1. Đặt điện tích điểm $Q_1 = 6.10^{-8}\\text{ C}$ tại điểm A và điện tích điểm $Q_2 = -2.10^{-8}\\text{ C}$ tại điểm B cách A một khoảng bằng 3 cm (Hình 17.5). Hãy xác định những điểm mà cường độ điện trường tại đó bằng 0.",
    "[Hình 17.5. Điện tích Q1 và Q2, điểm M, E1, E2]",
    "2. Cho tam giác ABC vuông tại A có AB = 3 cm và AC = 4 cm. Tại điểm B ta đặt điện tích $Q_1 = 4,5.10^{-8}\\text{ C}$, tại điểm C ta đặt điện tích $Q_2 = 2.10^{-8}\\text{ C}$.",
    "a) Tính độ lớn của cường độ điện trường do mỗi điện tích trên gây ra tại A.",
    "b) Tính cường độ điện trường tổng cộng tại A.",
    "",
    "**EM CÓ BIẾT**",
    "- Trong thực tế, một quả cầu có điện tích phân bố đều trong toàn bộ thể tích hoặc phân bố đều trên mặt cầu thì điện trường bên ngoài quả cầu tương đương với điện trường của một điện tích điểm đặt tại tâm cầu và có điện tích bằng với điện tích của quả cầu. Ta thấy công thức $E = \\frac{|Q|}{4\\pi\\varepsilon_0 r^2}$ vẫn được vận dụng để tìm cường độ điện trường trong trường hợp này. Do đó trong các thí nghiệm đơn giản về điện trường người ta thường sử dụng các quả cầu tích điện để thuận tiện trong đo đạc, nghiên cứu và tính toán.",
    "- Thực nghiệm cho thấy, ngay sát bề mặt của Trái Đất luôn có một điện trường có phương thẳng đứng, hướng từ trên xuống dưới và cường độ vào khoảng từ 100 V/m đến 200 V/m. Các hạt bụi mịn lơ lửng trong không khí được phân loại dựa vào kích thước của chúng như pm1, pm2.5, pm10,... con số đứng sau chữ pm chỉ đường kính tối đa của hạt bụi tính theo đơn vị $\\mu\\text{m}$. Ví dụ pm2.5 là hạt bụi mịn có đường kính tối đa bằng 2,5 $\\mu\\text{m}$. Những hạt bụi mịn này thường tích điện dương nên không thể bay lên cao và phân tán đi xa được và là nguyên nhân chính gây ô nhiễm môi trường ở các thành phố lớn.",
    "",
    "**? Câu hỏi:**",
    "Một hạt bụi mịn loại pm2,5 có điện tích bằng $1,6.10^{-19}\\text{ C}$ lơ lửng trong không khí nơi có điện trường của Trái Đất bằng 120 V/m. Bỏ qua trọng lực, tính lực điện của Trái Đất tác dụng lên hạt bụi mịn và từ đó giải thích lí do hạt bụi loại này thường lơ lửng trong không khí.",
    "",
    "68",
    "CHƯƠNG III – ĐIỆN TRƯỜNG",
    "",
    "## III. ĐIỆN PHỔ",
    "Để quan sát điện trường của hệ hai điện tích, người ta thực hiện thí nghiệm như sau: Cho vào bể chứa dầu một ít hạt cách điện mịn (mạt cưa chẳng hạn) rồi khuấy đều để các hạt lơ lửng trong dầu. Đặt một hoặc hai quả cầu kim loại tích điện trong bể chứa dầu đó, ta thấy các hạt cách điện sẽ nằm dọc theo các đường nhất định (Hình 17.6). Hình ảnh các đường như trên gọi là điện phổ.",
    "[Hình 17.6. Ảnh chụp điện phổ]",
    "a) Điện phổ của một điện tích",
    "b) Điện phổ của hai điện tích cùng dấu",
    "c) Điện phổ của hai điện tích trái dấu",
    "",
    "**Hoạt động:**",
    "1. Em hãy quan sát Hình 17.6 và đưa ra nhận xét về đặc điểm của điện phổ:",
    "a) Ở những vùng có điện trường mạnh hơn tức là ở gần điện tích hơn.",
    "b) Ở những vùng có điện trường yếu hơn tức là ở xa điện tích hơn.",
    "c) Ở điện trường có một điện tích và điện trường có nhiều điện tích.",
    "d) Ở vùng gần điện tích dương và ở vùng gần điện tích âm.",
    "",
    "[Hình 17.7. Các đường sức điện]",
    "a) Các đường sức điện của một điện tích dương",
    "b) Hệ các đường sức điện của hai điện tích dương $Q_1 = Q_2 > 0$ đặt gần nhau",
    "c) Hệ các đường sức điện của hai điện tích trái dấu $Q_1 = -Q_2$ đặt gần nhau",
    "",
    "2. Từ quan sát Hình 17.7 và các nhận xét trên, em hãy vẽ các đường sức điện của một điện tích âm; các đường sức điện của hai điện tích âm $Q_1 = Q_2 < 0$ đặt gần nhau.",
    "",
    "69",
    "CHƯƠNG III – ĐIỆN TRƯỜNG",
    "",
    "**EM ĐÃ HỌC**",
    "- Điện trường được tạo ra bởi điện tích, là dạng vật chất tồn tại quanh điện tích và truyền tương tác giữa các điện tích.",
    "- Vector cường độ điện trường $\\vec{E}$ tại một điểm được xác định bằng tỉ số giữa vector lực điện $\\vec{F}$ tác dụng lên một điện tích q đặt tại điểm đó và giá trị của điện tích đó:",
    "$\\vec{E} = \\frac{\\vec{F}}{q}$",
    "- Độ lớn của cường độ điện trường do một điện tích điểm Q đặt trong chân không hoặc trong không khí gây ra tại một điểm cách nó một khoảng r có giá trị bằng:",
    "$E = \\frac{|Q|}{4\\pi\\varepsilon_0 r^2}$",
    "- Khi cho một hoặc một số quả cầu tích điện vào trong một bể dầu đã trộn đều các hạt cách điện. Hệ các đường được tạo thành từ các hạt cách điện được gọi là điện phổ của điện tích hoặc hệ điện tích nói trên.",
    "- Công thức tính độ lớn cường độ điện trường của một điện tích điểm được vận dụng để tính cường độ điện trường của một hệ điện tích điểm hay tính cường độ điện trường của vật hình cầu tích điện đều.",
    "- Đường sức điện xuất phát ở điện tích dương và kết thúc ở điện tích âm.",
    "",
    "**EM CÓ THỂ**",
    "- Xác định phương, chiều, độ lớn của vector cường độ điện trường tại một điểm bất kì trong điện trường.",
    "- Tính được độ lớn cường độ điện trường và mô tả được vector cường độ điện trường do một điện tích điểm gây ra tại một điểm trong không gian.",
    "- Vẽ được hệ các đường sức điện trong trường hợp một điện tích hoặc hệ hai điện tích.",
    "- Vận dụng công thức $E = \\frac{|Q|}{4\\pi\\varepsilon_0 r^2}$ để tính toán và mô tả điện trường của hệ nhiều điện tích, vật tích điện hình cầu,...",
    "- Dùng hình ảnh điện phổ để qua đó giải thích được ngay sát sát bề mặt của Trái Đất có điện trường theo phương thẳng đứng hướng từ trên xuống dưới.",
    "",
    "70"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH3' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI11')), 'B17', 'Điện trường đều', 73, 3, $JSON$
{
  "content": [
    "# Bài 18 ĐIỆN TRƯỜNG ĐỀU",
    "",
    "**Khởi động:**",
    "*Chúng ta đã biết, cường độ điện trường tại mỗi điểm thường sẽ có giá trị khác nhau. Vậy có tồn tại những vùng điện trường mà cường độ điện trường tại mỗi điểm có giá trị như nhau không?*",
    "",
    "## I. KHÁI NIỆM ĐIỆN TRƯỜNG ĐỀU",
    "Điện trường đều là điện trường mà cường độ điện trường tại mỗi điểm có giá trị bằng nhau về độ lớn, giống nhau về phương và chiều.",
    "",
    "## II. ĐIỆN TRƯỜNG ĐỀU GIỮA HAI BẢN PHẲNG NHIỄM ĐIỆN ĐẶT SONG SONG",
    "Chúng ta có thể tạo ra điện trường đều bằng cách sử dụng hai bản kim loại được đặt song song và cách nhau một khoảng d. Hai bản kim loại này có hình dạng và kích thước giống hệt nhau, kích thước của hai bản lớn so với khoảng cách giữa chúng. Tích điện trái dấu cho hai bản kim loại này, khi đó hiệu điện thế giữa hai bản là U (Hình 18.1).",
    "Trong thí nghiệm này dây treo điện tích q < 0 luôn lệch so với phương thẳng đứng một góc không đổi tại mọi điểm trong không gian giữa hai bản kim loại. Điều đó chứng tỏ điện trường giữa hai bản kim loại là đều.",
    "Các đường sức của điện trường giữa hai bản phẳng song song cách đều và vuông góc với các bản phẳng, chúng xuất phát từ bản tích điện dương và kết thúc ở bản tích điện âm.",
    "Cường độ điện trường giữa hai bản phẳng nhiễm điện trái dấu đặt song song có độ lớn bằng tỉ số giữa hiệu điện thế giữa hai bản phẳng và khoảng cách giữa chúng:",
    "$E = \\frac{U}{d}$ (18.1)",
    "Trong đó U là hiệu điện thế giữa hai bản phẳng, đơn vị là vôn (V).",
    "d là khoảng cách giữa hai bản phẳng, đơn vị là mét (m).",
    "E là cường độ điện trường giữa hai bản phẳng, đơn vị là vôn/mét (V/m).",
    "[Hình 18.1. Thí nghiệm về điện trường đều]",
    "",
    "*Bài tập ví dụ:*",
    "Hai bản phẳng kim loại đặt song song, cách nhau một khoảng d = 20 cm. Đặt vào hai bản này một hiệu điện thế một chiều U = 1000 V. Một hạt bụi mịn pm 2.5 có điện tích $q = 16.10^{-19}\\text{ C}$ bay vào điện trường giữa hai bản phẳng. Hãy xác định phương, chiều và độ lớn của lực điện tác dụng lên hạt bụi đó.",
    "",
    "71",
    "CHƯƠNG III – ĐIỆN TRƯỜNG",
    "",
    "*Giải:*",
    "Độ lớn của cường độ điện trường đều giữa hai bản phẳng là",
    "$E = \\frac{U}{d} = \\frac{1000}{0,2} = 5000\\text{ (V/m)}$",
    "Vector cường độ điện trường có phương vuông góc với hai bản phẳng, chiều hướng từ bản tích điện dương đến bản tích điện âm.",
    "Lực điện tác dụng lên điện tích q > 0 sẽ cùng phương và cùng chiều với vector cường độ điện trường tức là cùng phương và cùng chiều với đường sức, do đó lực sẽ có phương vuông góc với các bản phẳng và chiều đi từ điện tích đến phía bản nhiễm điện âm.",
    "Từ công thức $\\vec{E} = \\frac{\\vec{F}}{q}$ ta tính được độ lớn của lực điện tác dụng lên hạt bụi:",
    "$F = qE = 16.10^{-19} . 5000 = 8.10^{-15}\\text{ N}.$",
    "",
    "**? Câu hỏi:**",
    "Để chẩn đoán hình ảnh trong y học người ta thường sử dụng tia X (hay tia Rơn Ghen) để chụp X quang và chụp CT. Cho rằng vùng điện trường giữa hai cực của ống tia X (Hình 18.2) là một điện trường đều. Khoảng cách giữa hai cực bằng 2 cm, hiệu điện thế giữa hai cực là 120 kV. Hãy tính lực điện trường tác dụng lên electron.",
    "[Hình 18.2. Cấu tạo ống phóng tia X. K: cực âm (Catôt), A: cực dương (Anôt)]",
    "",
    "## III. TÁC DỤNG CỦA ĐIỆN TRƯỜNG ĐỀU ĐỐI VỚI CHUYỂN ĐỘNG CỦA MỘT ĐIỆN TÍCH",
    "**Hoạt động:**",
    "1. Giữa hai bản phẳng song song nhiễm điện có cường độ điện trường đều là E. Một điện tích q > 0 có khối lượng m bay vào trong điện trường đều trên với vận tốc $\\vec{v}_0$ theo phương vuông góc với đường sức. Môi trường giữa hai bản phẳng nhiễm điện là chân không. Biết rằng trong hiện tượng này, trọng lực là rất nhỏ so với lực điện. Hãy so sánh vector lực điện tác dụng lên điện tích q trong Hình 18.3 với vector trọng lực tác dụng lên vật khối lượng m chuyển động ném ngang trong trường trọng lực như Hình 18.4. Từ đó chỉ ra rằng có sự tương tự giữa hai chuyển động nói trên.",
    "[Hình 18.3. Chuyển động của điện tích q vào trong điện trường đều theo phương vuông góc với đường sức điện]",
    "[Hình 18.4. Chuyển động ném ngang của vật khối lượng m trong trường trọng lực]",
    "",
    "72",
    "CHƯƠNG III – ĐIỆN TRƯỜNG",
    "",
    "2. Hãy thảo luận về tác dụng của điện trường đều lên chuyển động của điện tích bay vào điện trường đều theo phương vuông góc với đường sức điện:",
    "a) Ảnh hưởng như thế nào đến vận tốc của chuyển động?",
    "b) Từ đó dự đoán dạng quỹ đạo chuyển động.",
    "",
    "*Bài tập ví dụ:*",
    "Hai bản phẳng có kích thước lớn và bằng nhau, đặt song song với nhau, cách nhau một khoảng d = 24 cm như Hình 18.5. Hiệu điện thế giữa hai bản phẳng là 48 V. Một electron ($q = -1,6.10^{-19}\\text{ C}$, $m = 9,1.10^{-31}\\text{ kg}$) bay vào chính giữa hai bản phẳng theo phương vuông góc với các đường sức điện trường với vận tốc $200\\text{ m/s}$. Bỏ qua điện trường Trái Đất, lực cản môi trường, trọng lực tác dụng lên electron. Hãy viết phương trình quỹ đạo của chuyển động.",
    "[Hình 18.5. Electron bay vào điện trường đều giữa hai bản phẳng nhiễm điện trái dấu]",
    "",
    "*Giải:*",
    "Đặt gốc toạ độ đúng tại điểm electron bắt đầu bay vào điện trường đều. Trục Ox có hướng trùng với vector vận tốc ban đầu, trục Oy hướng thẳng đứng lên trên",
    "Độ lớn cường độ điện trường giữa hai bản phẳng là:",
    "$E = \\frac{U}{d} = \\frac{48}{24.10^{-2}} = 200\\text{ (V/m)}$",
    "Chú ý rằng vector cường độ điện trường hướng từ trên xuống dưới và ngược chiều với Oy nên hình chiếu trên phương Oy sẽ có giá trị âm.",
    "Lực điện tác dụng lên electron chiếu trên phương Oy có giá trị bằng:",
    "$F = -qE = -q\\frac{U}{d}$",
    "- Phương trình chuyển động theo phương Ox: $x = v_0\\cdot t$ (1)",
    "- Phương trình chuyển động theo phương Oy: $y = \\frac{1}{2}a_y\\cdot t^2 = \\frac{1}{2}\\frac{F}{m}\\cdot t^2 = -\\frac{1}{2}\\frac{qU}{md}t^2$ (2)",
    "- Từ (1) và (2) ta thu được phương trình quỹ đạo của chuyển động:",
    "$y = -\\frac{1}{2}\\cdot\\frac{qU}{md}\\left(\\frac{x}{v_0}\\right)^2 = 4,395.x^2\\text{ (m)}$ (3)",
    "",
    "Từ phương trình (3) cho thấy electron sẽ chuyển động theo cung parabol có bề lõm hướng lên bản phẳng nhiễm điện dương và khi gặp bản phẳng này chuyển động sẽ kết thúc.",
    "Với trường hợp điện tích dương bay vào trong điện trường đều, giải tương tự ta có quỹ đạo chuyển động là cung parabol có bề lõm hướng xuống dưới.",
    "",
    "73",
    "CHƯƠNG III – ĐIỆN TRƯỜNG",
    "",
    "Dao động kí là một loại thiết bị dùng để hiển thị dạng tín hiệu đưa vào. Cấu tạo của một dao động kí gồm 4 bộ phận chính: Ống phóng tia điện tử, màn huỳnh quang, súng điện tử, hệ thống lái tia (Hình 18.6). Ống phóng tia điện tử phát ra electron bay qua hai bản lái tia theo phương x và phương y rồi đập lên màn huỳnh quang tạo ra mỗi điểm sáng trên màn.",
    "[Hình 18.6. Mô hình ống phóng tia điện tử. Có Hiệu điện thế nguồn tăng tốc cho electron, Bản lái tia theo phương y, Bản lái tia theo phương x, Tia điện tử, Màn huỳnh quang]",
    "",
    "Hãy giải thích nguyên tắc hoạt động lái tia điện tử của các bản lái tia trong Hình 18.6.",
    "",
    "## IV. ỨNG DỤNG",
    "Hãy tìm hiểu về công nghệ ion âm lọc không khí được sử dụng rất phổ biến hiện nay (để lọc không khí trong ô tô, trong gia đình, trong nhà xưởng,...). Máy hút ẩm (Hình 18.7) trong trường hợp này các ion âm được phát ra theo phương vuông góc với đường sức điện trường.",
    "Hãy nêu tác dụng của điện trường đều của Trái Đất đối với chuyển động của chùm ion âm để giải thích cho khả năng lọc bụi của chúng.",
    "[Hình 18.7. Máy hút ẩm có công nghệ ion âm lọc không khí]",
    "",
    "74",
    "CHƯƠNG III – ĐIỆN TRƯỜNG",
    "",
    "**EM CÓ BIẾT**",
    "- Chúng ta đã biết, ngay sát bề mặt của Trái Đất luôn có một điện trường có phương thẳng đứng, hướng từ trên xuống dưới, có cường độ vào khoảng từ 100 V/m đến 200 V/m. Do đó, khi xét trong một không gian hẹp gần bề mặt của Trái Đất, các đường sức điện trường có thể coi là song song và cách đều, trong khoảng không gian hẹp đó, điện trường do Trái Đất sinh ra có thể coi là điện trường đều.",
    "- Các hạt bụi, bụi siêu mịn như sợi bông, bụi khói xe,... thường nhiễm điện dương, phân tán trong không khí nhưng tập trung nhiều ở gần mặt đất, rất có hại cho sức khoẻ khi chúng ta hít vào trong phổi. Công nghệ ion âm lọc không khí là một công nghệ tiên tiến áp dụng trên nhiều sản phẩm như máy lọc không khí, máy hút ẩm, máy điều hoà,... để làm sạch không khí bằng cách tạo ra ion âm để diệt khuẩn trong không khí, làm trung hoà các bụi mịn tích điện dương làm chúng rơi xuống đất.",
    "",
    "**? Câu hỏi:**",
    "Máy lọc không khí tạo ra chùm các ion âm $\\text{OH}^-$ (mỗi ion $\\text{OH}^-$ có khối lượng $m = 2,833.10^{-26}\\text{ kg}$, điện tích $-1,6.10^{-19}\\text{ C}$) có vận tốc ban đầu từ 20 m/s đến 40 m/s theo phương song song với mặt đất và cách mặt đất 50 cm. Điện trường đều đo được ở bề mặt Trái Đất là 114 V/m. Bỏ qua trọng lực và các loại lực cản khác. Hãy xác định quỹ đạo của chùm ion âm này.",
    "",
    "**EM ĐÃ HỌC**",
    "- Điện trường đều là điện trường mà cường độ điện trường các điểm đều có giá trị bằng nhau về độ lớn, giống nhau về phương và chiều. Các đường sức trong điện trường đều là các đường thẳng song song và cách đều nhau.",
    "- Điện trường giữa hai bản phẳng nhiễm điện trái dấu đặt song song là điện trường đều. Cường độ điện trường giữa hai bản phẳng này có độ lớn bằng tỉ số giữa hiệu điện thế giữa hai bản phẳng và khoảng cách giữa chúng: $E = \\frac{U}{d}$.",
    "- Khi một điện tích bay vào điện trường đều theo phương vuông góc với đường sức, dưới tác dụng của lực điện trường: vận tốc theo phương song song với đường sức bị biến đổi; vận tốc theo phương vuông góc với đường sức không thay đổi. Kết quả là vận tốc của điện tích liên tục đổi phương và tăng dần độ lớn, quỹ đạo chuyển động trở thành đường parabol.",
    "",
    "**EM CÓ THỂ**",
    "- Mô tả được ảnh hưởng của điện trường đều lên chuyển động của một điện tích khi bay vào điện trường đều theo phương vuông góc với các đường sức. Từ đó giải thích được nguyên tắc lái tia điện tử trong ống phóng tia điện tử.",
    "- Giải thích được cơ chế gia tốc cho electron trong ống phóng tia X, từ đó giúp điều khiển một số đặc tính của chùm tia X theo mong muốn.",
    "",
    "75"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH3' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI11')), 'B18', 'Thế năng điện', 78, 4, $JSON$
{
  "content": [
    "# Bài 19 THẾ NĂNG ĐIỆN",
    "",
    "**Khởi động:**",
    "*Chúng ta đã biết, có sự tương tự giữa chuyển động của một điện tích q trong điện trường đều với chuyển động của một vật khối lượng m trong trường trọng lực. Như vậy thì điện tích q trong điện trường có tồn tại thế năng tương tự như vật khối lượng m trong trọng trường không?*",
    "[Hình ảnh Quỹ đạo chuyển động của điện tích thử q > 0 khi bay vào điện trường đều theo phương vuông góc với đường sức.]",
    "",
    "## I. CÔNG CỦA LỰC ĐIỆN",
    "Một điện tích dương q dịch chuyển trong điện trường đều từ điểm M tới điểm N luôn chịu tác dụng của lực điện không đổi (Hình 19.1). Để tính công của lực điện trong dịch chuyển này ta có thể xét chuyển động theo các quỹ đạo khác nhau như theo đường thẳng MN, theo một đường gấp khúc MPN,... Kết quả cho thấy: *Công của lực điện làm dịch chuyển của điện tích q từ điểm M đến điểm N trong điện trường đều bằng qEd, không phụ thuộc vào hình dạng của đường đi mà chỉ phụ thuộc vào vị trí của điểm đầu M và vị trí của điểm cuối N của độ dịch chuyển trong điện trường.*",
    "$A_{MN} = qEd$ (19.1)",
    "trong đó: d là độ dài đại số của đoạn MM’, là hình chiếu của đoạn MN trên một đường sức điện.",
    "[Hình 19.1. Chuyển động của điện tích dương q từ điểm M đến điểm N trong điện trường đều]",
    "",
    "Với điện trường bất kì, người ta cũng chứng minh được rằng *công của lực điện trường làm dịch chuyển của điện tích q không phụ thuộc vào hình dạng của đường đi mà chỉ phụ thuộc vào vị trí của điểm đầu M và vị trí của điểm cuối N của độ dịch chuyển*. Đây là tính chất chung của một số trường lực như trường tĩnh điện, trường trọng lực,...",
    "Vì lực điện tỉ lệ với điện tích q nên công của lực điện làm dịch chuyển điện tích q từ điểm M đến điểm N cũng tỉ lệ với điện tích q.",
    "",
    "## II. THẾ NĂNG CỦA MỘT ĐIỆN TÍCH TRONG ĐIỆN TRƯỜNG",
    "**1. Thế năng của một điện tích trong điện trường đều**",
    "Thế năng của một điện tích q trong điện trường đều đặc trưng cho khả năng sinh công của điện trường đều khi đặt điện tích q tại điểm ta xét. Số đo thế năng của điện tích q trong điện trường đều của một tụ điện được tính bằng công mà điện trường đều có thể sinh ra khi dịch chuyển điện tích q từ điểm ta xét tới bản cực âm của tụ điện.",
    "",
    "76",
    "CHƯƠNG III – ĐIỆN TRƯỜNG",
    "",
    "Một điện tích dương q được đặt tại điểm M trong điện trường đều của một tụ điện có độ lớn của cường độ điện trường là E (Hình 19.2).",
    "1. Chứng minh rằng công mà điện trường đều của tụ điện có thể sinh ra khi dịch chuyển điện tích dương q từ điểm M tới bản cực âm là A = qEd",
    "2. Hãy nhận xét về công A khi ta thay q bằng một điện tích âm",
    "[Hình 19.2. Điện tích dương q trong điện trường đều của tụ điện]",
    "",
    "- Bản cực âm của tụ điện thường được chọn làm mốc để tính thế năng. Với điện trường của một điện tích hoặc của một hệ điện tích bất kì, người ta thường chọn điểm mốc ở vô cực vì ở đó điện trường và lực điện trường đều bằng không.",
    "- Thế năng của điện tích trong điện trường còn gọi là thế năng điện. Thế năng của một điện tích q trong điện trường đều đặc trưng cho khả năng sinh công của điện trường đều khi đặt điện tích q tại điểm đang xét.",
    "- Số đo thế năng của điện tích q tại điểm M trong điện trường đều bằng công của lực điện có thể sinh ra khi điện tích q di chuyển từ điểm M tới điểm mốc để tính thế năng:",
    "$W_M = qEd$ (19.2)",
    "trong đó d là khoảng cách từ M đến bản cực âm, $W_M$ là thế năng điện của điện tích q tại điểm M.",
    "",
    "**2. Thế năng của một điện tích trong điện trường bất kì**",
    "- Tương tự như trường hợp điện trường đều, với điện trường bất kì ta có thể phát biểu: *Thế năng của một điện tích q trong điện trường đặc trưng cho khả năng sinh công của điện trường khi đặt điện tích q tại điểm đang xét.*",
    "- Số đo thế năng của điện tích q tại điểm M trong điện trường bằng công của lực điện có thể sinh ra khi điện tích q di chuyển từ điểm M tới điểm mốc để tính thế năng.",
    "*Chú ý rằng, khi chọn mốc thế năng tại vô cực, ta có số đo thế năng của điện tích q tại điểm M trong điện trường bằng công của lực điện trong dịch chuyển của điện tích q từ điểm M tới vô cực:*",
    "$W_M = A_{M\\infty}$ (19.3)",
    "- Vì độ lớn của lực điện tỉ lệ thuận với điện tích q nên thế năng tại điểm M cũng tỉ lệ với điện tích q",
    "$W_M = V_M q$ (19.4)",
    "Hệ số tỉ lệ V không phụ thuộc vào điện tích q mà chỉ phụ thuộc vào điện trường và vị trí của điểm M.",
    "",
    "77",
    "CHƯƠNG III – ĐIỆN TRƯỜNG",
    "",
    "**? Câu hỏi:**",
    "1. Chứng tỏ rằng, công của lực điện trong sự dịch chuyển của điện tích q từ điểm M đến điểm N sẽ bằng độ giảm thế năng của điện tích q trong điện trường. Hãy mở rộng cho trường hợp M ở xa vô cùng.",
    "2. Trong điện trường bất kì, khi chọn mốc là ở xa vô cùng, có trường hợp mà số đo thế năng sẽ có giá trị âm không? Hãy vẽ hình minh hoạ.",
    "",
    "**EM ĐÃ HỌC**",
    "- Công của lực điện trường trong sự dịch chuyển của điện tích q không phụ thuộc vào hình dạng của đường đi mà chỉ phụ thuộc vào vị trí của điểm đầu M và điểm cuối N của chuyển động.",
    "- Thế năng của một điện tích q trong điện trường đặc trưng cho khả năng sinh công của điện trường khi đặt điện tích q tại điểm đang xét.",
    "- Trong điện trường đều: $W_M = qEd$.",
    "- Trong điện trường bất kì: $W_M = A_{M\\infty}$.",
    "",
    "**EM CÓ THỂ**",
    "- Xác định được thế năng điện của quả cầu tích điện đều đặt trong điện trường đều của Trái Đất.",
    "- Xác định được công dịch chuyển một điện tích giữa hai điểm trong điện trường đều của Trái Đất.",
    "",
    "78"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH3' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI11')), 'B19', 'Điện thế', 81, 5, $JSON$
{
  "content": [
    "# Bài 20 ĐIỆN THẾ",
    "",
    "**Khởi động:**",
    "*Trong thực tế chúng ta gặp những đường dây dẫn điện cao thế, trung thế, hạ thế. Từ \"thế\" ở đây được hiểu như thế nào? Có liên quan tới thế năng điện đã học ở Bài 19 hay không?*",
    "[Đường dây điện cao thế]",
    "",
    "## I. ĐIỆN THẾ TẠI MỘT ĐIỂM TRONG ĐIỆN TRƯỜNG",
    "**Hoạt động:**",
    "1. Để đặt một điện tích q vào điểm M trong điện trường chúng ta cần cung cấp thế năng $W_M$ cho điện tích q. Điều này tương ứng với việc thực hiện một công A dịch chuyển điện tích q từ vô cực về điểm M. Hãy vận dụng công thức (19.4) và (19.5) để thu được công thức:",
    "$V = \\frac{A}{q}$",
    "2. Tỉ số $V = \\frac{A}{q}$ như trên được gọi là điện thế của điện trường tại điểm M.",
    "a) Hãy dự đoán điện thế V đặc trưng cho đại lượng nào của điện trường.",
    "b) Xác định độ lớn điện tích q khi điện thế V có giá trị bằng công A thực hiện để dịch chuyển điện tích q từ vô cực về điểm M.",
    "",
    "*Điện thế tại một điểm trong điện trường đặc trưng cho điện trường tại điểm đó về thế năng, được xác định bằng công dịch chuyển một đơn vị điện tích dương từ vô cực về điểm đó.*",
    "$V = \\frac{A}{q}$ (20.1)",
    "Đơn vị của điện thế là vôn (kí hiệu là V), ngoài ra người ta còn dùng đơn vị kilôvôn (kV)",
    "1 kV = 1 000 V.",
    "",
    "**! Chú ý:**",
    "a) Điện thế có giá trị đại số, dấu của điện thế phụ thuộc vào dấu của công A và dấu của điện tích q.",
    "b) Cũng như chọn mốc thế năng, ngoài việc chọn mốc điện thế ở vô cực thì trong điện trường đều giữa hai bản phẳng người ta thường chọn mốc điện thế là bản nhiễm điện âm, còn mặt đất thường được chọn là mốc điện thế trong thực tiễn cuộc sống và kĩ thuật.",
    "Chúng ta đã được học và đo hiệu điện thế. Hiệu điện thế $U_{MN}$ mà chúng ta đo được chính là giá trị của hiệu giữa điện thế tại M và điện thế tại N",
    "$U_{MN} = V_M - V_N$ (20.2)",
    "Vì vậy U và V đều có chung đơn vị là vôn.",
    "",
    "79",
    "CHƯƠNG III – ĐIỆN TRƯỜNG",
    "",
    "**EM CÓ BIẾT**",
    "1. Hiệu điện thế còn được gọi là điện áp. Thiết bị dùng để biến đổi hiệu điện thế được gọi là biến áp.",
    "2. Theo quy định của mạng lưới truyền tải điện ở Việt Nam, các lưới điện có điện áp nhỏ hơn 1 kV gọi là hạ thế, từ 1 kV đến 66 kV gọi là trung thế, lớn hơn 66 kV gọi là cao thế. Còn theo quy định của hành lang an toàn lưới điện thì điện áp lớn hơn 1 kV đã được gọi là cao thế.",
    "",
    "## II. MỐI LIÊN HỆ GIỮA ĐIỆN THẾ VÀ CƯỜNG ĐỘ ĐIỆN TRƯỜNG",
    "Trong thực tế người ta thường xét sự dịch chuyển một điện tích q từ điểm N tới điểm M nào đó trong điện trường.",
    "",
    "**Hoạt động:**",
    "Hãy vận dụng công thức $V = \\frac{A}{q}$ để chứng tỏ rằng công thực hiện để dịch chuyển điện tích q từ điểm N đến điểm M bằng:",
    "$A_{MN} = (V_M - V_N)q = U_{MN}q$ (20.3)",
    "",
    "**! Chú ý:**",
    "Để dịch chuyển một điện tích dương q ngược chiều điện trường từ điểm N tới điểm M, ta cần cung cấp một lực ít nhất bằng với lực điện và ngược chiều. Trong dịch chuyển này, công ta bỏ ra có độ lớn bằng nhưng trái dấu với công của lực điện trường.",
    "",
    "**? Câu hỏi:**",
    "Tế bào quang điện chân không (Hình 20.1) gồm một ống hình trụ có một cửa sổ trong suốt, được hút chân không (áp suất trong khoảng $10^{-8}\\text{ mmHg}$ đến $10^{-6}\\text{ mmHg}$). Trong ống đặt một catôt (cực âm) có khả năng phát xạ electron khi được chiếu sáng và một anôt (cực dương). Electron trong điện trường giữa hai cực sẽ dịch chuyển về phía anôt nếu $U_{AK} > 0$.",
    "Cho hiệu điện thế $U_{AK} = 45\\text{ V}$ được đặt vào giữa hai cực của tế bào quang điện. Khi chiếu xạ ánh sáng phù hợp để catôt phát xạ eletron vào vùng điện trường giữa hai cực. Hãy tính công của điện trường trong dịch chuyển của electron từ catôt tới anôt.",
    "[Hình 20.1. Cấu tạo của tế bào quang điện chân không. (Catôt) K, (Anôt) A, Ánh sáng]",
    "",
    "Điện thế là một đại lượng gắn với điện trường, còn thế năng điện là đại lượng gắn với điện tích đặt trong điện trường.",
    "Trong công thức (20.1), công A mà chúng ta sử dụng để dịch chuyển điện tích q từ vô cực về điểm M cũng chính bằng thế năng điện $W_M$ của điện tích q đặt tại M trong điện trường. Như vậy, thế năng điện và điện thế liên hệ với nhau bởi công thức:",
    "$W_M = Vq$ (20.4)",
    "",
    "**? Câu hỏi:**",
    "Tính thế năng điện của một electron đặt tại điểm M có điện thế bằng 1 000 V.",
    "",
    "80",
    "CHƯƠNG III – ĐIỆN TRƯỜNG",
    "",
    "Trong điện trường đều, xét một điện tích thử dương chuyển động dọc theo một đường sức điện từ điểm M đến điểm N. Ta thấy, chiều của vector cường độ điện trường E hướng theo chiều giảm của điện thế. Chọn chiều dương của trục toạ độ là chiều đường sức (Hình 20.2).",
    "Áp dụng công thức (18.1) ta có:",
    "$E_M = E_N = E = \\frac{U}{d} = \\frac{V_M - V_N}{MN}$ (20.5)",
    "Kết quả trên cho thấy: trong điện trường đều, độ lớn cường độ điện trường bằng độ giảm của điện thế dọc theo một đơn vị độ dài đường sức.",
    "Với điện trường bất kì, công thức (20.5) vẫn được áp dụng trong trường hợp hai điểm M và N ở rất gần nhau.",
    "*Cường độ điện trường tại một điểm M có độ lớn bằng thương của hiệu điện thế giữa hai điểm M và N trên một đoạn nhỏ đường sức chia cho độ dài đại số của đoạn đường sức đó.*",
    "[Hình 20.2. Chuyển động của điện tích thử dọc theo một đường sức]",
    "",
    "*Bài tập ví dụ:*",
    "Có hai bản phẳng song song cách nhau một khoảng d (Hình 20.3), được nối vào nguồn điện một chiều có hiệu điện thế 48 V. Chọn bản nhiễm điện âm làm mốc điện thế.",
    "[Hình 20.3]",
    "a) Xác định mối liên hệ giữa điện thế và cường độ điện trường tại một điểm trong điện trường đều giữa hai bản phẳng.",
    "b) Áp dụng kết quả câu a để tính điện thế tại M nằm chính giữa khe hở của hai bản phẳng.",
    "",
    "*Giải:*",
    "a) Gọi N là điểm giao của đường sức đi qua M với bản nhiễm điện âm (Hình 20.3). $V_N = 0$ do điểm N nằm trên bản phẳng nhiễm điện âm được chọn làm mốc điện thế; $MN = h > 0$ vì MN thuận theo chiều đường sức, h chính là khoảng cách từ M tới bản nhiễm điện âm.",
    "Vận dụng công thức (20.5) vào điện trường đều giữa hai bản phẳng ta tìm được mối liên hệ giữa điện thế và cường độ điện trường tại điểm M:",
    "$E_M = \\frac{V_M - V_N}{MN} \\Rightarrow V_M = E_M h$",
    "b) Trường hợp điểm M nằm chính giữa khe hở hai bản phẳng tức là $h = \\frac{d}{2}$, ta có:",
    "$V_M = Eh = \\frac{U}{d} \\frac{d}{2} = \\frac{48}{2} = 24\\text{ V}$",
    "",
    "81",
    "CHƯƠNG III – ĐIỆN TRƯỜNG",
    "",
    "**? Câu hỏi:**",
    "Vận dụng mối liên hệ giữa điện thế và cường độ điện trường để xác định điện thế tại một điểm cách mặt đất 5 m ở nơi có điện trường của Trái Đất là 114 V/m.",
    "",
    "**EM ĐÃ HỌC**",
    "- Điện thế tại một điểm trong điện trường đặc trưng cho điện trường tại điểm đó về thế năng, được xác định bằng công dịch chuyển một đơn vị điện tích dương từ vô cực về điểm đó: $V = \\frac{A}{q}$",
    "- Điện thế có mối liên hệ với thế năng điện: $V_M = \\frac{W_M}{q}$",
    "- Mối liên hệ giữa cường độ điện trường và điện thế của hai điểm M và N trong điện trường đều dọc theo đường sức điện: $E_M = E_N = \\frac{V_M - V_N}{MN}$",
    "",
    "**EM CÓ THỂ**",
    "- Giải thích được ý nghĩa của hiệu điện thế giữa hai điểm.",
    "- Vận dụng được mối liên hệ thế năng điện với điện thế để tính được thế năng điện của điện tích nằm trong điện trường.",
    "- Tính được công dịch chuyển một điện tích q từ điểm N đến điểm M trong điện trường.",
    "",
    "82"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH3' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI11')), 'B20', 'Tụ điện', 85, 6, $JSON$
{
  "content": [
    "# Bài 21 TỤ ĐIỆN",
    "",
    "**Khởi động:**",
    "*Nếu một chiếc quạt điện gặp trục trặc như: cánh quạt quay chậm hoặc không quay dù vẫn cắm điện; động cơ nóng, rung và có âm thanh bất thường, thì nguyên nhân mà chúng ta cần xem xét là hỏng tụ điện. Vậy tụ điện có cấu tạo như thế nào?*",
    "[Hình ảnh Tụ điện, Động cơ, Trục quay. Tụ điện trong một chiếc quạt điện dân dụng]",
    "",
    "## I. TỤ ĐIỆN",
    "- Tụ điện được sử dụng trong các thiết bị điện như quạt điện, tủ lạnh, ti vi, động cơ,... với các hình dạng khác nhau.",
    "[Hình 21.1. Một số tụ điện]",
    "- *Tụ điện là một loại linh kiện điện tử gồm hai vật dẫn đặt gần nhau và ngăn cách nhau bởi môi trường cách điện (điện môi). Mỗi vật dẫn được gọi là một bản tụ điện.*",
    "- Mật độ điện tích tự do trong điện môi là rất nhỏ do đó điện môi là những chất không dẫn điện. Khi điện trường ngoài đặt vào điện môi lớn hơn một giới hạn nhất định thì các liên kết giữa các điện tích trái dấu trong nguyên tử của chất điện môi sẽ bị phá vỡ, điện tích tự do xuất hiện. Lúc này điện môi trở thành dẫn điện (điện môi bị đánh thủng).",
    "- Khi vẽ mạch điện, tụ điện được kí hiệu như Hình 21.2.",
    "[Hình 21.2. Kí hiệu tụ điện trong sơ đồ mạch điện]",
    "",
    "83",
    "CHƯƠNG III – ĐIỆN TRƯỜNG",
    "",
    "- Trong mạch điện, tụ điện có nhiệm vụ tích điện và phóng điện. Ta có thể hình dung quá trình tích điện và phóng điện như sau:",
    "+ Để tích điện cho tụ điện, người ta nối hai bản cực của tụ điện với hai cực của nguồn điện một chiều. Bản nối với cực dương sẽ tích điện dương, bản nối với cực âm sẽ tích điện âm (Hình 21.3). Điện tích trên hai bản tụ điện có độ lớn bằng nhau nhưng trái dấu. Ta gọi độ lớn này là điện tích của tụ điện.",
    "+ Sau khi tích điện cho tụ điện, ta bỏ nguồn điện ra và nối hai bản tụ điện với một điện trở (hoặc bóng đèn), sẽ có dòng điện chạy qua điện trở và điện tích trên tụ điện giảm nhanh. Ta gọi đó là sự phóng điện của tụ điện.",
    "[Hình 21.3. Tích điện cho tụ điện]",
    "",
    "**EM CÓ BIẾT**",
    "- Tụ điện gồm hai bản phẳng bằng kim loại, đặt song song, giữa hai bản là chất điện môi, có thể là không khí như chúng ta đã biết được gọi là tụ điện phẳng (Hình 21.4).",
    "- Trong thực tế, người ta thường chế tạo tụ điện với hai bản là hai tấm giấy thiếc, kẽm, hoặc nhôm; Lớp điện môi làm bằng giấy tẩm chất cách điện (paraffin); Để giảm kích thước của linh kiện, người ta cuộn tụ điện lại và đặt trong một vỏ bằng kim loại (Hình 21.5). Tụ điện lúc này có dạng hình trụ.",
    "[Hình 21.4. Cấu tạo của tụ điện phẳng. Gồm Bản cực kim loại, Chất điện môi]",
