    "+ $1\\text{ picôfara (kí hiệu là pF)} = 10^{-12}\\text{ F}.$",
    "Trên vỏ tụ điện thường được ghi hai thông số kĩ thuật quan trọng (Hình 21.1) là điện dung của tụ điện và hiệu điện thế tối đa được sử dụng (nếu dùng quá hiệu điện thế này, tụ điện có nguy cơ bị đánh thủng). Tuỳ vào từng loại tụ điện mà có thể có thêm các thông số khác như tần số dòng điện, khoảng nhiệt độ mà tụ điện hoạt động bình thường,...",
    "",
    "**EM CÓ BIẾT**",
    "Ngoài các tụ điện thông dụng trong công nghệ và cuộc sống, người ta còn chế tạo ra loại tụ điện xoay, là một loại tụ điện có thể thay đổi được điện dung.",
