    "",
    "## III. NĂNG LƯỢNG CỦA TỤ ĐIỆN",
    "Khi sử dụng nguồn điện để tích điện cho tụ, nguồn điện đã thực hiện công A để dịch chuyển các electron từ bản cực nối với cực dương sang bản cực nối với cực âm của tụ điện. Công A này đã chuyển thành thế năng điện của các electron trên bản nhiễm điện âm hay nói cách khác, tụ điện đã tích một năng lượng W = A. Khi cho tụ điện phóng điện qua điện trở (hay bóng đèn) thì tụ điện giải phóng năng lượng đã tích luỹ được. Do đó ứng dụng quan trọng nhất trong thực tế của tụ điện là *tích trữ năng lượng và cung cấp năng lượng*.",
    "",
    "**EM CÓ BIẾT**",
