INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH4' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI11')), 'B21', 'Cường độ dòng điện', 93, 1, $JSON$
{
  "content": [
    "# Bài 22 CƯỜNG ĐỘ DÒNG ĐIỆN",
    "",
    "**Khởi động:**",
    "*Cường độ dòng điện là gì và đặc trưng cho tính chất nào của dòng điện?*",
    "",
    "## I. CƯỜNG ĐỘ DÒNG ĐIỆN",
    "**1. Thí nghiệm**",
    "*Thí nghiệm 1.*",
    "*Chuẩn bị:*",
    "- 1 ampe kế.",
    "- 1 biến trở.",
    "- 1 bóng đèn.",
    "- Nguồn điện.",
    "- Dây nối.",
    "- Khoá K.",
    "- Nam châm điện.",
    "*Tiến hành:*",
    "- Bố trí thí nghiệm như Hình 22.1a.",
    "- Đóng khoá K, dịch chuyển con chạy của biến trở $R_{bt}$ để số chỉ của ampe kế tăng dần.",
    "[Hình 22.1. Sơ đồ thí nghiệm khảo sát độ mạnh yếu của dòng điện]",
    "",
    "**? Câu hỏi:**",
    "1. Hãy nhận xét về độ sáng của bóng đèn Đ khi số chỉ của ampe kế tăng dần.",
    "2. Theo em, thí nghiệm trên cho thấy cường độ dòng điện đặc trưng cho tính chất nào của dòng điện?",
    "",
    "*Thí nghiệm 2.*",
    "Thay đèn Đ bằng một nam châm điện N (Hình 22.1b).",
    "- Đóng khoá K, quan sát số lượng ghim giấy bằng sắt mà nam châm hút được.",
    "- Đóng khoá K, điều chỉnh biến trở để số chỉ ampe kế chỉ giá trị lớn hơn giá trị ban đầu, quan sát số lượng ghim giấy bằng sắt mà nam châm hút được. So sánh với số lượng ghim giấy bằng sắt mà nam châm điện hút được trong hai trường hợp.",
    "",
    "**? Câu hỏi:**",
    "1. Hãy nhận xét về số ghim giấy mà nam châm hút được khi chỉ số của ampe kế tăng.",
    "2. Từ kết quả thí nghiệm cho thấy cường độ dòng điện đặc trưng cho tính chất nào của dòng điện.",
    "",
    "91",
    "CHƯƠNG IV – DÒNG ĐIỆN. MẠCH ĐIỆN",
    "",
    "**2. Công thức tính cường độ dòng điện**",
    "Lượng điện tích chuyển qua tiết diện thẳng của dây dẫn trong một đơn vị thời gian càng lớn thì dòng điện chạy qua dây dẫn càng mạnh (Hình 22.2).",
    "Trong vật lí, người ta gọi độ lớn của điện lượng chuyển qua tiết diện thẳng của một dây dẫn trong một đơn vị thời gian là cường độ dòng điện chạy qua dây dẫn, được xác định bằng công thức:",
    "$I = \\frac{\\Delta q}{\\Delta t}$ (22.1)",
    "Trong công thức trên, đơn vị của cường độ dòng điện là ampe (kí hiệu là A), của điện lượng là Cu-lông (kí hiệu là C), của thời gian là giây (kí hiệu là s).",
    "Từ công thức (22.1), ta rút ra:",
    "$\\Delta q = I \\cdot \\Delta t$ (22.2)",
    "Công thức (22.2) cho thấy ý nghĩa của đơn vị điện lượng Cu-lông: 1 Cu-lông là tổng điện lượng của các hạt mang điện chạy qua tiết diện thẳng của dây dẫn trong 1 s bởi dòng điện có cường độ 1 A.",
    "Đơn vị của điện lượng: 1 C = 1 A.s.",
    "[Hình 22.2. Các điện tích dịch chuyển qua tiết diện thẳng của vật dẫn theo phương vuông góc với tiết diện của vật dẫn]",
    "",
    "**? Câu hỏi:**",
    "Trên một thiết bị dùng để nạp điện cho điện thoại di động có ghi thông số 10 000 mA.h. Thông số 10 000 mA.h cho biết điều gì?",
    "",
    "## II. LIÊN HỆ GIỮA CƯỜNG ĐỘ DÒNG ĐIỆN VỚI MẬT ĐỘ VÀ TỐC ĐỘ CỦA CÁC HẠT MANG ĐIỆN",
    "**1. Dòng điện chạy trong dây dẫn kim loại**",
    "Trong kim loại tồn tại các electron không liên kết với nguyên tử, được gọi là electron tự do vì chúng có thể chuyển động tự do về mọi hướng. Khi dây dẫn được nối với nguồn điện thì trong dây dẫn xuất hiện điện trường. Dưới tác dụng của lực điện trường, các electron mang điện tích âm dịch chuyển có hướng ngược với hướng của điện trường, tạo ra dòng điện (Hình 22.3).",
    "Người ta quy ước chiều dòng điện trong mạch là chiều từ cực dương sang cực âm của nguồn điện.",
    "Trong kim loại các electron tạo ra dòng điện dịch chuyển ngược chiều với chiều quy ước của dòng điện.",
    "[Hình 22.3. Sự tạo thành dòng điện trong kim loại. Gồm: Ion dương, Electron tự do]",
    "",
    "92",
    "CHƯƠNG IV – DÒNG ĐIỆN. MẠCH ĐIỆN",
    "",
    "**2. Biểu thức liên hệ giữa cường độ dòng điện với mật độ và tốc độ của các hạt mang điện**",
    "Nếu gọi:",
    "S là diện tích tiết diện thẳng của dây dẫn.",
    "n là mật độ hạt mang điện (ở đây là số electron tự do trong một đơn vị thể tích của dây dẫn).",
    "v là tốc độ dịch chuyển có hướng của electron.",
    "e là độ lớn điện tích của electron.",
    "Trong khoảng thời gian $\\Delta t$ số electron N chạy qua tiết diện thẳng của dây dẫn là: $N = n \\cdot S \\cdot h$, trong đó $h = v \\cdot \\Delta t$",
    "$N = n \\cdot S \\cdot v \\cdot \\Delta t$",
    "[Hình 22.4. Electron chạy qua tiết diện thẳng của dây dẫn]",
    "Do vậy, điện lượng chuyển qua tiết diện thẳng của dây dẫn trong khoảng thời gian $\\Delta t$ là:",
    "$\\Delta q = N \\cdot e = S \\cdot n \\cdot v \\cdot e \\cdot \\Delta t$.",
    "Theo định nghĩa cường độ dòng điện ở công thức (22.1), ta xác định được cường độ dòng điện chạy qua một dây dẫn kim loại như sau:",
    "$I = Snve$ (22.3)",
    "",
    "**3. Bài tập vận dụng**",
    "Một dây dẫn bằng kim loại, tiết diện tròn, có đường kính tiết diện là d = 2 mm, có dòng điện I = 5 A chạy qua. Cho biết mật độ electron tự do là $n = 8,45.10^{28}\\text{ electron/m}^3$. Hãy tính tốc độ dịch chuyển có hướng của các electron trong dây dẫn.",
    "",
    "*Giải:*",
    "Áp dụng công thức (22.3) ta có:",
    "$I = Snve$",
    "$\\Rightarrow v = \\frac{I}{nSe} = \\frac{I}{n\\frac{\\pi d^2}{4}e} = \\frac{4I}{n\\pi d^2 e}.$",
    "$= \\frac{I}{n\\frac{\\pi d^2}{4}e} = \\frac{4I}{n\\pi d^2 e}.$",
    "Thay số ta được: $v \\approx 1,2.10^{-4}\\text{ m/s} = 0,12\\text{ mm/s}.$",
    "",
    "93",
    "CHƯƠNG IV – DÒNG ĐIỆN. MẠCH ĐIỆN",
    "",
    "**EM ĐÃ HỌC**",
    "- Cường độ dòng điện là đại lượng đặc trưng cho tác dụng mạnh, yếu của dòng điện và được xác định bằng công thức: $I = \\frac{\\Delta q}{\\Delta t}$.",
    "- Biểu thức liên hệ giữa cường độ dòng điện trong dây dẫn kim loại với mật độ hạt mang điện tốc độ dịch chuyển có hướng của các hạt mang điện là:",
    "$I = Snve$.",
    "",
    "**EM CÓ THỂ**",
    "- Ước tính được cường độ dòng điện của tia sét trong các cơn dông.",
    "- Hiểu được ý nghĩa của thông số mA.h ghi trên pin, ắc quy và sạc dự phòng.",
    "- Giải thích được nguyên tắc đo điện tâm đồ.",
    "",
    "**EM CÓ BIẾT**",
    "Trong dung dịch điện phân tồn tại các ion dương và ion âm. Khi đóng mạch điện trong bình điện phân, các ion trong dung dịch chính là các hạt mang điện (Hình 22.5).",
    "[Hình 22.5. Ion dương và ion âm dịch chuyển trong dung dịch tạo ra dòng điện]",
    "",
    "94"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH4' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI11')), 'B22', 'Điện trở. Định luật Ôm', 97, 2, $JSON$
{
  "content": [
    "# Bài 23 ĐIỆN TRỞ. ĐỊNH LUẬT ÔM",
    "",
    "**Khởi động:**",
    "*Các thiết bị điện thông thường mà chúng ta dùng hằng ngày đều có các điện trở. Vậy điện trở đặc trưng cho tính chất nào của vật dẫn và tại sao một vật dẫn lại có điện trở?*",
    "",
    "## I. ĐIỆN TRỞ",
    "**1. Thí nghiệm**",
    "*Chuẩn bị:*",
    "- 1 ampe kế.",
    "- 1 vôn kế.",
    "- 1 nguồn có thể điều chỉnh thay đổi được hiệu điện thế.",
    "- Hai vật dẫn X và Y khác nhau.",
    "- Dây nối.",
    "- Khoá K.",
    "*Tiến hành:*",
    "- Mắc mạch điện như Hình vẽ 23.1.",
    "- Đóng khoá K. Điều chỉnh hiệu điện thế của nguồn ta thu được các giá trị của cường độ dòng điện $I_1$ chạy qua vật dẫn X, ghi kết quả vào mẫu Bảng 23.1.",
    "- Thay vật dẫn Y vào vị trí của vật dẫn X và lặp lại thí nghiệm, ta thu được các giá trị của cường độ dòng điện $I_2$ chạy qua vật dẫn Y, ghi kết quả vào mẫu Bảng 23.1.",
    "[Hình 23.1. Sơ đồ thí nghiệm đo cường độ dòng điện và hiệu điện thế ứng với các vật dẫn khác nhau]",
    "",
    "*Bảng 23.1.*",
    "| U (V) | Vật dẫn X, $I_1$ (mA) | Vật dẫn Y, $I_2$ (mA) |",
    "|---|---|---|",
    "| ? | ? | ? |",
    "| ? | ? | ? |",
    "| ? | ? | ? |",
    "| ? | ? | ? |",
    "| ? | ? | ? |",
    "| ? | ? | ? |",
    "| ? | ? | ? |",
    "| ? | ? | ? |",
    "",
    "**? Câu hỏi:**",
    "1. Hãy nhận xét về tỉ số $\\frac{U}{I}$ đối với từng vật dẫn X và vật dẫn Y.",
    "2. Đối với hai vật dẫn X và vật dẫn Y thì tỉ số $\\frac{U}{I}$ có khác nhau không?",
    "3. Nếu đặt cùng một hiệu điện thế vào hai đầu vật dẫn X và vật dẫn Y thì cường độ dòng điện chạy qua vật dẫn nào có giá trị nhỏ hơn?",
    "",
    "95",
    "CHƯƠNG IV – DÒNG ĐIỆN. MẠCH ĐIỆN",
    "",
    "**2. Định nghĩa điện trở**",
    "Từ kết quả tính tỉ số $\\frac{U}{I}$ của thí nghiệm ở trên cho thấy, ứng với mỗi vật dẫn thì tỉ số $\\frac{U}{I}$ là một hằng số.",
    "Kí hiệu hằng số trên là R, ta có: $R = \\frac{U}{I} \\Rightarrow I = \\frac{U}{R}$ (23.1)",
    "Biểu thức (23.1) cho thấy với cùng một hiệu điện thế, R càng lớn thì cường độ dòng điện I càng nhỏ. Điều này chứng tỏ vật dẫn đã cản trở sự dịch chuyển của các điện tích trong dây dẫn càng lớn. Như vậy, R là đại lượng đặc trưng cho mức độ cản trở dòng điện của vật dẫn và được gọi là điện trở.",
    "",
    "Điện trở của dây dẫn được kí hiệu là R (R là chữ cái đầu của từ tiếng Anh Resistance – cản trở).",
    "Trong công thức (23.1), hiệu điện thế U đo bằng vôn, cường độ dòng điện I đo bằng ampe thì điện trở đo bằng ohm (ôm), kí hiệu là $\\Omega$.",
    "$1\\Omega = \\frac{1\\text{ V}}{1\\text{ A}}$",
    "Một số bội số của ôm:",
    "$1\\text{ k}\\Omega = 1\\text{ }000\\text{ }\\Omega$.",
    "$1\\text{ M}\\Omega = 1\\text{ }000\\text{ k}\\Omega = 1\\text{ }000\\text{ }000\\text{ }\\Omega$.",
    "",
    "**3. Đường đặc trưng vôn – ampe**",
    "Đường đặc trưng vôn – ampe là đồ thị biểu diễn sự phụ thuộc giữa hiệu điện thế đặt vào và dòng điện chạy qua linh kiện đang xét.",
    "",
    "Bảng 23.2 là kết quả thí nghiệm đối với hai điện trở $R_1$ và $R_2$ theo thí nghiệm ở Mục 1. Từ bảng số liệu ta vẽ được đường đặc trưng vôn – ampe của hai điện trở $R_1$ và điện trở $R_2$ như Hình 23.2.",
    "Từ đường đặc trưng vôn - ampe ở Hình 23.2, ta thấy đồ thị là một đường thẳng, U tăng thì I cũng tăng. Như vậy đường đặc trưng vôn - ampe của điện trở là hàm bậc nhất xuất phát từ gốc toạ độ, ta có công thức:",
    "$I = kU$ (23.2)",
    "với $k = \\frac{1}{R}$ là hằng số không đổi gọi là độ dẫn điện.",
    "",
    "**EM CÓ BIẾT**",
    "Trong thiết bị điện tử điện trở là một linh kiện quan trọng. Tuỳ vào tỉ lệ pha trộn giữa hợp chất carbon và kim loại mà người ta tạo ra được các điện trở có trị số khác nhau.",
    "",
    "*Bảng 23.2. Kết quả thí nghiệm*",
    "| U (V) | Điện trở $R_1, I_1$ (mA) | Điện trở $R_2, I_2$ (mA) |",
    "|---|---|---|",
    "| 0,00 | 0,00 | 0,00 |",
    "| 1,0 | 0,43 | 0,21 |",
    "| 2,0 | 0,86 | 0,43 |",
    "| 3,0 | 1,30 | 0,65 |",
    "| 4,0 | 1,73 | 0,87 |",
    "| 5,0 | 2,17 | 1,09 |",
    "| 6,0 | 2,60 | 1,31 |",
    "| 7,0 | 3,03 | 1,53 |",
    "| 8,0 | 3,45 | 1,75 |",
    "",
    "[Hình 23.2. Đường đặc trưng vôn-ampe của hai điện trở R1 và R2]",
    "",
    "96",
    "CHƯƠNG IV – DÒNG ĐIỆN. MẠCH ĐIỆN",
    "",
    "Trường hợp đơn giản nhất là đặc trưng vôn – ampe của một điện trở R. Từ công thức $I = \\frac{U}{R}$, đường đặc trưng vôn - ampe là đường thẳng đi qua gốc toạ độ, có độ dốc càng lớn khi điện trở R càng nhỏ (Hình 23.3).",
    "[Hình 23.3. Đường đặc trưng vôn-ampe của điện trở R, Độ dốc = k = tan$\\alpha$]",
    "",
    "**? Câu hỏi:**",
    "1. Đường đặc trưng vôn-ampe của điện trở có đặc điểm gì? Đặc điểm này nói lên điều gì về mối quan hệ giữa hiệu điện thế U và cường độ dòng điện I.",
    "2. Độ dốc của đường đặc trưng vôn-ampe của điện trở liên quan đến điện trở như thế nào?",
    "",
    "*Bảng 23.2. Điện trở suất và hệ số nhiệt điện trở của một số kim loại*",
    "| Kim loại | $\\rho_0 (\\Omega\\text{.m})$ | $\\alpha\\text{ (K}^{-1})$ |",
    "|---|---|---|",
    "| Bạc | $1,62.10^{-8}$ | $4,1.10^{-3}$ |",
    "| Đồng | $1,69.10^{-8}$ | $4,3.10^{-3}$ |",
    "| Nhôm | $2,75.10^{-8}$ | $4,4.10^{-3}$ |",
    "| Sắt | $9,68.10^{-8}$ | $6,5.10^{-3}$ |",
    "| Bạch kim | $10,60.10^{-8}$ | $3,9.10^{-3}$ |",
    "| Vonfam | $5,25.10^{-8}$ | $4,5.10^{-3}$ |",
    "",
    "## II. ĐỊNH LUẬT OHM",
    "Mối quan hệ giữa hiệu điện thế U, cường độ dòng điện I và điện trở R của vật dẫn kim loại đã được nhà bác học người Đức Georg Simon Ohm (1789 – 1854) xác định bằng thực nghiệm và phát biểu thành định luật, gọi là định luật Ohm:",
    "**Định luật Ohm:** *Cường độ dòng điện chạy qua vật dẫn kim loại tỉ lệ thuận với hiệu điện thế ở hai đầu vật dẫn, tỉ lệ nghịch điện trở của vật dẫn.*",
    "Biểu thức: $I = \\frac{U}{R}$ (23.3)",
    "trong đó: I là cường độ dòng điện chạy qua vật dẫn, đơn vị là ampe, kí hiệu là (A).",
    "U là hiệu điện thế giữa hai đầu vật dẫn, đơn vị là vôn, kí hiệu là (V).",
    "R là điện trở của vật dẫn, đơn vị là ohm, kí hiệu là ($\\Omega$).",
    "",
    "## III. NGUYÊN NHÂN GÂY RA ĐIỆN TRỞ VÀ ẢNH HƯỞNG CỦA NHIỆT ĐỘ LÊN ĐIỆN TRỞ",
    "**1. Nguyên nhân gây ra điện trở trong vật dẫn kim loại**",
    "Trong kim loại, các nguyên tử bị mất electron hoá trị trở thành các ion dương. Các ion dương liên kết với nhau một cách trật tự tạo nên mạng tinh thể kim loại. Chuyển động nhiệt của các ion có thể phá vỡ trật tự này. Nhiệt độ càng cao dao động nhiệt càng mạnh, mạng tinh thể càng trở nên mất trật tự. Sự mất trật tự của mạng tinh thể cản trở chuyển động của electron tự do, là nguyên nhân gây ra điện trở của kim loại (Hình 23.4).",
    "",
    "97",
    "CHƯƠNG IV – DÒNG ĐIỆN. MẠCH ĐIỆN",
    "",
    "[Hình 23.4. Mô hình nguyên nhân gây ra điện trở trong kim loại]",
    "a) Ở nhiệt độ thấp, các electron tự do chuyển động tương đối dễ dàng.",
    "b) Ở nhiệt độ cao, các electron tự do bị cản trở chuyển động do sự dao động của các ion, gây ra sự va chạm giữa electron và ion.",
    "c) Các nguyên tử tạp chất cũng là nguyên nhân cản trở chuyển động của các electron.",
    "",
    "**? Câu hỏi:**",
    "Vận dụng công thức $I = Snve$ để giải thích tại sao điện trở R của vật dẫn kim loại lại phụ thuộc vào chiều dài $l$, tiết diện S và điện trở suất $\\rho$ của dây theo công thức $R = \\frac{\\rho l}{S}$.",
    "",
    "**2. Ảnh hưởng của nhiệt độ lên điện trở**",
    "a) Điện trở của đèn sợi đốt",
    "Dòng điện chạy qua điện trở có tác dụng làm nóng điện trở. Nguyên lí này này được sử dụng trong các bộ phận sưởi ấm, và cả trong dây tóc của bóng đèn sợi đốt. Hiệu ứng đốt nóng xảy ra do các electron va chạm với các nguyên tử. Khi electron chạy qua một vật dẫn điện, electron bị mất năng lượng. Các nguyên tử thu được năng lượng và dao động nhanh hơn. Sự dao động xảy ra nhanh hơn có nghĩa là nhiệt độ cao hơn.",
    "[Hình 23.5. Đường đặc trưng vôn-ampe của điện trở dây tóc bóng đèn]",
    "Dòng điện chạy qua dây tóc của bóng đèn sinh nhiệt, làm cho dây tóc nóng lên do đó điện trở của dây tóc thay đổi trong quá trình khảo sát. Khi dòng điện và hiệu điện thế nhỏ, đường đặc trưng vôn-ampe gần đúng là đường thẳng. Ở hiệu điện thế cao hơn, đường đặc trưng bắt đầu cong (Hình 23.5). Điều này cho thấy rằng điện trở của dây tóc bóng đèn tăng lên vì tỉ số $\\frac{U}{I}$ tăng lên.",
    "Trên đường đặc trưng, khi dây tóc bóng đèn phát sáng thì đường đặc trưng có độ dốc nhỏ nên điện trở lớn. Do vậy, ta thấy điện trở của dây tóc bóng đèn phụ thuộc vào nhiệt độ.",
    "",
    "98",
    "CHƯƠNG IV – DÒNG ĐIỆN. MẠCH ĐIỆN",
    "",
    "b) Điện trở nhiệt",
    "Điện trở nhiệt (thermistor) là linh kiện có điện trở thay đổi một cách rõ rệt theo nhiệt độ. Điện trở nhiệt được ứng dụng rộng rãi trong kĩ thuật điện tử, làm cảm biến nhiệt (Hình 23.6).",
    "Để khảo sát sự phụ thuộc của nhiệt điện trở NTC (Negative Temperature Coefficent) vào nhiệt độ người ta làm thí nghiệm như sau:",
    "- Bố trí thí nghiệm như Hình 23.7.",
    "- Đặt nhiệt điện trở vào giữa bình, đặt nhiệt kế vào trong bình, cạnh nhiệt điện trở.",
    "- Đổ nước mát vào bình cách nhiệt. Sau khoảng 2 phút, đo nhiệt độ của nước và điện trở của nhiệt điện trở.",
    "- Tăng nhiệt độ của nước trong bình bằng cách thêm từ từ nước sôi vào nước trong bình. Chờ nhiệt độ của nước trong bình ổn định. Đo nhiệt độ của nước và điện trở của nhiệt điện trở.",
    "- Lặp lại thao tác để đo nhiệt độ và điện trở của nhiệt điện trở ở các nhiệt độ khác.",
    "",
    "Kết quả thí nghiệm thu được như trong Bảng 23.3.",
    "[Hình 23.6. Điện trở nhiệt (NTC Thermistor, PTC Thermistor)]",
    "[Hình 23.7. Sơ đồ thí nghiệm khảo sát sự phụ thuộc nhiệt độ của điện trở nhiệt]",
    "",
    "*Bảng 23.3. Kết quả thí nghiệm*",
    "| Nhiệt độ ($^\\circ\\text{C}$) | Điện trở ($\\Omega$) |",
    "|---|---|",
    "| 5 | 121951,2 |",
    "| 9 | 99206,3 |",
    "| 15 | 73529,4 |",
    "| 19 | 60532,7 |",
    "| 26 | 43478,3 |",
    "| 32 | 33333,3 |",
    "| 37 | 26595,7 |",
    "| 41 | 22522,5 |",
    "| 49 | 16077,2 |",
    "| 53 | 13661,2 |",
    "| 58 | 11160,7 |",
    "| 62 | 9542,0 |",
    "| 68 | 7564,3 |",
    "| 74 | 6016,8 |",
    "| 80 | 4807,7 |",
    "",
    "[Hình 23.8. Đường đặc trưng vôn-ampe của nhiệt điện trở NTC]",
    "Từ số liệu trong Bảng 23.3, ta vẽ được đường đặc trưng vôn-ampe của điện trở nhiệt NTC như Hình 23.8.",
    "",
    "99",
    "CHƯƠNG IV – DÒNG ĐIỆN. MẠCH ĐIỆN",
    "",
    "Ngoài nhiệt điện trở NTC, trong thực tế còn có loại nhiệt điện trở PTC (Positive Temperature Coefficient). Điện trở của nhiệt điện trở PTC tăng khi nhiệt độ tăng.",
    "",
    "**? Câu hỏi:**",
    "Từ kết quả thí nghiệm em rút ra nhận xét gì về sự phụ thuộc của nhiệt điện trở NTC vào nhiệt độ?",
    "",
    "**? Câu hỏi:**",
    "Hai đồ thị trong Hình 23.9a, b mô tả đường đặc trưng vôn - ampe của một dây kim loại ở hai nhiệt độ khác nhau $t_1$ và $t_2$.",
    "a) Tính điện trở của dây kim loại ứng với mỗi nhiệt độ $t_1$ và $t_2$.",
    "b) Dây kim loại ở đồ thị nào có nhiệt độ cao hơn?",
    "[Hình 23.9. Đường đặc trưng vôn-ampe của một dây kim loại ở hai nhiệt độ khác nhau a) và b)]",
    "",
    "**Hoạt động:**",
    "Đồ thị Hình 24.10 thể hiện đường đặc trưng vôn-ampe của hai linh kiện là dây tóc bóng đèn và dây kim loại.",
    "a) Xác định đường nào là của dây tóc bóng đèn, đường nào là của dây kim loại.",
    "b) Xác định hiệu điện thế mà tại đó dây tóc bóng đèn và dây kim loại có điện trở như nhau.",
    "c) Xác định điện trở ứng với hiệu điện thế xác định được ở câu b.",
    "[Hình 23.10. Đường đặc trưng vôn-ampe của điện trở dây tóc bóng đèn và điện trở dây kim loại (đường X cong, đường Y thẳng)]",
    "",
    "100",
    "CHƯƠNG IV – DÒNG ĐIỆN. MẠCH ĐIỆN",
    "",
    "**EM ĐÃ HỌC**",
    "- Điện trở là đại lượng đặc trưng cho mức độ cản trở dòng điện của vật dẫn. Đơn vị của điện trở là (ôm), kí hiệu là $\\Omega$.",
    "- Định luật Ôm: Cường độ dòng điện chạy qua vật dẫn kim loại tỉ lệ thuận với hiệu điện thế ở hai đầu vật dẫn, tỉ lệ nghịch điện trở của vật dẫn: $I = \\frac{U}{R}$.",
    "- Điện trở kim loại phụ thuộc vào nhiệt độ theo gần đúng là hàm bậc nhất $R = R_0[1 + \\alpha(t - t_0)]$.",
    "- Nhiệt điện trở là loại điện trở có giá trị thay đổi đáng kể theo nhiệt độ. Có hai loại nhiệt điện trở NTC và PTC.",
    "",
    "**EM CÓ THỂ**",
    "- Giải thích được nguyên nhân gây ra điện trở trong kim loại.",
    "- Hiểu được tại sao khi sử dụng đèn LED lại tiết kiệm năng lượng điện hơn so với bóng đèn dây tóc.",
    "",
    "**EM CÓ BIẾT**",
    "**Hiện tượng siêu dẫn**",
    "Hiện tượng siêu dẫn là hiện tượng một số kim loại và hợp kim khi nhiệt độ thấp hơn một nhiệt độ tới hạn $T_c$ thì điện trở của nó đột ngột giảm xuống bằng 0.",
    "Khi vật dẫn ở trạng thái siêu dẫn, điện trở của nó gần bằng 0. Vì vậy, nếu trong một vòng dây siêu dẫn có dòng điện chạy qua thì dòng điện này có thể duy trì rất lâu, sau khi bỏ nguồn điện đi. Các vật siêu dẫn có nhiều ứng dụng trong thực tế. Người ta chế tạo ra những nam châm điện có cuộn dây bằng vật liệu siêu dẫn, có thể tạo ra từ trường mạnh trong thời gian dài mà không hao phí năng lượng vì toả nhiệt.",
    "",
    "*Bảng 23.4. Giá trị $T_c$ (K) của một số kim loại, hợp kim*",
