INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH4' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI11')), 'B23', 'Nguồn điện', 104, 3, $JSON$
{
  "content": [
    "# Bài 24 NGUỒN ĐIỆN",
    "",
    "**Khởi động:**",
    "*Em đã biết nguồn điện có khả năng cung cấp năng lượng điện để tạo ra dòng điện sử dụng trong đời sống. Vậy nguồn điện là gì? Vì sao nguồn điện có thể tạo ra dòng điện?*",
    "",
    "## I. NGUỒN ĐIỆN. SUẤT ĐIỆN ĐỘNG CỦA NGUỒN ĐIỆN",
    "**1. Điều kiện để duy trì dòng điện**",
    "Giả sử có hai quả cầu kim loại A và B giống nhau, quả cầu A mang điện tích +q và quả cầu B mang điện tích -q. Giữa quả cầu A và B có một hiệu điện thế $U_{AB} = V_A - V_B$ (Hình 24.1a).",
    "Khi nối quả cầu A với quả cầu B bằng một sợi dây kim loại, dưới tác dụng của lực điện các electron tự do dịch chuyển từ quả cầu B sang quả cầu A tạo thành dòng điện trong mạch (Hình 24.1b). Tuy nhiên, dòng điện này không tồn tại lâu dài, mà chỉ tồn tại trong thời gian rất ngắn, khi $V_A = V_B$ thì không còn tồn tại dòng điện trong mạch (Hình 24.1c)",
    "[Hình 24.1. Sự tạo thành dòng điện giữa hai quả cầu mang điện tích, a, b, c]",
    "",
    "**? Câu hỏi:**",
    "Tại sao dòng điện trong trường hợp mô tả ở Hình 24.1 chỉ tồn tại trong khoảng thời gian rất ngắn? Làm thế nào để duy trì dòng điện trong trường hợp này lâu dài?",
    "",
    "**2. Nguồn điện**",
    "Nguồn điện là thiết bị để tạo ra và duy trì hiệu điện thế, nhằm duy trì dòng điện trong mạch. Mỗi nguồn điện đều có hai cực là cực dương (+) và cực âm (-). Nguồn điện được kí hiệu như Hình 24.2. Hiệu điện thế giữa hai cực của nguồn điện được duy trì ngay cả khi có dòng điện chạy qua các vật dẫn nối liền giữa hai cực của nó, có nghĩa là sự tích điện khác nhau ở các cực của nguồn điện tiếp tục được duy trì.",
    "[Hình 24.2. Kí hiệu nguồn điện]",
    "",
    "Để tạo ra các điện cực như vậy, trong nguồn điện phải có lực thực hiện công để tách các electron ra khỏi nguyên tử, sau đó chuyển các electron hoặc ion dương được tạo thành như thế ra khỏi mỗi cực. Khi đó một cực thừa electron được gọi là cực âm, cực còn lại thiếu electron hoặc thừa ít electron hơn cực kia gọi là cực dương. Việc tách các electron ra khỏi",
    "",
    "102",
    "CHƯƠNG IV – DÒNG ĐIỆN. MẠCH ĐIỆN",
    "",
    "nguyên tử không phải do lực điện thực hiện mà phải do các lực có bản chất khác với lực điện thực hiện, được gọi là các lực lạ.",
    "",
    "**3. Suất điện động của nguồn điện**",
    "Khi nối hai cực của nguồn điện bằng một vật dẫn tạo thành mạch kín thì trong mạch có dòng điện. Nếu vật dẫn làm bằng kim loại thì chỉ có sự dịch chuyển của các electron tự do từ cực âm, qua vật dẫn đến cực dương (Hình 24.3). Bên trong nguồn điện, dưới tác dụng của lực lạ, các hạt tải điện dương lại dịch chuyển ngược chiều điện trường từ cực âm đến cực dương. Khi đó, lực lạ thực hiện một công thắng công cản của trường tĩnh điện bên trong nguồn điện.",
    "[Hình 24.3. Sự di chuyển của các điện tích dương và electron bên trong nguồn điện]",
    "",
    "Để đặc trưng cho khả năng thực hiện công của nguồn điện người ta đưa ra đại lượng gọi là suất điện động của nguồn điện, kí hiệu là $\\mathscr{E}$.",
    "Suất điện động $\\mathscr{E}$ của nguồn điện là đại lượng đặc trưng cho khả năng thực hiện công của nguồn điện và đo bằng thương số giữa công A của lực lạ thực hiện khi làm dịch chuyển một điện tích dương q bên trong nguồn điện từ cực âm đến cực dương và độ lớn của điện tích q đó:",
    "$\\mathscr{E} = \\frac{A}{q}$ (24.1)",
    "Đơn vị của suất điện động là vôn, kí hiệu là V.",
    "Số vôn ghi trên mỗi nguồn điện cho biết trị số của suất điện động của nguồn điện đó. Số vôn này cũng là giá trị của hiệu điện thế giữa hai cực của nguồn điện khi mạch điện hở.",
    "",
    "## II. ẢNH HƯỞNG CỦA ĐIỆN TRỞ TRONG CỦA NGUỒN ĐIỆN LÊN HIỆU ĐIỆN THẾ GIỮA HAI CỰC CỦA NGUỒN",
    "**1. Điện trở trong của nguồn**",
    "Trong mạch điện kín, dòng điện chạy qua mạch ngoài và bên trong nguồn điện. Như vậy, nguồn điện cũng là một vật dẫn và cũng có điện trở. Điện trở này được gọi là điện trở trong của nguồn điện. Vì vậy, mỗi nguồn điện được đặc trưng bằng suất điện động $\\mathscr{E}$ và điện trở trong r của nguồn.",
    "Trong mạch kín khi đo hiệu điện thế giữa hai đầu của nguồn, ta luôn nhận được một giá trị hiệu điện thế nhỏ hơn giá trị suất điện động của nguồn. Lí do này có một vài nguyên nhân nhưng nguyên nhân quan trọng nhất đó là các nguồn điện đều có điện trở trong.",
    "",
    "**2. Ảnh hưởng của điện trở trong của nguồn điện lên hiệu điện thế giữa hai cực của nguồn**",
    "Để dễ hình dung, ta tưởng tượng tách điện trở trong r của nguồn ra bên ngoài, khi đó nguồn điện được xem là lí tưởng, không có điện trở trong. Nguồn điện lúc này được xem như mắc cùng một điện trở r như mô tả ở trong phần đường đứt nét (Hình 24.4).",
    "",
    "103",
    "CHƯƠNG IV – DÒNG ĐIỆN. MẠCH ĐIỆN",
    "",
    "[Hình 24.4. Điện trở trong r của nguồn điện trong sơ đồ mạch điện]",
    "Khi mắc nguồn điện với mạch ngoài bởi điện trở R. Khi đó, điện trở của mạch gồm điện trở mạch ngoài R mắc nối tiếp với điện trở trong r. Giả sử dòng điện chạy trong mạch có cường độ I thì trong khoảng thời gian t có điện lượng $q = It$ chuyển qua mạch. Nguồn điện đã thực hiện công A, theo công thức (24.1), công A có giá trị:",
    "$A = q\\mathscr{E} = \\mathscr{E}It$ (24.2)",
    "Cũng trong khoảng thời gian t đó nhiệt lượng toả ra ở điện trở ngoài R và điện trở trong r là:",
    "$Q = RI^2t + rI^2t$ (24.3)",
    "Theo định luật bảo toàn năng lượng, năng lượng tiêu thụ trên toàn mạch phải bằng năng lượng do nguồn điện cung cấp. Từ công thức (24.2) và (24.3), ta có:",
    "$\\mathscr{E}It = RI^2t + rI^2t$",
    "hay $\\mathscr{E} = IR + Ir = I(R + r)$ (24.4)",
    "",
    "Người ta gọi tích số của cường độ dòng điện với điện trở của đoạn mạch là độ giảm thế trên đoạn mạch. Như vậy, theo công thức (24.4) ta có suất điện động của nguồn điện có giá trị bằng tổng các độ giảm thế ở mạch ngoài và mạch trong.",
    "Nếu gọi $U = IR$ là hiệu điện thế mạch ngoài thì công thức (24.4) được viết lại là:",
    "$U = \\mathscr{E} - Ir$ (24.5)",
    "Hiệu điện thế mạch ngoài cũng là hiệu điện thế giữa hai cực dương và âm của nguồn điện.",
    "",
    "**? Câu hỏi:**",
    "Khi dùng vôn kế để đo hiệu điện thế giữa hai cực của nguồn điện thì số chỉ trên vôn kế và số vôn ghi trên nhãn của nguồn điện có mối liên hệ như thế nào? Điều đó cho biết có gì tồn tại bên trong của nguồn điện?",
    "",
    "**EM CÓ BIẾT**",
    "Từ các hệ thức (24.4) ta có:",
    "$I = \\frac{\\mathscr{E}}{R + r}$",
    "Với (R + r) là tổng điện trở của mạch ngoài và điện trở trong của nguồn điện, được gọi là điện trở toàn phần của mạch điện kín.",
    "Hệ thức $I = \\frac{\\mathscr{E}}{R + r}$ biểu thị định luật Ôm đối với toàn mạch, được phát biểu như sau:",
    "*Cường độ dòng điện chạy trong mạch điện kín tỉ lệ thuận với suất điện động của nguồn điện và tỉ lệ nghịch với điện trở toàn phần của mạch điện đó.*",
    "",
    "**? Câu hỏi:**",
    "Từ biểu thức (24.5), hãy:",
    "1. Mô tả ảnh hưởng của điện trở trong của nguồn điện lên hiệu điện thế giữa hai cực của nguồn.",
    "2. So sánh suất điện động và hiệu điện thế giữa hai đầu đoạn mạch.",
    "3. Trường hợp nào thì hiệu điện thế U giữa hai cực của nguồn điện bằng suất điện động $\\mathscr{E}$ của nguồn?",
    "",
    "104",
    "CHƯƠNG IV – DÒNG ĐIỆN. MẠCH ĐIỆN",
    "",
    "**EM CÓ BIẾT**",
    "Hiện tượng đoản mạch (hay còn gọi là ngắn mạch) xảy ra khi nguồn điện được nối với mạch ngoài có điện trở không đáng kể hoặc bằng 0, nguyên nhân do việc chập mạch điện làm cho điện trở của dây dẫn bằng 0, khi đó cực âm của nguồn nối trực tiếp với cực dương của nguồn mà không qua thiết bị điện.",
    "",
    "**3. Bài tập luyện tập**",
    "1. Cho mạch điện như Hình 24.5. Suất điện động $\\mathscr{E} = 10\\text{ V}$, bỏ qua điện trở trong của nguồn. Các giá trị điện trở $R_1 = 20\\text{ }\\Omega$, $R_2 = 40\\text{ }\\Omega$, $R_3 = 50\\text{ }\\Omega$.",
    "a) Tính cường độ dòng điện chạy qua điện trở $R_1$.",
    "b) Tính cường độ dòng điện I chạy qua mạch chính.",
    "2. Cho mạch điện như Hình 24.6. Các giá trị điện trở $R_1 = 3\\text{ }\\Omega$, $R_2 = 4\\text{ }\\Omega$ và $R_3 = 6\\text{ }\\Omega$. Suất điện động của nguồn $\\mathscr{E} = 12\\text{ V}$, điện trở trong của nguồn $r = 0,6\\text{ }\\Omega$.",
    "a) Tính điện trở của đoạn mạch AB.",
    "b) Tính cường độ dòng điện chạy qua các điện trở $R_1, R_2, R_3$ và hiệu điện thế giữa hai đầu mỗi điện trở.",
    "",
    "[Hình 24.5]",
    "[Hình 24.6]",
    "",
    "**? Câu hỏi:**",
    "Vì sao sẽ rất nguy hiểm nếu hiện tượng đoản mạch xảy ra đối với mạng điện ở gia đình?",
    "",
    "**EM ĐÃ HỌC**",
    "- Suất điện động $\\mathscr{E}$ của nguồn điện là đại lượng đặc trưng cho khả năng thực hiện công của nguồn điện và đo bằng thương số giữa công A của lực lạ thực hiện khi làm dịch chuyển một điện tích dương q bên trong nguồn điện từ cực âm đến cực dương và độ lớn của điện tích q đó.",
    "$\\mathscr{E} = \\frac{A}{q}$",
    "Đơn vị của suất điện động là vôn, kí hiệu là V.",
    "- Mối liên hệ giữa suất điện động và hiệu điện thế mạch ngoài:",
    "$\\mathscr{E} = U + Ir \\text{ hay } U = \\mathscr{E} - Ir$.",
    "",
    "**EM CÓ THỂ**",
    "- Mô tả được ảnh hưởng của điện trở trong của nguồn điện lên hiệu điện thế giữa hai cực của nguồn điện.",
    "- Xác định được cường độ dòng điện, điện trở trong của pin mặt trời.",
    "",
    "105"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH4' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI11')), 'B24', 'Năng lượng và công suất điện', 108, 4, $JSON$
{
  "content": [
    "# Bài 25 NĂNG LƯỢNG VÀ CÔNG SUẤT ĐIỆN",
    "",
    "**Khởi động:**",
    "[Hình ảnh Bảng bên ghi một số nội dung trong Hoá đơn tiền điện]",
    "*Bảng bên ghi một số nội dung trong Hoá đơn tiền điện giá trị gia tăng (GTGT) của Công ty điện lực. Em hãy cho biết ý nghĩa của các số liệu trong bảng.*",
    "",
    "## I. NĂNG LƯỢNG ĐIỆN",
    "Khi đặt hiệu điện thế U vào hai đầu của một mạch tiêu thụ điện, dưới tác dụng của lực điện, các điện tích tự do trong mạch điện chuyển dời có hướng tạo ra dòng điện. Ta đã biết công của lực điện trong trường hợp này được tính bằng công thức: $A = qU$.",
    "Nếu t là thời gian dòng điện chạy trong mạch thì cường độ dòng điện là $I = \\frac{q}{t}$, thì công của lực điện là:",
    "$A = UIt$ (25.1)",
    "Ở đây A là số đo năng lượng điện mà đoạn mạch nhận được (tiêu thụ) từ nguồn điện và được gọi là năng lượng điện tiêu thụ của đoạn mạch. Do đó:",
    "*Năng lượng điện tiêu thụ của đoạn mạch bằng công của lực điện thực hiện khi di chuyển các điện tích.*",
    "$W = A = UIt$ (25.2)",
    "Đơn vị của năng lượng điện tiêu thụ là jun, kí hiệu là J.",
    "Dòng điện chạy trong đoạn mạch gây ra các tác dụng khác nhau và khi đó có sự chuyển hoá năng lượng điện tiêu thụ của đoạn mạch thành các dạng năng lượng khác.",
    "[Hình 25.1. Một số thiết bị dùng điện. Gồm: a) Xe đạp điện, b) Ấm đun nước, c) Bóng đèn sợi đốt, d) Bóng đèn LED]",
    "",
    "106",
    "CHƯƠNG IV – DÒNG ĐIỆN. MẠCH ĐIỆN",
    "",
    "**? Câu hỏi:**",
    "1. Năng lượng điện tiêu thụ trong dụng cụ, thiết bị dùng điện ở Hình 25.1 chuyển hoá thành dạng năng lượng nào là nhiều nhất?",
    "2. Hãy chứng minh rằng, nếu đoạn mạch chỉ có điện trở R (đoạn mạch thuần điện trở) thì nhiệt lượng đoạn mạch toả ra khi có dòng điện chạy qua được tính bằng công thức:",
    "$Q = I^2Rt = \\frac{U^2}{R}t$ (25.3)",
    "",
    "Ngoài đơn vị Jun, người ta còn dùng đơn vị kilôoát giờ (kW.h) để đo năng lượng điện tiêu thụ. 1 kW.h = 3,6.10$^6$ J.",
    "",
    "**EM CÓ BIẾT**",
    "Người ta đo năng lượng điện tiêu thụ bằng một thiết bị gọi là công tơ điện (Hình 25.2). Khi các dụng cụ, thiết bị tiêu thụ năng lượng điện hoạt động thì đĩa của công tơ quay, số chỉ của công tơ tăng dần. Đơn vị của chỉ số trên công tơ là kW.h. Trong đời sống người ta thường gọi 1 kW.h là 1 số điện.",
    "[Hình 25.2. Công tơ điện]",
    "",
    "## II. CÔNG SUẤT ĐIỆN",
    "Công suất tiêu thụ năng lượng điện (gọi tắt là công suất điện) của một đoạn mạch là năng lượng điện mà mạch tiêu thụ trong một đơn vị thời gian:",
    "$\\mathscr{P} = \\frac{A}{t} = UI$ (25.4)",
    "Đơn vị của công suất điện là Oát, kí hiệu là W.",
    "",
    "**? Câu hỏi:**",
    "Hãy chứng minh rằng 1 kW.h = 3,6.10$^6$ J.",
    "",
    "*Bảng 25.1. Công suất điện của một số thiết bị dùng điện*",
    "| Thiết bị | Công suất điện | Thiết bị | Công suất điện |",
    "|---|---|---|---|",
    "| Đèn tuýp LED 1,2 m | 25 W | Tủ lạnh | 100 W |",
    "| Bóng đèn huỳnh quang 1,2 m | 36 W | Máy giặt | 470 W |",
    "",
    "107",
    "CHƯƠNG IV – DÒNG ĐIỆN. MẠCH ĐIỆN",
    "",
    "| Bóng đèn sợi đốt | 40 W | Nồi cơm điện | 600 W |",
    "|---|---|---|---|",
    "| Quạt cây | 55 W | Bàn là | 1 000 W |",
    "| Tivi LED 32 inches | 69 W | Điều hòa 9 000BTU | 2 638 W |",
    "",
    "**EM CÓ BIẾT**",
    "Nếu trên dụng cụ hoặc thiết bị dùng điện ghi 220 V - 100 W, thì phải hiểu là chỉ khi nào dụng cụ hoặc thiết bị được dùng ở đúng hiệu điện thế U = 220 V (bằng với *hiệu điện thế định mức*) thì công suất điện của nó mới bằng 100 W. Công suất này được gọi là công suất định mức.",
    "",
    "**Hoạt động:**",
    "1. Trên hoá đơn GTGT (tiền điện) ở đầu bài học, tiền điện được tính luỹ tiến (càng dùng điện nhiều thì đơn giá của 1 kW.h điện càng tăng). Theo em, cách tính này nhằm những mục đích gì? Tại sao?",
    "2. Cho các thông tin về bóng đèn sợi đốt và bóng đèn LED cùng có độ sáng như sau:",
    "[Hình ảnh bóng đèn sợi đốt và bóng đèn LED cùng các thông số]",
    "| | Đèn sợi đốt | Đèn LED |",
    "|---|---|---|",
    "| Giản đồ phân phối năng lượng | Điện năng 100J -> Ánh sáng nhìn thấy 5J, Nhiệt năng 95J | Điện năng 100J -> Ánh sáng nhìn thấy 80J, Nhiệt năng 20J |",
    "| | 220 V - 100 W | 220 V - 20 W |",
    "| Thời gian hoạt động | 1 000 h | 30 000 h |",
    "| Giá tiền/bóng | 8 000 đồng | 48 000 đồng |",
    "| Giá tiền điện | \\multicolumn{2}{c|}{2 000 đồng/kW.h} |",
    "",
    "Giả sử trung bình mỗi bóng đèn sử dụng 5 h/ngày, em hãy tính tiền điện phải trả cho từng bóng đèn mỗi tháng và trong 30 000 h, từ đó lập luận để so sánh về hiệu quả kinh tế khi sử dụng hai loại bóng trên.",
    "",
    "108",
    "CHƯƠNG IV – DÒNG ĐIỆN. MẠCH ĐIỆN",
    "",
    "## III. BÀI TẬP",
    "**1. Bài tập ví dụ**",
    "Trên nhãn của một ấm điện có ghi 220 V - 1 000 W. Sử dụng ấm điện này ở hiệu điện thế 200 V để đun sôi 2 lít nước từ nhiệt độ $20\\text{ }^\\circ\\text{C}$. Tính thời gian đun nước. Biết hiệu suất của ấm là 90%, nhiệt dung riêng của nước là 4 190 J/kg.K, coi điện trở của ấm điện không thay đổi so với khi hoạt động ở chế độ bình thường.",
    "*Giải:*",
    "Nhiệt lượng cần để đun sôi 2 lít nước từ $20\\text{ }^\\circ\\text{C}$:",
    "$Q = mc.\\Delta t = 2.4\\ 190.(100 - 20) = 670\\ 400\\text{ J}$",
    "Hiệu suất của ấm H = 90% nên năng lượng điện tiêu thụ của ấm là:",
    "$A = \\frac{Q}{H} = \\frac{670\\ 400}{0,9} \\approx 744\\ 889\\text{ J}$",
    "Điện trở của ấm điện",
    "$R = \\frac{U_{dm}^2}{\\mathscr{P}_{dm}} = \\frac{220^2}{1000} = 48,4\\text{ }\\Omega$",
    "Từ công thức $A = \\frac{U^2}{R}.t$, suy ra thời gian đun nước thời gian đun nước:",
    "$t = \\frac{AR}{U^2} = \\frac{744\\ 889.48,4}{200^2} \\approx 901\\text{ s}.$",
    "",
    "**2. Bài tập**",
    "1. Trên nhãn của bóng đèn 1 có ghi 220 V - 20 W và bóng đèn 2 có ghi 220 V - 10 W. Coi điện trở của mỗi bóng đèn không thay đổi.",
    "a) Tính năng lượng điện tiêu thụ của mỗi bóng đèn khi sử dụng ở hiệu điện thế 200 V trong thời gian 2 giờ.",
    "b) Tính tổng công suất điện tiêu thụ của cả hai bóng đèn trong những trường hợp sau:",
    "- Mắc song song hai bóng đèn vào hiệu điện thế 220 V.",
    "- Mắc nối tiếp hai bóng đèn vào hiệu điện thế 220 V.",
    "c) Dùng cách mắc nào nêu trên để cả hai bóng đèn đều sáng bình thường? Tại sao?",
    "2. Thông thường, ở nước ta hiệu điện thế mạng điện trong các gia đình, trường học,... là 220 V. Em hãy tìm hiểu về hiệu điện thế định mức, công suất định mức của mỗi thiết bị điện, cách mắc các thiết bị điện dùng trong lớp học của em và thời gian sử dụng trung bình của từng thiết bị mỗi tháng để làm các việc sau:",
    "a) Vẽ lại sơ đồ mạch điện.",
    "b) Áp dụng giá điện trong Hoá đơn GTGT (tiền điện) ở đầu của bài học để dự tính tiền điện trung bình phải trả mỗi tháng cho lớp học.",
    "c) Hãy đề xuất phương án sử dụng tiết kiệm điện cho gia đình, lớp học.",
    "",
    "109",
    "CHƯƠNG IV – DÒNG ĐIỆN. MẠCH ĐIỆN",
    "",
    "**EM ĐÃ HỌC**",
    "- Năng lượng điện tiêu thụ của đoạn mạch được đo bằng công của lực điện thực hiện khi dịch chuyển các điện tích. Công thức tính công của lực điện A = qU = UIt. Đơn vị là Jun, kí hiệu là J.",
    "- Đối với đoạn mạch thuần điện trở, nhiệt lượng đoạn mạch toả ra khi dòng điện chạy qua được tính bằng công thức: $Q = RI^2t$.",
    "- Công suất tiêu thụ năng lượng điện của một đoạn mạch là năng lượng điện mà đoạn mạch tiêu thụ trong một đơn vị thời gian. Công thức tính:",
    "$\\mathscr{P} = \\frac{A}{t} = UI$. Đơn vị là Oát, kí hiệu là W.",
    "",
    "**EM CÓ THỂ**",
    "- Giải thích được nội dung ghi trong hoá đơn tiền điện và ý nghĩa của việc tính giá điện luỹ tiến; lợi ích của việc thay đèn sợi đốt bằng đèn LED.",
    "- Ước tính được số tiền điện trung bình mỗi tháng phải trả cho các dụng cụ và thiết bị điện dùng trong nhà và các biện pháp tiết kiệm năng lượng điện tiêu thụ.",
    "",
    "110"
  ]
}
