INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH4' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI11')), 'B25', 'Thực hành: Đo suất điện động và điện trở trong của pin điện hoá', 113, 5, $JSON$
{
  "content": [
    "# Bài 26 THỰC HÀNH: ĐO SUẤT ĐIỆN ĐỘNG VÀ ĐIỆN TRỞ TRONG CỦA PIN ĐIỆN HOÁ",
    "",
    "**Khởi động:**",
    "*Pin điện hoá khi sử dụng sau khoảng thời gian thì suất điện động và điện trở trong thay đổi và đến một mức nào đó sẽ cần thay pin mới. Làm thế nào đo được suất điện động và điện trở trong của pin điện hoá bằng dụng cụ thí nghiệm?*",
    "",
    "## I. DỤNG CỤ THÍ NGHIỆM",
    "- Hai pin điện hoá loại 1,5 V (một pin cũ đã sử dụng gần hết điện, một pin mới chưa sử dụng) (1).",
    "- Một biến trở 100 $\\Omega$ (2).",
    "- Hai đồng hồ đo điện đa năng hiện số (3).",
    "- Dây nối (4).",
    "- Công tắc điện K (5).",
    "- Điện trở bảo vệ $R_0$ (6).",
    "- Bảng lắp mạch điện (7).",
    "[Hình 26.1. Bộ thí nghiệm đo suất điện động và điện trở trong của pin điện hoá. Gồm các dụng cụ từ (1) đến (7)]",
    "",
    "## II. THIẾT KẾ PHƯƠNG ÁN THÍ NGHIỆM",
    "**Hoạt động:**",
    "Hãy trả lời các câu hỏi sau:",
    "a) Có thể sử dụng đồng hồ đo điện đa năng để đo trực tiếp suất điện động của nguồn điện và điện trở trong của nguồn không? Tại sao?",
    "b) Để xác định suất điện động và điện trở trong của pin cần đo các đại lượng nào?",
    "c) Thiết kế phương án thí nghiệm để đo suất điện động và điện trở trong của pin điện hoá.",
    "",
    "111",
    "CHƯƠNG IV – DÒNG ĐIỆN. MẠCH ĐIỆN",
    "",
    "## III. TIẾN HÀNH THÍ NGHIỆM",
    "A. Tiến hành thí nghiệm với nguồn điện là một pin cũ.",
    "1. Bố trí thí nghiệm như Hình 26.2.",
    "2. Điều chỉnh biến trở đến giá trị 100 $\\Omega$.",
    "3. Đóng khoá K, bật đồng hồ đo hiệu điện thế và cường độ dòng điện.",
    "4. Ghi giá trị hiệu điện thế U và cường độ dòng điện I vào mẫu Bảng 26.1. Ngắt khóa K.",
    "5. Lặp lại 4 lần các bước 2, 3, 4 với giá trị R giảm dần.",
    "6. Đánh dấu các điểm thực nghiệm lên hệ trục tọa độ và vẽ đường thẳng đi gần nhất các điểm thực nghiệm (tham khảo Hình 26.3)",
    "7. Kéo dài đường đồ thị cắt trục tung tại $U_0$ (tham khảo Hình 26.3).",
    "8. Xác định suất điện động $\\mathscr{E}$ của pin là giá trị $U_0$.",
    "9. Chọn hai điểm M, N trên đồ thị xác định các giá trị U, I tương ứng và xác định điện trở trong theo công thức:",
    "$r = \\frac{U_M - U_N}{I_N - I_M}$",
    "10. Ước lượng sai số bằng đồ thị.",
    "",
    "B. Tiến hành thí nghiệm với nguồn điện là một pin mới.",
    "1. Thay nguồn điện bằng pin mới.",
    "2. Lặp lại các bước thí nghiệm như thí nghiệm với pin cũ, và ghi số liệu vào Bảng 26.2, vẽ đồ thị U = f(I) và xác định suất điện động, điện trở trong của pin.",
    "",
    "[Hình 26.2. Sơ đồ mạch điện thí nghiệm đo suất điện động và điện trở trong của pin điện hoá]",
    "",
    "*Bảng 26.1. Kết quả đo với pin cũ*",
    "| Số thứ tự | R ($\\Omega$) | U (V) | I (mA) |",
    "|---|---|---|---|",
    "| 1 | ? | ? | ? |",
    "| 2 | ? | ? | ? |",
    "| 3 | ? | ? | ? |",
    "| 4 | ? | ? | ? |",
    "| 5 | ? | ? | ? |",
    "$I = 0 \\Rightarrow U_0 = \\mathscr{E} = ...$",
    "$r = ... \\quad \\Delta r = ...$",
    "",
    "*Bảng 26.2. Kết quả đo với pin mới*",
    "| Số thứ tự | R ($\\Omega$) | U (V) | I (mA) |",
    "|---|---|---|---|",
    "| 1 | ? | ? | ? |",
    "| 2 | ? | ? | ? |",
    "| 3 | ? | ? | ? |",
    "| 4 | ? | ? | ? |",
    "| 5 | ? | ? | ? |",
    "$I = 0 \\Rightarrow U_0 = \\mathscr{E} = ...$",
    "$r = ... \\quad \\Delta r = ...$",
    "",
    "## IV. KẾT QUẢ THÍ NGHIỆM",
    "[Hình 26.3. Đồ thị quan hệ U và I với pin mới]",
    "",
    "112",
    "CHƯƠNG IV – DÒNG ĐIỆN. MẠCH ĐIỆN",
    "",
    "**Hoạt động:**",
    "Nhận xét và đánh giá kết quả thí nghiệm",
    "1. Nhận xét về dạng đồ thị và mối quan hệ U và I đối với pin cũ và pin mới.",
    "2. Em có thể đề xuất một phương án thí nghiệm khác để có thể đo suất điện động và điện trở.",
    "",
    "**EM ĐÃ HỌC**",
    "Xác định suất điện động và điện trở trong của một pin hoặc ắc quy bằng dụng cụ thí nghiệm.",
    "",
    "**EM CÓ THỂ**",
    "Giải thích tại sao trong khi tiến hành thí nghiệm không nên đóng mạch điện trong thời gian dài.",
    "",
    "**EM CÓ BIẾT**",
    "Pin lithium-ion là loại pin được dùng phổ biến trong điện thoại di động, máy tính xách tay, xe máy điện, ô tô điện, thậm chí trong tàu ngầm sử dụng động cơ điện. Pin lithium-ion có khối lượng nhẹ, khả năng lưu trữ điện năng lớn, sạc điện nhanh và sạc được nhiều lần.",
    "Công nghệ xe điện đang được phát triển tại Việt Nam, phần lớn năng lượng điện sử dụng pin lithium-ion. Mỗi pin có suất điện động khoảng 3,2 V được ghép thành bộ pin có suất điện động 48 V, 60 V, 72 V hoặc cao hơn để sử dụng trong các loại xe khác nhau.",
    "",
    "113",
    "# GIẢI THÍCH MỘT SỐ THUẬT NGỮ DÙNG TRONG SÁCH",
    "",
    "| THUẬT NGỮ | TRANG |",
    "|---|---|",
    "| *Công tơ điện:* là thiết bị dùng để đo lượng điện năng của một hoặc nhiều thiết bị tiêu thụ điện. | 107 |",
    "| *Dao động cơ:* là chuyển động của một vật qua lại quanh một vị trí cân bằng. | 6 |",
    "| *Dao động cưỡng bức:* là dao động của một hệ chịu tác dụng của một ngoại lực tuần hoàn. | 26 |",
    "| *Dao động điều hoà:* là dao động trong đó li độ của vật là một hàm cosin (hay sin) của thời gian. | 6 |",
    "| *Dao động tắt dần:* là dao động có biên độ của nó giảm dần theo thời gian. | 25 |",
    "| *Điện phổ:* là hình ảnh hệ các đường sức điện được tạo ra khi đặt một hoặc vài điện tích vào trong một bể chứa dầu đã được trộn đều các hạt cách điện. | 72 |",
    "| *Điện trở nhiệt:* là loại linh kiện điện tử có giá trị điện trở thay đổi một cách rõ rệt dưới tác dụng nhiệt. | 102 |",
    "| *Điện trở NTC (Negative Temperature Coefficient):* là loại nhiệt điện trở có điện trở giảm khi nhiệt độ tăng. | 99 |",
    "| *Điện trở PTC (Positive Temperature Coefficient):* là loại nhiệt điện trở có điện trở tăng khi nhiệt độ tăng. | 100 |",
    "| *Điện trường:* là dạng vật chất tồn tại quanh điện tích và truyền tương tác giữa các điện tích. | 62 |",
    "| *Hiện tượng cộng hưởng:* là hiện tượng biên độ dao động cưỡng bức tăng đến giá trị cực đại khi tần số f của lực cưỡng bức tiến đến bằng tần số tự nhiên $f_0$ của hệ dao động. | 25 |",
    "| *Hiện tượng giao thoa:* là hiện tượng khi hai sóng kết hợp gặp nhau thì có những điểm ở đó chúng luôn tăng cường lẫn nhau có những điểm ở đó chúng triệt tiêu nhau. | 50 |",
    "| *Nguồn điện:* là các thiết bị điện có khả năng cung cấp dòng điện lâu dài cho thiết bị sử dụng điện hoạt động. | 105 |",
    "| *Sóng cơ:* là những biến dạng cơ (hay dao động cơ) lan truyền trong một môi trường đàn hồi. | 32 |",
    "| *Sóng điện từ:* là sự lan truyền các dao động điện từ trong không gian. | 45 |",
    "",
    "114",
    "| THUẬT NGỮ | TRANG |",
    "|---|---|",
    "| *Sóng dọc:* là sóng trong đó các phần tử của môi trường dao động theo phương trùng với phương truyền sóng gọi là sóng dọc. | 38 |",
    "| *Sóng dừng:* là sự tổng hợp các sóng tới và sóng phản xạ giao thoa với nhau. | 54 |",
    "| *Sóng ngang:* là sóng trong đó các phần tử của môi trường dao động theo phương vuông góc với phương truyền sóng. | 38 |",
    "| *Suất điện động:* của nguồn điện là đại lượng đặc trưng cho khả năng thực hiện công của nguồn điện và đo bằng thương số giữa công của lực lạ thực hiện khi làm dịch chuyển một điện tích dương bên trong nguồn điện từ cực âm đến cực dương và độ lớn của điện tích đó. | 105 |",
    "| *Tia hồng ngoại:* là sóng điện từ không nhìn thấy, có bước sóng nằm trong khoảng từ 0,76 $\\mu$m đến 1 mm. | 46 |",
    "| *Tia tử ngoại:* là sóng điện từ không nhìn thấy, có bước sóng nằm trong khoảng từ 1 nm đến 0,38 $\\mu$m. | 47 |",
    "| *Tia X:* là sóng điện từ có bước sóng nhỏ hơn tia tử ngoại (từ $10^{-8}$ m đến $10^{-12}$ m). | 48 |",
    "| *Tụ điện:* là một loại linh kiện điện tử gồm hai vật dẫn đặt gần nhau và ngăn cách nhau bởi môi trường cách điện. | 86 |",
